    "verse_number": 79,
    "content":
        "فويل للذين يكتبون الكتب بايديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا فويل لهم مما كتبت ايديهم وويل لهم مما يكسبون",
  },
  {
    "surah_number": 2,
    "verse_number": 80,
    "content":
        "وقالوا لن تمسنا النار الا اياما معدودة قل اتخذتم عند الله عهدا فلن يخلف الله عهده ام تقولون على الله ما لا تعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 81,
    "content":
        "بلى من كسب سيئة واحطت به خطيـته فاولـئك اصحب النار هم فيها خلدون",
  },
  {
    "surah_number": 2,
    "verse_number": 82,
    "content": "والذين ءامنوا وعملوا الصـلحت اولـئك اصحب الجنة هم فيها خلدون",
  },
  {
    "surah_number": 2,
    "verse_number": 83,
    "content":
        "واذ اخذنا ميثق بني اسرـءيل لا تعبدون الا الله وبالولدين احسانا وذي القربى واليتمى والمسكين وقولوا للناس حسنا واقيموا الصلاة وءاتوا الزكوة ثم توليتم الا قليلا منكم وانتم معرضون",
  },
  {
    "surah_number": 2,
    "verse_number": 84,
    "content":
        "واذ اخذنا ميثقكم لا تسفكون دماءكم ولا تخرجون انفسكم من ديركم ثم اقررتم وانتم تشهدون",
  },
  {
    "surah_number": 2,
    "verse_number": 85,
    "content":
        "ثم انتم هـؤلاء تقتلون انفسكم وتخرجون فريقا منكم من ديرهم تظهرون عليهم بالاثم والعدون وان ياتوكم اسرى تفدوهم وهو محرم عليكم اخراجهم افتؤمنون ببعض الكتب وتكفرون ببعض فما جزاء من يفعل ذلك منكم الا خزي في الحيوة الدنيا ويوم القيمة يردون الى اشد العذاب وما الله بغفل عما تعملون",
  },
  {
    "surah_number": 2,
    "verse_number": 86,
    "content":
        "اولـئك الذين اشتروا الحيوة الدنيا بالاخرة فلا يخفف عنهم العذاب ولا هم ينصرون",
  },
  {
    "surah_number": 2,
    "verse_number": 87,
    "content":
        "ولقد ءاتينا موسى الكتب وقفينا من بعده بالرسل وءاتينا عيسى ابن مريم البينت وايدنه بروح القدس افكلما جاءكم رسول بما لا تهوى انفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون",
  },
  {
    "surah_number": 2,
    "verse_number": 88,
    "content": "وقالوا قلوبنا غلف بل لعنهم الله بكفرهم فقليلا ما يؤمنون",
  },
  {
    "surah_number": 2,
    "verse_number": 89,
    "content":
        "ولما جاءهم كتب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون على الذين كفروا فلما جاءهم ما عرفوا كفروا به فلعنة الله على الكفرين",
  },
  {
    "surah_number": 2,
    "verse_number": 90,
    "content":
        "بئسما اشتروا به انفسهم ان يكفروا بما انزل الله بغيا ان ينزل الله من فضله على من يشاء من عباده فباءو بغضب على غضب وللكفرين عذاب مهين",
  },
  {
    "surah_number": 2,
    "verse_number": 91,
    "content":
        "واذا قيل لهم ءامنوا بما انزل الله قالوا نؤمن بما انزل علينا ويكفرون بما وراءه وهو الحق مصدقا لما معهم قل فلم تقتلون انبياء الله من قبل ان كنتم مؤمنين",
  },
  {
    "surah_number": 2,
    "verse_number": 92,
    "content": "ولقد جاءكم موسى بالبينت ثم اتخذتم العجل من بعده وانتم ظلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 93,
    "content":
        "واذ اخذنا ميثقكم ورفعنا فوقكم الطور خذوا ما ءاتينكم بقوة واسمعوا قالوا سمعنا وعصينا واشربوا في قلوبهم العجل بكفرهم قل بئسما يامركم به ايمنكم ان كنتم مؤمنين",
  },
  {
    "surah_number": 2,
    "verse_number": 94,
    "content":
        "قل ان كانت لكم الدار الاخرة عند الله خالصة من دون الناس فتمنوا الموت ان كنتم صدقين",
  },
  {
    "surah_number": 2,
    "verse_number": 95,
    "content": "ولن يتمنوه ابدا بما قدمت ايديهم والله عليم بالظـلمين",
  },
  {
    "surah_number": 2,
    "verse_number": 96,
    "content":
        "ولتجدنهم احرص الناس على حيوة ومن الذين اشركوا يود احدهم لو يعمر الف سنة وما هو بمزحزحه من العذاب ان يعمر والله بصير بما يعملون",
  },
  {
    "surah_number": 2,
    "verse_number": 97,
    "content":
        "قل من كان عدوا لـجبريل فانه نزله على قلبك باذن الله مصدقا لما بين يديه وهدى وبشرى للمؤمنين",
  },
  {
    "surah_number": 2,
    "verse_number": 98,
    "content":
        "من كان عدوا لله وملـئكته ورسله وجبريل وميكىل فان الله عدو للكفرين",
  },
  {
    "surah_number": 2,
    "verse_number": 99,
    "content": "ولقد انزلنا اليك ءايت بينت وما يكفر بها الا الفسقون",
  },
  {
    "surah_number": 2,
    "verse_number": 100,
    "content": "اوكلما عهدوا عهدا نبذه فريق منهم بل اكثرهم لا يؤمنون",
  },
  {
    "surah_number": 2,
    "verse_number": 101,
    "content":
        "ولما جاءهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين اوتوا الكتب كتب الله وراء ظهورهم كانهم لا يعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 102,
    "content":
        "واتبعوا ما تتلوا الشيطين على ملك سليمن وما كفر سليمن ولكن الشيطين كفروا يعلمون الناس السحر وما انزل على الملكين ببابل هروت ومروت وما يعلمان من احد حتى يقولا انما نحن فتنة فلا تكفر فيتعلمون منهما ما يفرقون به بين المرء وزوجه وما هم بضارين به من احد الا باذن الله ويتعلمون ما يضرهم ولا ينفعهم ولقد علموا لمن اشترىه ما له في الاخرة من خلق ولبئس ما شروا به انفسهم لو كانوا يعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 103,
    "content": "ولو انهم ءامنوا واتقوا لمثوبة من عند الله خير لو كانوا يعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 104,
    "content":
        "يـايها الذين ءامنوا لا تقولوا رعنا وقولوا انظرنا واسمعوا وللكفرين عذاب اليم",
  },
  {
    "surah_number": 2,
    "verse_number": 105,
    "content":
        "ما يود الذين كفروا من اهل الكتب ولا المشركين ان ينزل عليكم من خير من ربكم والله يختص برحمته من يشاء والله ذو الفضل العظيم",
  },
  {
    "surah_number": 2,
    "verse_number": 106,
    "content":
        "ما ننسخ من ءاية او ننسها نات بخير منها او مثلها الم تعلم ان الله على كل شيء قدير",
  },
  {
    "surah_number": 2,
    "verse_number": 107,
    "content":
        "الم تعلم ان الله له ملك السموت والارض وما لكم من دون الله من ولي ولا نصير",
  },
  {
    "surah_number": 2,
    "verse_number": 108,
    "content":
        "ام تريدون ان تسـلوا رسولكم كما سئل موسى من قبل ومن يتبدل الكفر بالايمن فقد ضل سواء السبيل",
  },
  {
    "surah_number": 2,
    "verse_number": 109,
    "content":
        "ود كثير من اهل الكتب لو يردونكم من بعد ايمنكم كفارا حسدا من عند انفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتى ياتي الله بامره ان الله على كل شيء قدير",
  },
  {
    "surah_number": 2,
    "verse_number": 110,
    "content":
        "واقيموا الصلاة وءاتوا الزكوة وما تقدموا لانفسكم من خير تجدوه عند الله ان الله بما تعملون بصير",
  },
  {
    "surah_number": 2,
    "verse_number": 111,
    "content":
        "وقالوا لن يدخل الجنة الا من كان هودا او نصرى تلك امانيهم قل هاتوا برهنكم ان كنتم صدقين",
  },
  {
    "surah_number": 2,
    "verse_number": 112,
    "content":
        "بلى من اسلم وجهه لله وهو محسن فله اجره عند ربه ولا خوف عليهم ولا هم يحزنون",
  },
  {
    "surah_number": 2,
    "verse_number": 113,
    "content":
        "وقالت اليهود ليست النصرى على شيء وقالت النصرى ليست اليهود على شيء وهم يتلون الكتب كذلك قال الذين لا يعلمون مثل قولهم فالله يحكم بينهم يوم القيمة فيما كانوا فيه يختلفون",
  },
  {
    "surah_number": 2,
    "verse_number": 114,
    "content":
        "ومن اظلم ممن منع مسجد الله ان يذكر فيها اسمه وسعى في خرابها اولـئك ما كان لهم ان يدخلوها الا خائفين لهم في الدنيا خزي ولهم في الاخرة عذاب عظيم",
  },
  {
    "surah_number": 2,
    "verse_number": 115,
    "content": "ولله المشرق والمغرب فاينما تولوا فثم وجه الله ان الله وسع عليم",
  },
  {
    "surah_number": 2,
    "verse_number": 116,
    "content":
        "وقالوا اتخذ الله ولدا سبحنه بل له ما في السموت والارض كل له قنتون",
  },
  {
    "surah_number": 2,
    "verse_number": 117,
    "content": "بديع السموت والارض واذا قضى امرا فانما يقول له كن فيكون",
  },
  {
    "surah_number": 2,
    "verse_number": 118,
    "content":
        "وقال الذين لا يعلمون لولا يكلمنا الله او تاتينا ءاية كذلك قال الذين من قبلهم مثل قولهم تشبهت قلوبهم قد بينا الايت لقوم يوقنون",
  },
  {
    "surah_number": 2,
    "verse_number": 119,
    "content": "انا ارسلنك بالحق بشيرا ونذيرا ولا تسـل عن اصحب الجحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 120,
    "content":
        "ولن ترضى عنك اليهود ولا النصرى حتى تتبع ملتهم قل ان هدى الله هو الهدى ولئن اتبعت اهواءهم بعد الذي جاءك من العلم ما لك من الله من ولي ولا نصير",
  },
  {
    "surah_number": 2,
    "verse_number": 121,
    "content":
        "الذين ءاتينهم الكتب يتلونه حق تلاوته اولـئك يؤمنون به ومن يكفر به فاولـئك هم الخسرون",
  },
  {
    "surah_number": 2,
    "verse_number": 122,
    "content":
        "يبني اسرـءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم على العلمين",
  },
  {
    "surah_number": 2,
    "verse_number": 123,
    "content":
        "واتقوا يوما لا تجزي نفس عن نفس شيـا ولا يقبل منها عدل ولا تنفعها شفعة ولا هم ينصرون",
  },
  {
    "surah_number": 2,
    "verse_number": 124,
    "content":
        "واذ ابتلى ابرهـم ربه بكلمت فاتمهن قال اني جاعلك للناس اماما قال ومن ذريتي قال لا ينال عهدي الظـلمين",
  },
  {
    "surah_number": 2,
    "verse_number": 125,
    "content":
        "واذ جعلنا البيت مثابة للناس وامنا واتخذوا من مقام ابرهـم مصلى وعهدنا الى ابرهـم واسمعيل ان طهرا بيتي للطائفين والعكفين والركع السجود",
  },
  {
    "surah_number": 2,
    "verse_number": 126,
    "content":
        "واذ قال ابرهـم رب اجعل هذا بلدا ءامنا وارزق اهله من الثمرت من ءامن منهم بالله واليوم الاخر قال ومن كفر فامتعه قليلا ثم اضطره الى عذاب النار وبئس المصير",
  },
  {
    "surah_number": 2,
    "verse_number": 127,
    "content":
        "واذ يرفع ابرهـم القواعد من البيت واسمعيل ربنا تقبل منا انك انت السميع العليم",
  },
  {
    "surah_number": 2,
    "verse_number": 128,
    "content":
        "ربنا واجعلنا مسلمين لك ومن ذريتنا امة مسلمة لك وارنا مناسكنا وتب علينا انك انت التواب الرحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 129,
    "content":
        "ربنا وابعث فيهم رسولا منهم يتلوا عليهم ءايتك ويعلمهم الكتب والحكمة ويزكيهم انك انت العزيز الحكيم",
  },
  {
    "surah_number": 2,
    "verse_number": 130,
    "content":
        "ومن يرغب عن ملة ابرهـم الا من سفه نفسه ولقد اصطفينه في الدنيا وانه في الاخرة لمن الصـلحين",
  },
  {
    "surah_number": 2,
    "verse_number": 131,
    "content": "اذ قال له ربه اسلم قال اسلمت لرب العلمين",
  },
  {
    "surah_number": 2,
    "verse_number": 132,
    "content":
        "ووصى بها ابرهـم بنيه ويعقوب يبني ان الله اصطفى لكم الدين فلا تموتن الا وانتم مسلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 133,
    "content":
        "ام كنتم شهداء اذ حضر يعقوب الموت اذ قال لبنيه ما تعبدون من بعدي قالوا نعبد الهك واله ءابائك ابرهـم واسمعيل واسحق الها وحدا ونحن له مسلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 134,
    "content":
        "تلك امة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسـلون عما كانوا يعملون",
  },
  {
    "surah_number": 2,
    "verse_number": 135,
    "content":
        "وقالوا كونوا هودا او نصرى تهتدوا قل بل ملة ابرهـم حنيفا وما كان من المشركين",
  },
  {
    "surah_number": 2,
    "verse_number": 136,
    "content":
        "قولوا ءامنا بالله وما انزل الينا وما انزل الى ابرهـم واسمعيل واسحق ويعقوب والاسباط وما اوتي موسى وعيسى وما اوتي النبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 137,
    "content":
        "فان ءامنوا بمثل ما ءامنتم به فقد اهتدوا وان تولوا فانما هم في شقاق فسيكفيكهم الله وهو السميع العليم",
  },
  {
    "surah_number": 2,
    "verse_number": 138,
    "content": "صبغة الله ومن احسن من الله صبغة ونحن له عبدون",
  },
  {
    "surah_number": 2,
    "verse_number": 139,
    "content":
        "قل اتحاجوننا في الله وهو ربنا وربكم ولنا اعملنا ولكم اعملكم ونحن له مخلصون",
  },
  {
    "surah_number": 2,
    "verse_number": 140,
    "content":
        "ام تقولون ان ابرهـم واسمعيل واسحق ويعقوب والاسباط كانوا هودا او نصرى قل ءانتم اعلم ام الله ومن اظلم ممن كتم شهدة عنده من الله وما الله بغفل عما تعملون",
  },
  {
    "surah_number": 2,
    "verse_number": 141,
    "content":
        "تلك امة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسـلون عما كانوا يعملون",
  },
  {
    "surah_number": 2,
    "verse_number": 142,
    "content":
        "سيقول السفهاء من الناس ما ولىهم عن قبلتهم التي كانوا عليها قل لله المشرق والمغرب يهدي من يشاء الى صراط مستقيم",
  },
  {
    "surah_number": 2,
    "verse_number": 143,
    "content":
        "وكذلك جعلنكم امة وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا وما جعلنا القبلة التي كنت عليها الا لنعلم من يتبع الرسول ممن ينقلب على عقبيه وان كانت لكبيرة الا على الذين هدى الله وما كان الله ليضيع ايمنكم ان الله بالناس لرءوف رحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 144,
    "content":
        "قد نرى تقلب وجهك في السماء فلنولينك قبلة ترضىها فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره وان الذين اوتوا الكتب ليعلمون انه الحق من ربهم وما الله بغفل عما يعملون",
  },
  {
    "surah_number": 2,
    "verse_number": 145,
    "content":
        "ولئن اتيت الذين اوتوا الكتب بكل ءاية ما تبعوا قبلتك وما انت بتابع قبلتهم وما بعضهم بتابع قبلة بعض ولئن اتبعت اهواءهم من بعد ما جاءك من العلم انك اذا لمن الظـلمين",
  },
  {
    "surah_number": 2,
    "verse_number": 146,
    "content":
        "الذين ءاتينهم الكتب يعرفونه كما يعرفون ابناءهم وان فريقا منهم ليكتمون الحق وهم يعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 147,
    "content": "الحق من ربك فلا تكونن من الممترين",
  },
  {
    "surah_number": 2,
    "verse_number": 148,
    "content":
        "ولكل وجهة هو موليها فاستبقوا الخيرت اين ما تكونوا يات بكم الله جميعا ان الله على كل شيء قدير",
  },
  {
    "surah_number": 2,
    "verse_number": 149,
    "content":
        "ومن حيث خرجت فول وجهك شطر المسجد الحرام وانه للحق من ربك وما الله بغفل عما تعملون",
  },
  {
    "surah_number": 2,
    "verse_number": 150,
    "content":
        "ومن حيث خرجت فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره لئلا يكون للناس عليكم حجة الا الذين ظلموا منهم فلا تخشوهم واخشوني ولاتم نعمتي عليكم ولعلكم تهتدون",
  },
  {
    "surah_number": 2,
    "verse_number": 151,
    "content":
        "كما ارسلنا فيكم رسولا منكم يتلوا عليكم ءايتنا ويزكيكم ويعلمكم الكتب والحكمة ويعلمكم ما لم تكونوا تعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 152,
    "content": "فاذكروني اذكركم واشكروا لي ولا تكفرون",
  },
  {
    "surah_number": 2,
    "verse_number": 153,
    "content":
        "يـايها الذين ءامنوا استعينوا بالصبر والصلاة ان الله مع الصـبرين",
  },
  {
    "surah_number": 2,
    "verse_number": 154,
    "content": "ولا تقولوا لمن يقتل في سبيل الله اموت بل احياء ولكن لا تشعرون",
  },
  {
    "surah_number": 2,
    "verse_number": 155,
    "content":
        "ولنبلونكم بشيء من الخوف والجوع ونقص من الامول والانفس والثمرت وبشر الصـبرين",
  },
  {
    "surah_number": 2,
    "verse_number": 156,
    "content": "الذين اذا اصبتهم مصيبة قالوا انا لله وانا اليه رجعون",
  },
  {
    "surah_number": 2,
    "verse_number": 157,
    "content": "اولـئك عليهم صلوت من ربهم ورحمة واولـئك هم المهتدون",
  },
  {
    "surah_number": 2,
    "verse_number": 158,
    "content":
        "ان الصفا والمروة من شعائر الله فمن حج البيت او اعتمر فلا جناح عليه ان يطوف بهما ومن تطوع خيرا فان الله شاكر عليم",
  },
  {
    "surah_number": 2,
    "verse_number": 159,
    "content":
        "ان الذين يكتمون ما انزلنا من البينت والهدى من بعد ما بينـه للناس في الكتب اولـئك يلعنهم الله ويلعنهم اللـعنون",
  },
  {
    "surah_number": 2,
    "verse_number": 160,
    "content":
        "الا الذين تابوا واصلحوا وبينوا فاولـئك اتوب عليهم وانا التواب الرحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 161,
    "content":
        "ان الذين كفروا وماتوا وهم كفار اولـئك عليهم لعنة الله والملـئكة والناس اجمعين",
  },
  {
    "surah_number": 2,
    "verse_number": 162,
    "content": "خلدين فيها لا يخفف عنهم العذاب ولا هم ينظرون",
  },
  {
    "surah_number": 2,
    "verse_number": 163,
    "content": "والهكم اله وحد لا اله الا هو الرحمن الرحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 164,
    "content":
        "ان في خلق السموت والارض واختلف اليل والنهار والفلك التي تجري في البحر بما ينفع الناس وما انزل الله من السماء من ماء فاحيا به الارض بعد موتها وبث فيها من كل دابة وتصريف الريح والسحاب المسخر بين السماء والارض لايت لقوم يعقلون",
  },
  {
    "surah_number": 2,
    "verse_number": 165,
    "content":
        "ومن الناس من يتخذ من دون الله اندادا يحبونهم كحب الله والذين ءامنوا اشد حبا لله ولو يرى الذين ظلموا اذ يرون العذاب ان القوة لله جميعا وان الله شديد العذاب",
  },
  {
    "surah_number": 2,
    "verse_number": 166,
    "content":
        "اذ تبرا الذين اتبعوا من الذين اتبعوا وراوا العذاب وتقطعت بهم الاسباب",
  },
  {
    "surah_number": 2,
    "verse_number": 167,
    "content":
        "وقال الذين اتبعوا لو ان لنا كرة فنتبرا منهم كما تبرءوا منا كذلك يريهم الله اعملهم حسرت عليهم وما هم بخرجين من النار",
  },
  {
    "surah_number": 2,
    "verse_number": 168,
    "content":
        "يـايها الناس كلوا مما في الارض حللا طيبا ولا تتبعوا خطوت الشيطن انه لكم عدو مبين",
  },
  {
    "surah_number": 2,
    "verse_number": 169,
    "content": "انما يامركم بالسوء والفحشاء وان تقولوا على الله ما لا تعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 170,
    "content":
        "واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما الفينا عليه ءاباءنا اولو كان ءاباؤهم لا يعقلون شيـا ولا يهتدون",
  },
  {
    "surah_number": 2,
    "verse_number": 171,
    "content":
        "ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع الا دعاء ونداء صم بكم عمي فهم لا يعقلون",
  },
  {
    "surah_number": 2,
    "verse_number": 172,
    "content":
        "يـايها الذين ءامنوا كلوا من طيبت ما رزقنكم واشكروا لله ان كنتم اياه تعبدون",
  },
  {
    "surah_number": 2,
    "verse_number": 173,
    "content":
        "انما حرم عليكم الميتة والدم ولحم الخنزير وما اهل به لغير الله فمن اضطر غير باغ ولا عاد فلا اثم عليه ان الله غفور رحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 174,
    "content":
        "ان الذين يكتمون ما انزل الله من الكتب ويشترون به ثمنا قليلا اولـئك ما ياكلون في بطونهم الا النار ولا يكلمهم الله يوم القيمة ولا يزكيهم ولهم عذاب اليم",
  },
  {
    "surah_number": 2,
    "verse_number": 175,
    "content":
        "اولـئك الذين اشتروا الضللة بالهدى والعذاب بالمغفرة فما اصبرهم على النار",
  },
  {
    "surah_number": 2,
    "verse_number": 176,
    "content":
        "ذلك بان الله نزل الكتب بالحق وان الذين اختلفوا في الكتب لفي شقاق بعيد",
  },
  {
    "surah_number": 2,
    "verse_number": 177,
    "content":
        "ليس البر ان تولوا وجوهكم قبل المشرق والمغرب ولكن البر من ءامن بالله واليوم الاخر والملـئكة والكتب والنبيـن وءاتى المال على حبه ذوي القربى واليتمى والمسكين وابن السبيل والسائلين وفي الرقاب واقام الصلاة وءاتى الزكوة والموفون بعهدهم اذا عهدوا والصـبرين في الباساء والضراء وحين الباس اولـئك الذين صدقوا واولـئك هم المتقون",
  },
  {
    "surah_number": 2,
    "verse_number": 178,
    "content":
        "يـايها الذين ءامنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والانثى بالانثى فمن عفي له من اخيه شيء فاتباع بالمعروف واداء اليه باحسن ذلك تخفيف من ربكم ورحمة فمن اعتدى بعد ذلك فله عذاب اليم",
  },
  {
    "surah_number": 2,
    "verse_number": 179,
    "content": "ولكم في القصاص حيوة يـاولي الالبب لعلكم تتقون",
  },
  {
    "surah_number": 2,
    "verse_number": 180,
    "content":
        "كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصية للولدين والاقربين بالمعروف حقا على المتقين",
  },
  {
    "surah_number": 2,
    "verse_number": 181,
    "content":
        "فمن بدله بعد ما سمعه فانما اثمه على الذين يبدلونه ان الله سميع عليم",
  },
  {
    "surah_number": 2,
    "verse_number": 182,
    "content":
        "فمن خاف من موص جنفا او اثما فاصلح بينهم فلا اثم عليه ان الله غفور رحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 183,
    "content":
        "يـايها الذين ءامنوا كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون",
  },
  {
    "surah_number": 2,
    "verse_number": 184,
    "content":
        "اياما معدودت فمن كان منكم مريضا او على سفر فعدة من ايام اخر وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وان تصوموا خير لكم ان كنتم تعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 185,
    "content":
        "شهر رمضان الذي انزل فيه القرءان هدى للناس وبينت من الهدى والفرقان فمن شهد منكم الشهر فليصمه ومن كان مريضا او على سفر فعدة من ايام اخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العدة ولتكبروا الله على ما هدىكم ولعلكم تشكرون",
  },
  {
    "surah_number": 2,
    "verse_number": 186,
    "content":
        "واذا سالك عبادي عني فاني قريب اجيب دعوة الداع اذا دعان فليستجيبوا لي وليؤمنوا بي لعلهم يرشدون",
  },
  {
    "surah_number": 2,
    "verse_number": 187,
    "content":
        "احل لكم ليلة الصيام الرفث الى نسائكم هن لباس لكم وانتم لباس لهن علم الله انكم كنتم تختانون انفسكم فتاب عليكم وعفا عنكم فالـن بشروهن وابتغوا ما كتب الله لكم وكلوا واشربوا حتى يتبين لكم الخيط الابيض من الخيط الاسود من الفجر ثم اتموا الصيام الى اليل ولا تبشروهن وانتم عكفون في المسجد تلك حدود الله فلا تقربوها كذلك يبين الله ءايته للناس لعلهم يتقون",
  },
  {
    "surah_number": 2,
    "verse_number": 188,
    "content":
        "ولا تاكلوا امولكم بينكم بالبطل وتدلوا بها الى الحكام لتاكلوا فريقا من امول الناس بالاثم وانتم تعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 189,
    "content":
        "يسـلونك عن الاهلة قل هي موقيت للناس والحج وليس البر بان تاتوا البيوت من ظهورها ولكن البر من اتقى واتوا البيوت من ابوبها واتقوا الله لعلكم تفلحون",
  },
  {
    "surah_number": 2,
    "verse_number": 190,
    "content":
        "وقتلوا في سبيل الله الذين يقتلونكم ولا تعتدوا ان الله لا يحب المعتدين",
  },
  {
    "surah_number": 2,
    "verse_number": 191,
    "content":
        "واقتلوهم حيث ثقفتموهم واخرجوهم من حيث اخرجوكم والفتنة اشد من القتل ولا تقتلوهم عند المسجد الحرام حتى يقتلوكم فيه فان قتلوكم فاقتلوهم كذلك جزاء الكفرين",
  },
  {
    "surah_number": 2,
    "verse_number": 192,
    "content": "فان انتهوا فان الله غفور رحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 193,
    "content":
        "وقتلوهم حتى لا تكون فتنة ويكون الدين لله فان انتهوا فلا عدون الا على الظـلمين",
  },
  {
    "surah_number": 2,
    "verse_number": 194,
    "content":
        "الشهر الحرام بالشهر الحرام والحرمت قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم واتقوا الله واعلموا ان الله مع المتقين",
  },
  {
    "surah_number": 2,
    "verse_number": 195,
    "content":
        "وانفقوا في سبيل الله ولا تلقوا بايديكم الى التهلكة واحسنوا ان الله يحب المحسنين",
  },
  {
    "surah_number": 2,
    "verse_number": 196,
    "content":
        "واتموا الحج والعمرة لله فان احصرتم فما استيسر من الهدي ولا تحلقوا رءوسكم حتى يبلغ الهدي محله فمن كان منكم مريضا او به اذى من راسه ففدية من صيام او صدقة او نسك فاذا امنتم فمن تمتع بالعمرة الى الحج فما استيسر من الهدي فمن لم يجد فصيام ثلثة ايام في الحج وسبعة اذا رجعتم تلك عشرة كاملة ذلك لمن لم يكن اهله حاضري المسجد الحرام واتقوا الله واعلموا ان الله شديد العقاب",
  },
  {
    "surah_number": 2,
    "verse_number": 197,
    "content":
        "الحج اشهر معلومت فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج وما تفعلوا من خير يعلمه الله وتزودوا فان خير الزاد التقوى واتقون يـاولي الالبب",
  },
  {
    "surah_number": 2,
    "verse_number": 198,
    "content":
        "ليس عليكم جناح ان تبتغوا فضلا من ربكم فاذا افضتم من عرفت فاذكروا الله عند المشعر الحرام واذكروه كما هدىكم وان كنتم من قبله لمن الضالين",
  },
  {
    "surah_number": 2,
    "verse_number": 199,
    "content": "ثم افيضوا من حيث افاض الناس واستغفروا الله ان الله غفور رحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 200,
    "content":
        "فاذا قضيتم منسككم فاذكروا الله كذكركم ءاباءكم او اشد ذكرا فمن الناس من يقول ربنا ءاتنا في الدنيا وما له في الاخرة من خلق",
  },
  {
    "surah_number": 2,
    "verse_number": 201,
    "content":
        "ومنهم من يقول ربنا ءاتنا في الدنيا حسنة وفي الاخرة حسنة وقنا عذاب النار",
  },
  {
    "surah_number": 2,
    "verse_number": 202,
    "content": "اولـئك لهم نصيب مما كسبوا والله سريع الحساب",
  },
  {
    "surah_number": 2,
    "verse_number": 203,
    "content":
        "واذكروا الله في ايام معدودت فمن تعجل في يومين فلا اثم عليه ومن تاخر فلا اثم عليه لمن اتقى واتقوا الله واعلموا انكم اليه تحشرون",
  },
  {
    "surah_number": 2,
    "verse_number": 204,
    "content":
        "ومن الناس من يعجبك قوله في الحيوة الدنيا ويشهد الله على ما في قلبه وهو الد الخصام",
  },
  {
    "surah_number": 2,
    "verse_number": 205,
    "content":
        "واذا تولى سعى في الارض ليفسد فيها ويهلك الحرث والنسل والله لا يحب الفساد",
  },
  {
    "surah_number": 2,
    "verse_number": 206,
    "content":
        "واذا قيل له اتق الله اخذته العزة بالاثم فحسبه جهنم ولبئس المهاد",
  },
  {
    "surah_number": 2,
    "verse_number": 207,
    "content": "ومن الناس من يشري نفسه ابتغاء مرضات الله والله رءوف بالعباد",
  },
  {
    "surah_number": 2,
    "verse_number": 208,
    "content":
        "يـايها الذين ءامنوا ادخلوا في السلم كافة ولا تتبعوا خطوت الشيطن انه لكم عدو مبين",
  },
  {
    "surah_number": 2,
    "verse_number": 209,
    "content": "فان زللتم من بعد ما جاءتكم البينت فاعلموا ان الله عزيز حكيم",
  },
  {
    "surah_number": 2,
    "verse_number": 210,
    "content":
        "هل ينظرون الا ان ياتيهم الله في ظلل من الغمام والملـئكة وقضي الامر والى الله ترجع الامور",
  },
  {
    "surah_number": 2,
    "verse_number": 211,
    "content":
        "سل بني اسرـءيل كم ءاتينهم من ءاية بينة ومن يبدل نعمة الله من بعد ما جاءته فان الله شديد العقاب",
  },
  {
    "surah_number": 2,
    "verse_number": 212,
    "content":
        "زين للذين كفروا الحيوة الدنيا ويسخرون من الذين ءامنوا والذين اتقوا فوقهم يوم القيمة والله يرزق من يشاء بغير حساب",
  },
  {
    "surah_number": 2,
    "verse_number": 213,
    "content":
        "كان الناس امة وحدة فبعث الله النبيـن مبشرين ومنذرين وانزل معهم الكتب بالحق ليحكم بين الناس فيما اختلفوا فيه وما اختلف فيه الا الذين اوتوه من بعد ما جاءتهم البينت بغيا بينهم فهدى الله الذين ءامنوا لما اختلفوا فيه من الحق باذنه والله يهدي من يشاء الى صراط مستقيم",
  },
  {
    "surah_number": 2,
    "verse_number": 214,
    "content":
        "ام حسبتم ان تدخلوا الجنة ولما ياتكم مثل الذين خلوا من قبلكم مستهم الباساء والضراء وزلزلوا حتى يقول الرسول والذين ءامنوا معه متى نصر الله الا ان نصر الله قريب",
  },
  {
    "surah_number": 2,
    "verse_number": 215,
    "content":
        "يسـلونك ماذا ينفقون قل ما انفقتم من خير فللولدين والاقربين واليتمى والمسكين وابن السبيل وما تفعلوا من خير فان الله به عليم",
  },
  {
    "surah_number": 2,
    "verse_number": 216,
    "content":
        "كتب عليكم القتال وهو كره لكم وعسى ان تكرهوا شيـا وهو خير لكم وعسى ان تحبوا شيـا وهو شر لكم والله يعلم وانتم لا تعلمون",
  },
  {
    "surah_number": 2,
    "verse_number": 217,
    "content":
        "يسـلونك عن الشهر الحرام قتال فيه قل قتال فيه كبير وصد عن سبيل الله وكفر به والمسجد الحرام واخراج اهله منه اكبر عند الله والفتنة اكبر من القتل ولا يزالون يقتلونكم حتى يردوكم عن دينكم ان استطعوا ومن يرتدد منكم عن دينه فيمت وهو كافر فاولـئك حبطت اعملهم في الدنيا والاخرة واولـئك اصحب النار هم فيها خلدون",
  },
  {
    "surah_number": 2,
    "verse_number": 218,
    "content":
        "ان الذين ءامنوا والذين هاجروا وجهدوا في سبيل الله اولـئك يرجون رحمت الله والله غفور رحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 219,
    "content":
        "يسـلونك عن الخمر والميسر قل فيهما اثم كبير ومنفع للناس واثمهما اكبر من نفعهما ويسـلونك ماذا ينفقون قل العفو كذلك يبين الله لكم الايت لعلكم تتفكرون",
  },
  {
    "surah_number": 2,
    "verse_number": 220,
    "content":
        "في الدنيا والاخرة ويسـلونك عن اليتمى قل اصلاح لهم خير وان تخالطوهم فاخونكم والله يعلم المفسد من المصلح ولو شاء الله لاعنتكم ان الله عزيز حكيم",
  },
  {
    "surah_number": 2,
    "verse_number": 221,
    "content":
        "ولا تنكحوا المشركت حتى يؤمن ولامة مؤمنة خير من مشركة ولو اعجبتكم ولا تنكحوا المشركين حتى يؤمنوا ولعبد مؤمن خير من مشرك ولو اعجبكم اولـئك يدعون الى النار والله يدعوا الى الجنة والمغفرة باذنه ويبين ءايته للناس لعلهم يتذكرون",
  },
  {
    "surah_number": 2,
    "verse_number": 222,
    "content":
        "ويسـلونك عن المحيض قل هو اذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فاذا تطهرن فاتوهن من حيث امركم الله ان الله يحب التوـبين ويحب المتطهرين",
  },
  {
    "surah_number": 2,
    "verse_number": 223,
    "content":
        "نساؤكم حرث لكم فاتوا حرثكم انى شئتم وقدموا لانفسكم واتقوا الله واعلموا انكم ملقوه وبشر المؤمنين",
  },
  {
    "surah_number": 2,
    "verse_number": 224,
    "content":
