  },
  {
    "surah_number": 2,
    "verse_number": 226,
    "content":
        "للذين يؤلون من نسائهم تربص اربعة اشهر فان فاءو فان الله غفور رحيم",
  },
  {
    "surah_number": 2,
    "verse_number": 227,
    "content": "وان عزموا الطلق فان الله سميع عليم",
