  },
  {
    "surah_number": 2,
    "verse_number": 246,
    "content":
        "الم تر الى الملا من بني اسرـءيل من بعد موسى اذ قالوا لنبي لهم ابعث لنا ملكا نقتل في سبيل الله قال هل عسيتم ان كتب عليكم القتال الا تقتلوا قالوا وما لنا الا نقتل في سبيل الله وقد اخرجنا من ديرنا وابنائنا فلما كتب عليهم القتال تولوا الا قليلا منهم والله عليم بالظـلمين",
  },
  {
    "surah_number": 2,
    "verse_number": 247,
