        "وقال لهم نبيهم ان الله قد بعث لكم طالوت ملكا قالوا انى يكون له الملك علينا ونحن احق بالملك منه ولم يؤت سعة من المال قال ان الله اصطفىه عليكم وزاده بسطة في العلم والجسم والله يؤتي ملكه من يشاء والله وسع عليم",
  },
  {
    "surah_number": 2,
