    "content":
        "فلما فصل طالوت بالجنود قال ان الله مبتليكم بنهر فمن شرب منه فليس مني ومن لم يطعمه فانه مني الا من اغترف غرفة بيده فشربوا منه الا قليلا منهم فلما جاوزه هو والذين ءامنوا معه قالوا لا طاقة لنا اليوم بجالوت وجنوده قال الذين يظنون انهم ملقوا الله كم من فئة قليلة غلبت فئة كثيرة باذن الله والله مع الصـبرين",
  },
  {
    "surah_number": 2,
