  },
  {
    "surah_number": 2,
    "verse_number": 258,
    "content":
        "الم تر الى الذي حاج ابرهـم في ربه ان ءاتىه الله الملك اذ قال ابرهـم ربي الذي يحي ويميت قال انا احي واميت قال ابرهـم فان الله ياتي بالشمس من المشرق فات بها من المغرب فبهت الذي كفر والله لا يهدي القوم الظـلمين",
  },
  {
    "surah_number": 2,
    "verse_number": 259,
    "content":
        "او كالذي مر على قرية وهي خاوية على عروشها قال انى يحي هذه الله بعد موتها فاماته الله مائة عام ثم بعثه قال كم لبثت قال لبثت يوما او بعض يوم قال بل لبثت مائة عام فانظر الى طعامك وشرابك لم يتسنه وانظر الى حمارك ولنجعلك ءاية للناس وانظر الى العظام كيف ننشزها ثم نكسوها لحما فلما تبين له قال اعلم ان الله على كل شيء قدير",
  },
  {
    "surah_number": 2,
