  },
  {
    "surah_number": 2,
    "verse_number": 266,
    "content":
        "ايود احدكم ان تكون له جنة من نخيل واعناب تجري من تحتها الانهر له فيها من كل الثمرت واصابه الكبر وله ذرية ضعفاء فاصابها اعصار فيه نار فاحترقت كذلك يبين الله لكم الايت لعلكم تتفكرون",
  },
  {
    "surah_number": 2,
