    "verse_number": 2,
    "content":
        "والذين ءامنوا وعملوا الصـلحت وءامنوا بما نزل على محمد وهو الحق من ربهم كفر عنهم سيـاتهم واصلح بالهم",
  },
  {
    "surah_number": 47,
    "verse_number": 3,
    "content":
        "ذلك بان الذين كفروا اتبعوا البطل وان الذين ءامنوا اتبعوا الحق من ربهم كذلك يضرب الله للناس امثلهم",
