    "verse_number": 12,
    "content":
        "ان الله يدخل الذين ءامنوا وعملوا الصـلحت جنـت تجري من تحتها الانهر والذين كفروا يتمتعون وياكلون كما تاكل الانعم والنار مثوى لهم",
  },
  {
    "surah_number": 47,
    "verse_number": 13,
    "content":
        "وكاين من قرية هي اشد قوة من قريتك التي اخرجتك اهلكنهم فلا ناصر لهم",
  },
  {
    "surah_number": 47,
    "verse_number": 14,
    "content": "افمن كان على بينة من ربه كمن زين له سوء عمله واتبعوا اهواءهم",
