    "verse_number": 15,
    "content":
        "مثل الجنة التي وعد المتقون فيها انهر من ماء غير ءاسن وانهر من لبن لم يتغير طعمه وانهر من خمر لذة للشـربين وانهر من عسل مصفى ولهم فيها من كل الثمرت ومغفرة من ربهم كمن هو خلد في النار وسقوا ماء حميما فقطع امعاءهم",
  },
  {
    "surah_number": 47,
    "verse_number": 16,
    "content":
        "ومنهم من يستمع اليك حتى اذا خرجوا من عندك قالوا للذين اوتوا العلم ماذا قال ءانفا اولـئك الذين طبع الله على قلوبهم واتبعوا اهواءهم",
  },
  {
    "surah_number": 47,
    "verse_number": 17,
    "content": "والذين اهتدوا زادهم هدى وءاتىهم تقوىهم",
  },
  {
    "surah_number": 47,
    "verse_number": 18,
    "content":
        "فهل ينظرون الا الساعة ان تاتيهم بغتة فقد جاء اشراطها فانى لهم اذا جاءتهم ذكرىهم",
  },
  {
    "surah_number": 47,
    "verse_number": 19,
    "content":
        "فاعلم انه لا اله الا الله واستغفر لذنبك وللمؤمنين والمؤمنت والله يعلم متقلبكم ومثوىكم",
  },
  {
    "surah_number": 47,
    "verse_number": 20,
    "content":
        "ويقول الذين ءامنوا لولا نزلت سورة فاذا انزلت سورة محكمة وذكر فيها القتال رايت الذين في قلوبهم مرض ينظرون اليك نظر المغشي عليه من الموت فاولى لهم",
  },
  {
    "surah_number": 47,
    "verse_number": 21,
    "content": "طاعة وقول معروف فاذا عزم الامر فلو صدقوا الله لكان خيرا لهم",
  },
  {
