  },
  {
    "surah_number": 47,
    "verse_number": 34,
    "content":
        "ان الذين كفروا وصدوا عن سبيل الله ثم ماتوا وهم كفار فلن يغفر الله لهم",
  },
  {
    "surah_number": 47,
    "verse_number": 35,
    "content":
