  },
  {
    "surah_number": 48,
    "verse_number": 6,
    "content":
        "ويعذب المنفقين والمنفقت والمشركين والمشركت الظانين بالله ظن السوء عليهم دائرة السوء وغضب الله عليهم ولعنهم واعد لهم جهنم وساءت مصيرا",
  },
  {
    "surah_number": 48,
    "verse_number": 7,
    "content": "ولله جنود السموت والارض وكان الله عزيزا حكيما",
  },
  {
    "surah_number": 48,
    "verse_number": 8,
    "content": "انا ارسلنك شهدا ومبشرا ونذيرا",
