  },
  {
    "surah_number": 48,
    "verse_number": 18,
    "content":
        "لقد رضي الله عن المؤمنين اذ يبايعونك تحت الشجرة فعلم ما في قلوبهم فانزل السكينة عليهم واثبهم فتحا قريبا",
  },
  {
    "surah_number": 48,
    "verse_number": 19,
    "content": "ومغانم كثيرة ياخذونها وكان الله عزيزا حكيما",
