  {
    "surah_number": 48,
    "verse_number": 20,
    "content":
        "وعدكم الله مغانم كثيرة تاخذونها فعجل لكم هذه وكف ايدي الناس عنكم ولتكون ءاية للمؤمنين ويهديكم صراطا مستقيما",
