    "verse_number": 24,
    "content":
        "وهو الذي كف ايديهم عنكم وايديكم عنهم ببطن مكة من بعد ان اظفركم عليهم وكان الله بما تعملون بصيرا",
  },
  {
    "surah_number": 48,
    "verse_number": 25,
    "content":
        "هم الذين كفروا وصدوكم عن المسجد الحرام والهدي معكوفا ان يبلغ محله ولولا رجال مؤمنون ونساء مؤمنت لم تعلموهم ان تطـوهم فتصيبكم منهم معرة بغير علم ليدخل الله في رحمته من يشاء لو تزيلوا لعذبنا الذين كفروا منهم عذابا اليما",
  },
  {
    "surah_number": 48,
    "verse_number": 26,
    "content":
        "اذ جعل الذين كفروا في قلوبهم الحمية حمية الجهلية فانزل الله سكينته على رسوله وعلى المؤمنين والزمهم كلمة التقوى وكانوا احق بها واهلها وكان الله بكل شيء عليما",
  },
  {
    "surah_number": 48,
    "verse_number": 27,
    "content":
        "لقد صدق الله رسوله الرءيا بالحق لتدخلن المسجد الحرام ان شاء الله ءامنين محلقين رءوسكم ومقصرين لا تخافون فعلم ما لم تعلموا فجعل من دون ذلك فتحا قريبا",
  },
  {
    "surah_number": 48,
    "verse_number": 28,
    "content":
