  },
  {
    "surah_number": 48,
    "verse_number": 29,
    "content":
        "محمد رسول الله والذين معه اشداء على الكفار رحماء بينهم ترىهم ركعا سجدا يبتغون فضلا من الله ورضونا سيماهم في وجوههم من اثر السجود ذلك مثلهم في التورىة ومثلهم في الانجيل كزرع اخرج شطـه فـازره فاستغلظ فاستوى على سوقه يعجب الزراع ليغيظ بهم الكفار وعد الله الذين ءامنوا وعملوا الصـلحت منهم مغفرة واجرا عظيما",
  },
  {
    "surah_number": 49,
    "verse_number": 1,
    "content":
        "يـايها الذين ءامنوا لا تقدموا بين يدي الله ورسوله واتقوا الله ان الله سميع عليم",
  },
  {
    "surah_number": 49,
    "verse_number": 2,
    "content":
        "يـايها الذين ءامنوا لا ترفعوا اصوتكم فوق صوت النبي ولا تجهروا له بالقول كجهر بعضكم لبعض ان تحبط اعملكم وانتم لا تشعرون",
  },
  {
    "surah_number": 49,
    "verse_number": 3,
    "content":
