  {
    "surah_number": 49,
    "verse_number": 8,
    "content": "فضلا من الله ونعمة والله عليم حكيم",
  },
  {
    "surah_number": 49,
    "verse_number": 9,
    "content":
        "وان طائفتان من المؤمنين اقتتلوا فاصلحوا بينهما فان بغت احدىهما على الاخرى فقتلوا التي تبغي حتى تفيء الى امر الله فان فاءت فاصلحوا بينهما بالعدل واقسطوا ان الله يحب المقسطين",
  },
  {
    "surah_number": 49,
    "verse_number": 10,
    "content": "انما المؤمنون اخوة فاصلحوا بين اخويكم واتقوا الله لعلكم ترحمون",
  },
  {
    "surah_number": 49,
    "verse_number": 11,
    "content":
        "يـايها الذين ءامنوا لا يسخر قوم من قوم عسى ان يكونوا خيرا منهم ولا نساء من نساء عسى ان يكن خيرا منهن ولا تلمزوا انفسكم ولا تنابزوا بالالقب بئس الاسم الفسوق بعد الايمن ومن لم يتب فاولـئك هم الظـلمون",
  },
  {
    "surah_number": 49,
    "verse_number": 12,
    "content":
        "يـايها الذين ءامنوا اجتنبوا كثيرا من الظن ان بعض الظن اثم ولا تجسسوا ولا يغتب بعضكم بعضا ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه واتقوا الله ان الله تواب رحيم",
  },
  {
    "surah_number": 49,
    "verse_number": 13,
    "content":
        "يـايها الناس انا خلقنكم من ذكر وانثى وجعلنكم شعوبا وقبائل لتعارفوا ان اكرمكم عند الله اتقىكم ان الله عليم خبير",
  },
  {
    "surah_number": 49,
    "verse_number": 14,
    "content":
        "قالت الاعراب ءامنا قل لم تؤمنوا ولكن قولوا اسلمنا ولما يدخل الايمن في قلوبكم وان تطيعوا الله ورسوله لا يلتكم من اعملكم شيـا ان الله غفور رحيم",
  },
  {
    "surah_number": 49,
    "verse_number": 15,
    "content":
        "انما المؤمنون الذين ءامنوا بالله ورسوله ثم لم يرتابوا وجهدوا بامولهم وانفسهم في سبيل الله اولـئك هم الصـدقون",
  },
  {
    "surah_number": 49,
    "verse_number": 16,
    "content":
        "قل اتعلمون الله بدينكم والله يعلم ما في السموت وما في الارض والله بكل شيء عليم",
  },
  {
    "surah_number": 49,
    "verse_number": 17,
    "content":
        "يمنون عليك ان اسلموا قل لا تمنوا علي اسلمكم بل الله يمن عليكم ان هدىكم للايمن ان كنتم صدقين",
  },
  {
    "surah_number": 49,
    "verse_number": 18,
    "content": "ان الله يعلم غيب السموت والارض والله بصير بما تعملون",
  },
  {"surah_number": 50, "verse_number": 1, "content": "ق والقرءان المجيد"},
  {
    "surah_number": 50,
    "verse_number": 2,
    "content": "بل عجبوا ان جاءهم منذر منهم فقال الكفرون هذا شيء عجيب",
  },
  {
    "surah_number": 50,
    "verse_number": 3,
    "content": "اءذا متنا وكنا ترابا ذلك رجع بعيد",
  },
  {
    "surah_number": 50,
    "verse_number": 4,
    "content": "قد علمنا ما تنقص الارض منهم وعندنا كتب حفيظ",
  },
  {
    "surah_number": 50,
    "verse_number": 5,
    "content": "بل كذبوا بالحق لما جاءهم فهم في امر مريج",
  },
  {
    "surah_number": 50,
    "verse_number": 6,
    "content":
        "افلم ينظروا الى السماء فوقهم كيف بنينها وزينـها وما لها من فروج",
  },
  {
    "surah_number": 50,
    "verse_number": 7,
    "content": "والارض مددنها والقينا فيها روسي وانبتنا فيها من كل زوج بهيج",
  },
  {
    "surah_number": 50,
    "verse_number": 8,
    "content": "تبصرة وذكرى لكل عبد منيب",
  },
  {
    "surah_number": 50,
    "verse_number": 9,
    "content": "ونزلنا من السماء ماء مبركا فانبتنا به جنـت وحب الحصيد",
  },
  {
    "surah_number": 50,
    "verse_number": 10,
    "content": "والنخل باسقت لها طلع نضيد",
  },
  {
    "surah_number": 50,
    "verse_number": 11,
    "content": "رزقا للعباد واحيينا به بلدة ميتا كذلك الخروج",
  },
  {
    "surah_number": 50,
    "verse_number": 12,
    "content": "كذبت قبلهم قوم نوح واصحب الرس وثمود",
  },
  {"surah_number": 50, "verse_number": 13, "content": "وعاد وفرعون واخون لوط"},
  {
    "surah_number": 50,
    "verse_number": 14,
    "content": "واصحب الايكة وقوم تبع كل كذب الرسل فحق وعيد",
  },
  {
    "surah_number": 50,
    "verse_number": 15,
    "content": "افعيينا بالخلق الاول بل هم في لبس من خلق جديد",
  },
  {
    "surah_number": 50,
    "verse_number": 16,
    "content":
        "ولقد خلقنا الانسن ونعلم ما توسوس به نفسه ونحن اقرب اليه من حبل الوريد",
  },
  {
    "surah_number": 50,
    "verse_number": 17,
    "content": "اذ يتلقى المتلقيان عن اليمين وعن الشمال قعيد",
  },
  {
    "surah_number": 50,
    "verse_number": 18,
    "content": "ما يلفظ من قول الا لديه رقيب عتيد",
  },
  {
    "surah_number": 50,
    "verse_number": 19,
    "content": "وجاءت سكرة الموت بالحق ذلك ما كنت منه تحيد",
  },
  {
    "surah_number": 50,
    "verse_number": 20,
    "content": "ونفخ في الصور ذلك يوم الوعيد",
  },
  {
    "surah_number": 50,
    "verse_number": 21,
    "content": "وجاءت كل نفس معها سائق وشهيد",
  },
  {
    "surah_number": 50,
    "verse_number": 22,
    "content": "لقد كنت في غفلة من هذا فكشفنا عنك غطاءك فبصرك اليوم حديد",
  },
  {
    "surah_number": 50,
    "verse_number": 23,
    "content": "وقال قرينه هذا ما لدي عتيد",
  },
  {
    "surah_number": 50,
    "verse_number": 24,
    "content": "القيا في جهنم كل كفار عنيد",
  },
  {"surah_number": 50, "verse_number": 25, "content": "مناع للخير معتد مريب"},
  {
    "surah_number": 50,
    "verse_number": 26,
    "content": "الذي جعل مع الله الها ءاخر فالقياه في العذاب الشديد",
  },
  {
    "surah_number": 50,
    "verse_number": 27,
    "content": "قال قرينه ربنا ما اطغيته ولكن كان في ضلل بعيد",
  },
  {
    "surah_number": 50,
    "verse_number": 28,
    "content": "قال لا تختصموا لدي وقد قدمت اليكم بالوعيد",
  },
  {
    "surah_number": 50,
    "verse_number": 29,
    "content": "ما يبدل القول لدي وما انا بظلـم للعبيد",
  },
  {
    "surah_number": 50,
    "verse_number": 30,
    "content": "يوم نقول لجهنم هل امتلات وتقول هل من مزيد",
  },
  {
    "surah_number": 50,
    "verse_number": 31,
    "content": "وازلفت الجنة للمتقين غير بعيد",
  },
  {
    "surah_number": 50,
    "verse_number": 32,
    "content": "هذا ما توعدون لكل اواب حفيظ",
  },
  {
    "surah_number": 50,
    "verse_number": 33,
    "content": "من خشي الرحمن بالغيب وجاء بقلب منيب",
  },
  {
    "surah_number": 50,
    "verse_number": 34,
    "content": "ادخلوها بسلم ذلك يوم الخلود",
  },
  {
    "surah_number": 50,
    "verse_number": 35,
    "content": "لهم ما يشاءون فيها ولدينا مزيد",
  },
  {
    "surah_number": 50,
    "verse_number": 36,
    "content":
        "وكم اهلكنا قبلهم من قرن هم اشد منهم بطشا فنقبوا في البلد هل من محيص",
  },
  {
    "surah_number": 50,
    "verse_number": 37,
    "content": "ان في ذلك لذكرى لمن كان له قلب او القى السمع وهو شهيد",
  },
  {
    "surah_number": 50,
    "verse_number": 38,
    "content":
        "ولقد خلقنا السموت والارض وما بينهما في ستة ايام وما مسنا من لغوب",
  },
  {
    "surah_number": 50,
    "verse_number": 39,
    "content": "فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب",
  },
  {
    "surah_number": 50,
    "verse_number": 40,
    "content": "ومن اليل فسبحه وادبر السجود",
  },
  {
    "surah_number": 50,
    "verse_number": 41,
    "content": "واستمع يوم يناد المناد من مكان قريب",
  },
  {
    "surah_number": 50,
    "verse_number": 42,
    "content": "يوم يسمعون الصيحة بالحق ذلك يوم الخروج",
  },
  {
    "surah_number": 50,
    "verse_number": 43,
    "content": "انا نحن نحي ونميت والينا المصير",
  },
  {
    "surah_number": 50,
    "verse_number": 44,
    "content": "يوم تشقق الارض عنهم سراعا ذلك حشر علينا يسير",
  },
  {
    "surah_number": 50,
    "verse_number": 45,
    "content":
        "نحن اعلم بما يقولون وما انت عليهم بجبار فذكر بالقرءان من يخاف وعيد",
  },
  {"surah_number": 51, "verse_number": 1, "content": "والذـريت ذروا"},
  {"surah_number": 51, "verse_number": 2, "content": "فالحملت وقرا"},
  {"surah_number": 51, "verse_number": 3, "content": "فالجريت يسرا"},
  {"surah_number": 51, "verse_number": 4, "content": "فالمقسمت امرا"},
  {"surah_number": 51, "verse_number": 5, "content": "انما توعدون لصادق"},
  {"surah_number": 51, "verse_number": 6, "content": "وان الدين لوقع"},
  {"surah_number": 51, "verse_number": 7, "content": "والسماء ذات الحبك"},
  {"surah_number": 51, "verse_number": 8, "content": "انكم لفي قول مختلف"},
  {"surah_number": 51, "verse_number": 9, "content": "يؤفك عنه من افك"},
  {"surah_number": 51, "verse_number": 10, "content": "قتل الخرـصون"},
  {"surah_number": 51, "verse_number": 11, "content": "الذين هم في غمرة ساهون"},
  {"surah_number": 51, "verse_number": 12, "content": "يسـلون ايان يوم الدين"},
  {
    "surah_number": 51,
    "verse_number": 13,
    "content": "يوم هم على النار يفتنون",
  },
  {
    "surah_number": 51,
    "verse_number": 14,
    "content": "ذوقوا فتنتكم هذا الذي كنتم به تستعجلون",
  },
  {
    "surah_number": 51,
    "verse_number": 15,
    "content": "ان المتقين في جنـت وعيون",
  },
  {
    "surah_number": 51,
    "verse_number": 16,
    "content": "ءاخذين ما ءاتىهم ربهم انهم كانوا قبل ذلك محسنين",
  },
  {
    "surah_number": 51,
    "verse_number": 17,
    "content": "كانوا قليلا من اليل ما يهجعون",
  },
  {"surah_number": 51, "verse_number": 18, "content": "وبالاسحار هم يستغفرون"},
  {
    "surah_number": 51,
    "verse_number": 19,
    "content": "وفي امولهم حق للسائل والمحروم",
  },
  {
    "surah_number": 51,
    "verse_number": 20,
    "content": "وفي الارض ءايت للموقنين",
  },
  {"surah_number": 51, "verse_number": 21, "content": "وفي انفسكم افلا تبصرون"},
  {
    "surah_number": 51,
    "verse_number": 22,
    "content": "وفي السماء رزقكم وما توعدون",
  },
  {
    "surah_number": 51,
    "verse_number": 23,
    "content": "فورب السماء والارض انه لحق مثل ما انكم تنطقون",
  },
  {
    "surah_number": 51,
    "verse_number": 24,
    "content": "هل اتىك حديث ضيف ابرهيم المكرمين",
  },
  {
    "surah_number": 51,
    "verse_number": 25,
    "content": "اذ دخلوا عليه فقالوا سلما قال سلم قوم منكرون",
  },
  {
    "surah_number": 51,
    "verse_number": 26,
    "content": "فراغ الى اهله فجاء بعجل سمين",
  },
  {
    "surah_number": 51,
    "verse_number": 27,
    "content": "فقربه اليهم قال الا تاكلون",
  },
  {
    "surah_number": 51,
    "verse_number": 28,
    "content": "فاوجس منهم خيفة قالوا لا تخف وبشروه بغلم عليم",
  },
  {
    "surah_number": 51,
    "verse_number": 29,
    "content": "فاقبلت امراته في صرة فصكت وجهها وقالت عجوز عقيم",
  },
  {
    "surah_number": 51,
    "verse_number": 30,
    "content": "قالوا كذلك قال ربك انه هو الحكيم العليم",
  },
  {
    "surah_number": 51,
    "verse_number": 31,
    "content": "قال فما خطبكم ايها المرسلون",
  },
  {
    "surah_number": 51,
    "verse_number": 32,
    "content": "قالوا انا ارسلنا الى قوم مجرمين",
  },
  {
    "surah_number": 51,
    "verse_number": 33,
    "content": "لنرسل عليهم حجارة من طين",
  },
  {"surah_number": 51, "verse_number": 34, "content": "مسومة عند ربك للمسرفين"},
  {
    "surah_number": 51,
    "verse_number": 35,
    "content": "فاخرجنا من كان فيها من المؤمنين",
  },
  {
    "surah_number": 51,
    "verse_number": 36,
    "content": "فما وجدنا فيها غير بيت من المسلمين",
  },
  {
    "surah_number": 51,
    "verse_number": 37,
    "content": "وتركنا فيها ءاية للذين يخافون العذاب الاليم",
  },
  {
    "surah_number": 51,
    "verse_number": 38,
    "content": "وفي موسى اذ ارسلنه الى فرعون بسلطن مبين",
  },
  {
    "surah_number": 51,
    "verse_number": 39,
    "content": "فتولى بركنه وقال سحر او مجنون",
  },
  {
    "surah_number": 51,
    "verse_number": 40,
    "content": "فاخذنه وجنوده فنبذنهم في اليم وهو مليم",
  },
  {
    "surah_number": 51,
    "verse_number": 41,
    "content": "وفي عاد اذ ارسلنا عليهم الريح العقيم",
  },
  {
    "surah_number": 51,
    "verse_number": 42,
    "content": "ما تذر من شيء اتت عليه الا جعلته كالرميم",
  },
  {
    "surah_number": 51,
    "verse_number": 43,
    "content": "وفي ثمود اذ قيل لهم تمتعوا حتى حين",
  },
  {
    "surah_number": 51,
    "verse_number": 44,
    "content": "فعتوا عن امر ربهم فاخذتهم الصـعقة وهم ينظرون",
  },
  {
    "surah_number": 51,
    "verse_number": 45,
    "content": "فما استطعوا من قيام وما كانوا منتصرين",
  },
  {
    "surah_number": 51,
    "verse_number": 46,
    "content": "وقوم نوح من قبل انهم كانوا قوما فسقين",
  },
  {
    "surah_number": 51,
    "verse_number": 47,
    "content": "والسماء بنينها باييد وانا لموسعون",
  },
  {
    "surah_number": 51,
    "verse_number": 48,
    "content": "والارض فرشنها فنعم المهدون",
  },
  {
    "surah_number": 51,
    "verse_number": 49,
    "content": "ومن كل شيء خلقنا زوجين لعلكم تذكرون",
  },
  {
    "surah_number": 51,
    "verse_number": 50,
    "content": "ففروا الى الله اني لكم منه نذير مبين",
  },
  {
    "surah_number": 51,
    "verse_number": 51,
    "content": "ولا تجعلوا مع الله الها ءاخر اني لكم منه نذير مبين",
  },
  {
    "surah_number": 51,
    "verse_number": 52,
    "content": "كذلك ما اتى الذين من قبلهم من رسول الا قالوا ساحر او مجنون",
  },
  {
    "surah_number": 51,
    "verse_number": 53,
    "content": "اتواصوا به بل هم قوم طاغون",
  },
  {
    "surah_number": 51,
    "verse_number": 54,
    "content": "فتول عنهم فما انت بملوم",
  },
  {
    "surah_number": 51,
    "verse_number": 55,
    "content": "وذكر فان الذكرى تنفع المؤمنين",
  },
  {
    "surah_number": 51,
    "verse_number": 56,
    "content": "وما خلقت الجن والانس الا ليعبدون",
  },
  {
    "surah_number": 51,
    "verse_number": 57,
    "content": "ما اريد منهم من رزق وما اريد ان يطعمون",
  },
  {
    "surah_number": 51,
    "verse_number": 58,
    "content": "ان الله هو الرزاق ذو القوة المتين",
  },
  {
    "surah_number": 51,
    "verse_number": 59,
    "content": "فان للذين ظلموا ذنوبا مثل ذنوب اصحبهم فلا يستعجلون",
  },
  {
    "surah_number": 51,
    "verse_number": 60,
    "content": "فويل للذين كفروا من يومهم الذي يوعدون",
  },
  {"surah_number": 52, "verse_number": 1, "content": "والطور"},
  {"surah_number": 52, "verse_number": 2, "content": "وكتب مسطور"},
  {"surah_number": 52, "verse_number": 3, "content": "في رق منشور"},
  {"surah_number": 52, "verse_number": 4, "content": "والبيت المعمور"},
  {"surah_number": 52, "verse_number": 5, "content": "والسقف المرفوع"},
  {"surah_number": 52, "verse_number": 6, "content": "والبحر المسجور"},
  {"surah_number": 52, "verse_number": 7, "content": "ان عذاب ربك لوقع"},
  {"surah_number": 52, "verse_number": 8, "content": "ما له من دافع"},
  {"surah_number": 52, "verse_number": 9, "content": "يوم تمور السماء مورا"},
  {"surah_number": 52, "verse_number": 10, "content": "وتسير الجبال سيرا"},
  {"surah_number": 52, "verse_number": 11, "content": "فويل يومئذ للمكذبين"},
  {"surah_number": 52, "verse_number": 12, "content": "الذين هم في خوض يلعبون"},
  {
    "surah_number": 52,
