  {
    "surah_number": 52,
    "verse_number": 15,
    "content": "افسحر هذا ام انتم لا تبصرون",
  },
  {
    "surah_number": 52,
    "verse_number": 16,
    "content":
        "اصلوها فاصبروا او لا تصبروا سواء عليكم انما تجزون ما كنتم تعملون",
  },
  {
    "surah_number": 52,
    "verse_number": 17,
    "content": "ان المتقين في جنـت ونعيم",
  },
  {
    "surah_number": 52,
    "verse_number": 18,
    "content": "فكهين بما ءاتىهم ربهم ووقىهم ربهم عذاب الجحيم",
  },
  {
    "surah_number": 52,
    "verse_number": 19,
    "content": "كلوا واشربوا هنيـا بما كنتم تعملون",
  },
  {
    "surah_number": 52,
    "verse_number": 20,
    "content": "متكـين على سرر مصفوفة وزوجنهم بحور عين",
  },
  {
    "surah_number": 52,
    "verse_number": 21,
    "content":
        "والذين ءامنوا واتبعتهم ذريتهم بايمن الحقنا بهم ذريتهم وما التنهم من عملهم من شيء كل امري بما كسب رهين",
  },
  {
    "surah_number": 52,
    "verse_number": 22,
    "content": "وامددنهم بفكهة ولحم مما يشتهون",
  },
  {
    "surah_number": 52,
    "verse_number": 23,
    "content": "يتنزعون فيها كاسا لا لغو فيها ولا تاثيم",
  },
  {
    "surah_number": 52,
    "verse_number": 24,
    "content": "ويطوف عليهم غلمان لهم كانهم لؤلؤ مكنون",
  },
  {
    "surah_number": 52,
    "verse_number": 25,
    "content": "واقبل بعضهم على بعض يتساءلون",
  },
  {
    "surah_number": 52,
    "verse_number": 26,
    "content": "قالوا انا كنا قبل في اهلنا مشفقين",
  },
  {
    "surah_number": 52,
    "verse_number": 27,
    "content": "فمن الله علينا ووقىنا عذاب السموم",
  },
  {
    "surah_number": 52,
    "verse_number": 28,
    "content": "انا كنا من قبل ندعوه انه هو البر الرحيم",
  },
  {
    "surah_number": 52,
    "verse_number": 29,
    "content": "فذكر فما انت بنعمت ربك بكاهن ولا مجنون",
  },
  {
    "surah_number": 52,
    "verse_number": 30,
    "content": "ام يقولون شاعر نتربص به ريب المنون",
  },
  {
    "surah_number": 52,
    "verse_number": 31,
    "content": "قل تربصوا فاني معكم من المتربصين",
  },
  {
    "surah_number": 52,
    "verse_number": 32,
    "content": "ام تامرهم احلمهم بهذا ام هم قوم طاغون",
  },
  {
    "surah_number": 52,
    "verse_number": 33,
    "content": "ام يقولون تقوله بل لا يؤمنون",
  },
  {
    "surah_number": 52,
    "verse_number": 34,
    "content": "فلياتوا بحديث مثله ان كانوا صدقين",
  },
  {
    "surah_number": 52,
    "verse_number": 35,
    "content": "ام خلقوا من غير شيء ام هم الخلقون",
  },
  {
    "surah_number": 52,
    "verse_number": 36,
    "content": "ام خلقوا السموت والارض بل لا يوقنون",
  },
  {
    "surah_number": 52,
    "verse_number": 37,
    "content": "ام عندهم خزائن ربك ام هم المصيطرون",
  },
  {
    "surah_number": 52,
    "verse_number": 38,
    "content": "ام لهم سلم يستمعون فيه فليات مستمعهم بسلطن مبين",
  },
  {
    "surah_number": 52,
    "verse_number": 39,
    "content": "ام له البنت ولكم البنون",
  },
  {
    "surah_number": 52,
    "verse_number": 40,
    "content": "ام تسـلهم اجرا فهم من مغرم مثقلون",
  },
  {
    "surah_number": 52,
    "verse_number": 41,
    "content": "ام عندهم الغيب فهم يكتبون",
  },
  {
    "surah_number": 52,
    "verse_number": 42,
    "content": "ام يريدون كيدا فالذين كفروا هم المكيدون",
  },
  {
    "surah_number": 52,
    "verse_number": 43,
    "content": "ام لهم اله غير الله سبحن الله عما يشركون",
  },
  {
    "surah_number": 52,
    "verse_number": 44,
    "content": "وان يروا كسفا من السماء ساقطا يقولوا سحاب مركوم",
  },
  {
    "surah_number": 52,
    "verse_number": 45,
    "content": "فذرهم حتى يلقوا يومهم الذي فيه يصعقون",
  },
  {
    "surah_number": 52,
    "verse_number": 46,
    "content": "يوم لا يغني عنهم كيدهم شيـا ولا هم ينصرون",
  },
  {
    "surah_number": 52,
    "verse_number": 47,
    "content": "وان للذين ظلموا عذابا دون ذلك ولكن اكثرهم لا يعلمون",
  },
  {
    "surah_number": 52,
    "verse_number": 48,
    "content": "واصبر لحكم ربك فانك باعيننا وسبح بحمد ربك حين تقوم",
  },
  {
    "surah_number": 52,
    "verse_number": 49,
    "content": "ومن اليل فسبحه وادبر النجوم",
  },
  {"surah_number": 53, "verse_number": 1, "content": "والنجم اذا هوى"},
  {"surah_number": 53, "verse_number": 2, "content": "ما ضل صاحبكم وما غوى"},
  {"surah_number": 53, "verse_number": 3, "content": "وما ينطق عن الهوى"},
  {"surah_number": 53, "verse_number": 4, "content": "ان هو الا وحي يوحى"},
  {"surah_number": 53, "verse_number": 5, "content": "علمه شديد القوى"},
  {"surah_number": 53, "verse_number": 6, "content": "ذو مرة فاستوى"},
  {"surah_number": 53, "verse_number": 7, "content": "وهو بالافق الاعلى"},
  {"surah_number": 53, "verse_number": 8, "content": "ثم دنا فتدلى"},
  {"surah_number": 53, "verse_number": 9, "content": "فكان قاب قوسين او ادنى"},
  {"surah_number": 53, "verse_number": 10, "content": "فاوحى الى عبده ما اوحى"},
  {"surah_number": 53, "verse_number": 11, "content": "ما كذب الفؤاد ما راى"},
  {"surah_number": 53, "verse_number": 12, "content": "افتمرونه على ما يرى"},
  {"surah_number": 53, "verse_number": 13, "content": "ولقد رءاه نزلة اخرى"},
  {"surah_number": 53, "verse_number": 14, "content": "عند سدرة المنتهى"},
  {"surah_number": 53, "verse_number": 15, "content": "عندها جنة الماوى"},
  {"surah_number": 53, "verse_number": 16, "content": "اذ يغشى السدرة ما يغشى"},
  {"surah_number": 53, "verse_number": 17, "content": "ما زاغ البصر وما طغى"},
  {
    "surah_number": 53,
    "verse_number": 18,
    "content": "لقد راى من ءايت ربه الكبرى",
  },
  {"surah_number": 53, "verse_number": 19, "content": "افرءيتم اللـت والعزى"},
  {"surah_number": 53, "verse_number": 20, "content": "ومنوة الثالثة الاخرى"},
  {"surah_number": 53, "verse_number": 21, "content": "الكم الذكر وله الانثى"},
  {"surah_number": 53, "verse_number": 22, "content": "تلك اذا قسمة ضيزى"},
  {
    "surah_number": 53,
    "verse_number": 23,
    "content":
        "ان هي الا اسماء سميتموها انتم وءاباؤكم ما انزل الله بها من سلطن ان يتبعون الا الظن وما تهوى الانفس ولقد جاءهم من ربهم الهدى",
  },
  {"surah_number": 53, "verse_number": 24, "content": "ام للانسن ما تمنى"},
  {"surah_number": 53, "verse_number": 25, "content": "فلله الاخرة والاولى"},
  {
    "surah_number": 53,
    "verse_number": 26,
    "content":
        "وكم من ملك في السموت لا تغني شفعتهم شيـا الا من بعد ان ياذن الله لمن يشاء ويرضى",
  },
  {
    "surah_number": 53,
    "verse_number": 27,
    "content": "ان الذين لا يؤمنون بالاخرة ليسمون الملـئكة تسمية الانثى",
  },
  {
    "surah_number": 53,
    "verse_number": 28,
    "content":
        "وما لهم به من علم ان يتبعون الا الظن وان الظن لا يغني من الحق شيـا",
  },
  {
    "surah_number": 53,
    "verse_number": 29,
    "content": "فاعرض عن من تولى عن ذكرنا ولم يرد الا الحيوة الدنيا",
  },
  {
    "surah_number": 53,
    "verse_number": 30,
    "content":
        "ذلك مبلغهم من العلم ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بمن اهتدى",
  },
  {
    "surah_number": 53,
    "verse_number": 31,
    "content":
        "ولله ما في السموت وما في الارض ليجزي الذين اســوا بما عملوا ويجزي الذين احسنوا بالحسنى",
  },
  {
    "surah_number": 53,
    "verse_number": 32,
    "content":
        "الذين يجتنبون كبـئر الاثم والفوحش الا اللمم ان ربك وسع المغفرة هو اعلم بكم اذ انشاكم من الارض واذ انتم اجنة في بطون امهتكم فلا تزكوا انفسكم هو اعلم بمن اتقى",
  },
  {"surah_number": 53, "verse_number": 33, "content": "افرءيت الذي تولى"},
  {"surah_number": 53, "verse_number": 34, "content": "واعطى قليلا واكدى"},
  {
    "surah_number": 53,
    "verse_number": 35,
    "content": "اعنده علم الغيب فهو يرى",
  },
  {
    "surah_number": 53,
    "verse_number": 36,
    "content": "ام لم ينبا بما في صحف موسى",
  },
  {"surah_number": 53, "verse_number": 37, "content": "وابرهيم الذي وفى"},
  {"surah_number": 53, "verse_number": 38, "content": "الا تزر وازرة وزر اخرى"},
  {
    "surah_number": 53,
    "verse_number": 39,
    "content": "وان ليس للانسن الا ما سعى",
  },
  {"surah_number": 53, "verse_number": 40, "content": "وان سعيه سوف يرى"},
  {"surah_number": 53, "verse_number": 41, "content": "ثم يجزىه الجزاء الاوفى"},
  {"surah_number": 53, "verse_number": 42, "content": "وان الى ربك المنتهى"},
  {"surah_number": 53, "verse_number": 43, "content": "وانه هو اضحك وابكى"},
  {"surah_number": 53, "verse_number": 44, "content": "وانه هو امات واحيا"},
  {
    "surah_number": 53,
    "verse_number": 45,
    "content": "وانه خلق الزوجين الذكر والانثى",
  },
  {"surah_number": 53, "verse_number": 46, "content": "من نطفة اذا تمنى"},
  {"surah_number": 53, "verse_number": 47, "content": "وان عليه النشاة الاخرى"},
  {"surah_number": 53, "verse_number": 48, "content": "وانه هو اغنى واقنى"},
  {"surah_number": 53, "verse_number": 49, "content": "وانه هو رب الشعرى"},
  {"surah_number": 53, "verse_number": 50, "content": "وانه اهلك عادا الاولى"},
  {"surah_number": 53, "verse_number": 51, "content": "وثمودا فما ابقى"},
  {
    "surah_number": 53,
    "verse_number": 52,
    "content": "وقوم نوح من قبل انهم كانوا هم اظلم واطغى",
  },
  {"surah_number": 53, "verse_number": 53, "content": "والمؤتفكة اهوى"},
  {"surah_number": 53, "verse_number": 54, "content": "فغشىها ما غشى"},
  {"surah_number": 53, "verse_number": 55, "content": "فباي ءالاء ربك تتمارى"},
  {
    "surah_number": 53,
    "verse_number": 56,
    "content": "هذا نذير من النذر الاولى",
  },
  {"surah_number": 53, "verse_number": 57, "content": "ازفت الازفة"},
  {
    "surah_number": 53,
    "verse_number": 58,
    "content": "ليس لها من دون الله كاشفة",
  },
  {"surah_number": 53, "verse_number": 59, "content": "افمن هذا الحديث تعجبون"},
  {"surah_number": 53, "verse_number": 60, "content": "وتضحكون ولا تبكون"},
  {"surah_number": 53, "verse_number": 61, "content": "وانتم سمدون"},
  {"surah_number": 53, "verse_number": 62, "content": "فاسجدوا لله واعبدوا"},
  {
    "surah_number": 54,
    "verse_number": 1,
    "content": "اقتربت الساعة وانشق القمر",
  },
  {
    "surah_number": 54,
    "verse_number": 2,
    "content": "وان يروا ءاية يعرضوا ويقولوا سحر مستمر",
  },
  {
    "surah_number": 54,
    "verse_number": 3,
    "content": "وكذبوا واتبعوا اهواءهم وكل امر مستقر",
  },
  {
    "surah_number": 54,
    "verse_number": 4,
    "content": "ولقد جاءهم من الانباء ما فيه مزدجر",
  },
  {"surah_number": 54, "verse_number": 5, "content": "حكمة بلغة فما تغن النذر"},
  {
    "surah_number": 54,
    "verse_number": 6,
    "content": "فتول عنهم يوم يدع الداع الى شيء نكر",
  },
  {
    "surah_number": 54,
    "verse_number": 7,
    "content": "خشعا ابصرهم يخرجون من الاجداث كانهم جراد منتشر",
  },
  {
    "surah_number": 54,
    "verse_number": 8,
    "content": "مهطعين الى الداع يقول الكفرون هذا يوم عسر",
  },
  {
    "surah_number": 54,
    "verse_number": 9,
    "content": "كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر",
  },
  {
    "surah_number": 54,
    "verse_number": 10,
    "content": "فدعا ربه اني مغلوب فانتصر",
  },
  {
    "surah_number": 54,
    "verse_number": 11,
    "content": "ففتحنا ابوب السماء بماء منهمر",
  },
  {
    "surah_number": 54,
    "verse_number": 12,
    "content": "وفجرنا الارض عيونا فالتقى الماء على امر قد قدر",
  },
  {
    "surah_number": 54,
    "verse_number": 13,
    "content": "وحملنه على ذات الوح ودسر",
  },
  {
    "surah_number": 54,
    "verse_number": 14,
    "content": "تجري باعيننا جزاء لمن كان كفر",
  },
  {
    "surah_number": 54,
    "verse_number": 15,
    "content": "ولقد تركنها ءاية فهل من مدكر",
  },
  {"surah_number": 54, "verse_number": 16, "content": "فكيف كان عذابي ونذر"},
  {
    "surah_number": 54,
    "verse_number": 17,
    "content": "ولقد يسرنا القرءان للذكر فهل من مدكر",
  },
  {
    "surah_number": 54,
    "verse_number": 18,
    "content": "كذبت عاد فكيف كان عذابي ونذر",
  },
  {
    "surah_number": 54,
    "verse_number": 19,
    "content": "انا ارسلنا عليهم ريحا صرصرا في يوم نحس مستمر",
  },
  {
    "surah_number": 54,
    "verse_number": 20,
    "content": "تنزع الناس كانهم اعجاز نخل منقعر",
  },
  {"surah_number": 54, "verse_number": 21, "content": "فكيف كان عذابي ونذر"},
  {
    "surah_number": 54,
    "verse_number": 22,
    "content": "ولقد يسرنا القرءان للذكر فهل من مدكر",
  },
  {"surah_number": 54, "verse_number": 23, "content": "كذبت ثمود بالنذر"},
  {
    "surah_number": 54,
    "verse_number": 24,
    "content": "فقالوا ابشرا منا وحدا نتبعه انا اذا لفي ضلل وسعر",
  },
  {
    "surah_number": 54,
    "verse_number": 25,
    "content": "اءلقي الذكر عليه من بيننا بل هو كذاب اشر",
  },
  {
    "surah_number": 54,
    "verse_number": 26,
    "content": "سيعلمون غدا من الكذاب الاشر",
  },
  {
    "surah_number": 54,
    "verse_number": 27,
    "content": "انا مرسلوا الناقة فتنة لهم فارتقبهم واصطبر",
  },
  {
    "surah_number": 54,
    "verse_number": 28,
    "content": "ونبئهم ان الماء قسمة بينهم كل شرب محتضر",
  },
  {
    "surah_number": 54,
    "verse_number": 29,
    "content": "فنادوا صاحبهم فتعاطى فعقر",
  },
  {"surah_number": 54, "verse_number": 30, "content": "فكيف كان عذابي ونذر"},
  {
    "surah_number": 54,
    "verse_number": 31,
    "content": "انا ارسلنا عليهم صيحة وحدة فكانوا كهشيم المحتظر",
  },
  {
    "surah_number": 54,
    "verse_number": 32,
    "content": "ولقد يسرنا القرءان للذكر فهل من مدكر",
  },
  {"surah_number": 54, "verse_number": 33, "content": "كذبت قوم لوط بالنذر"},
  {
    "surah_number": 54,
    "verse_number": 34,
    "content": "انا ارسلنا عليهم حاصبا الا ءال لوط نجينهم بسحر",
  },
  {
    "surah_number": 54,
    "verse_number": 35,
    "content": "نعمة من عندنا كذلك نجزي من شكر",
  },
  {
    "surah_number": 54,
    "verse_number": 36,
    "content": "ولقد انذرهم بطشتنا فتماروا بالنذر",
  },
  {
    "surah_number": 54,
    "verse_number": 37,
    "content": "ولقد رودوه عن ضيفه فطمسنا اعينهم فذوقوا عذابي ونذر",
  },
  {
    "surah_number": 54,
    "verse_number": 38,
    "content": "ولقد صبحهم بكرة عذاب مستقر",
  },
  {"surah_number": 54, "verse_number": 39, "content": "فذوقوا عذابي ونذر"},
  {
    "surah_number": 54,
    "verse_number": 40,
    "content": "ولقد يسرنا القرءان للذكر فهل من مدكر",
  },
  {
    "surah_number": 54,
    "verse_number": 41,
    "content": "ولقد جاء ءال فرعون النذر",
  },
  {
    "surah_number": 54,
    "verse_number": 42,
    "content": "كذبوا بـايتنا كلها فاخذنهم اخذ عزيز مقتدر",
  },
  {
    "surah_number": 54,
    "verse_number": 43,
    "content": "اكفاركم خير من اولـئكم ام لكم براءة في الزبر",
  },
  {
    "surah_number": 54,
    "verse_number": 44,
    "content": "ام يقولون نحن جميع منتصر",
  },
  {
    "surah_number": 54,
    "verse_number": 45,
    "content": "سيهزم الجمع ويولون الدبر",
  },
  {
    "surah_number": 54,
    "verse_number": 46,
    "content": "بل الساعة موعدهم والساعة ادهى وامر",
  },
  {
    "surah_number": 54,
    "verse_number": 47,
    "content": "ان المجرمين في ضلل وسعر",
  },
  {
    "surah_number": 54,
    "verse_number": 48,
    "content": "يوم يسحبون في النار على وجوههم ذوقوا مس سقر",
  },
  {"surah_number": 54, "verse_number": 49, "content": "انا كل شيء خلقنه بقدر"},
  {
    "surah_number": 54,
    "verse_number": 50,
    "content": "وما امرنا الا وحدة كلمح بالبصر",
  },
  {
    "surah_number": 54,
    "verse_number": 51,
    "content": "ولقد اهلكنا اشياعكم فهل من مدكر",
  },
  {"surah_number": 54, "verse_number": 52, "content": "وكل شيء فعلوه في الزبر"},
  {"surah_number": 54, "verse_number": 53, "content": "وكل صغير وكبير مستطر"},
  {
    "surah_number": 54,
    "verse_number": 54,
    "content": "ان المتقين في جنـت ونهر",
  },
  {
    "surah_number": 54,
    "verse_number": 55,
    "content": "في مقعد صدق عند مليك مقتدر",
  },
  {"surah_number": 55, "verse_number": 1, "content": "الرحمن"},
  {"surah_number": 55, "verse_number": 2, "content": "علم القرءان"},
  {"surah_number": 55, "verse_number": 3, "content": "خلق الانسن"},
  {"surah_number": 55, "verse_number": 4, "content": "علمه البيان"},
  {"surah_number": 55, "verse_number": 5, "content": "الشمس والقمر بحسبان"},
  {"surah_number": 55, "verse_number": 6, "content": "والنجم والشجر يسجدان"},
  {
    "surah_number": 55,
    "verse_number": 7,
    "content": "والسماء رفعها ووضع الميزان",
  },
  {"surah_number": 55, "verse_number": 8, "content": "الا تطغوا في الميزان"},
  {
    "surah_number": 55,
    "verse_number": 9,
    "content": "واقيموا الوزن بالقسط ولا تخسروا الميزان",
  },
  {"surah_number": 55, "verse_number": 10, "content": "والارض وضعها للانام"},
  {
    "surah_number": 55,
    "verse_number": 11,
    "content": "فيها فكهة والنخل ذات الاكمام",
  },
  {
    "surah_number": 55,
    "verse_number": 12,
    "content": "والحب ذو العصف والريحان",
  },
  {
    "surah_number": 55,
    "verse_number": 13,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 14,
    "content": "خلق الانسن من صلصل كالفخار",
  },
  {
    "surah_number": 55,
    "verse_number": 15,
    "content": "وخلق الجان من مارج من نار",
  },
  {
    "surah_number": 55,
    "verse_number": 16,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 17,
    "content": "رب المشرقين ورب المغربين",
  },
  {
    "surah_number": 55,
    "verse_number": 18,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 19, "content": "مرج البحرين يلتقيان"},
  {"surah_number": 55, "verse_number": 20, "content": "بينهما برزخ لا يبغيان"},
  {
    "surah_number": 55,
    "verse_number": 21,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 22,
    "content": "يخرج منهما اللؤلؤ والمرجان",
  },
  {
    "surah_number": 55,
    "verse_number": 23,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 24,
    "content": "وله الجوار المنشـات في البحر كالاعلم",
  },
  {
    "surah_number": 55,
    "verse_number": 25,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 26, "content": "كل من عليها فان"},
  {
    "surah_number": 55,
    "verse_number": 27,
    "content": "ويبقى وجه ربك ذو الجلل والاكرام",
  },
  {
    "surah_number": 55,
    "verse_number": 28,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 29,
    "content": "يسـله من في السموت والارض كل يوم هو في شان",
  },
  {
    "surah_number": 55,
    "verse_number": 30,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 31, "content": "سنفرغ لكم ايه الثقلان"},
  {
    "surah_number": 55,
    "verse_number": 32,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 33,
    "content":
        "يمعشر الجن والانس ان استطعتم ان تنفذوا من اقطار السموت والارض فانفذوا لا تنفذون الا بسلطن",
  },
  {
    "surah_number": 55,
    "verse_number": 34,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 35,
    "content": "يرسل عليكما شواظ من نار ونحاس فلا تنتصران",
  },
  {
    "surah_number": 55,
    "verse_number": 36,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 37,
    "content": "فاذا انشقت السماء فكانت وردة كالدهان",
  },
  {
    "surah_number": 55,
    "verse_number": 38,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 39,
    "content": "فيومئذ لا يسـل عن ذنبه انس ولا جان",
  },
  {
    "surah_number": 55,
    "verse_number": 40,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 41,
    "content": "يعرف المجرمون بسيمهم فيؤخذ بالنوصي والاقدام",
  },
  {
    "surah_number": 55,
    "verse_number": 42,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 43,
    "content": "هذه جهنم التي يكذب بها المجرمون",
  },
  {
    "surah_number": 55,
    "verse_number": 44,
    "content": "يطوفون بينها وبين حميم ءان",
  },
  {
    "surah_number": 55,
    "verse_number": 45,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 46,
    "content": "ولمن خاف مقام ربه جنتان",
  },
  {
    "surah_number": 55,
    "verse_number": 47,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 48, "content": "ذواتا افنان"},
  {
    "surah_number": 55,
    "verse_number": 49,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 50, "content": "فيهما عينان تجريان"},
  {
    "surah_number": 55,
    "verse_number": 51,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 52, "content": "فيهما من كل فكهة زوجان"},
  {
    "surah_number": 55,
    "verse_number": 53,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 54,
    "content": "متكـين على فرش بطائنها من استبرق وجنى الجنتين دان",
  },
  {
    "surah_number": 55,
    "verse_number": 55,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 56,
    "content": "فيهن قصرت الطرف لم يطمثهن انس قبلهم ولا جان",
  },
  {
    "surah_number": 55,
    "verse_number": 57,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 58, "content": "كانهن الياقوت والمرجان"},
  {
    "surah_number": 55,
    "verse_number": 59,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 60,
    "content": "هل جزاء الاحسن الا الاحسن",
  },
  {
    "surah_number": 55,
    "verse_number": 61,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 62, "content": "ومن دونهما جنتان"},
  {
    "surah_number": 55,
    "verse_number": 63,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 64, "content": "مدهامتان"},
  {
    "surah_number": 55,
    "verse_number": 65,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 66, "content": "فيهما عينان نضاختان"},
  {
    "surah_number": 55,
    "verse_number": 67,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 68, "content": "فيهما فكهة ونخل ورمان"},
  {
    "surah_number": 55,
    "verse_number": 69,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 70, "content": "فيهن خيرت حسان"},
  {
    "surah_number": 55,
    "verse_number": 71,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {"surah_number": 55, "verse_number": 72, "content": "حور مقصورت في الخيام"},
  {
    "surah_number": 55,
    "verse_number": 73,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 74,
    "content": "لم يطمثهن انس قبلهم ولا جان",
  },
  {
    "surah_number": 55,
    "verse_number": 75,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 76,
    "content": "متكـين على رفرف خضر وعبقري حسان",
  },
  {
    "surah_number": 55,
    "verse_number": 77,
    "content": "فباي ءالاء ربكما تكذبان",
  },
  {
    "surah_number": 55,
    "verse_number": 78,
    "content": "تبرك اسم ربك ذي الجلل والاكرام",
  },
  {"surah_number": 56, "verse_number": 1, "content": "اذا وقعت الواقعة"},
  {"surah_number": 56, "verse_number": 2, "content": "ليس لوقعتها كاذبة"},
  {"surah_number": 56, "verse_number": 3, "content": "خافضة رافعة"},
  {"surah_number": 56, "verse_number": 4, "content": "اذا رجت الارض رجا"},
  {"surah_number": 56, "verse_number": 5, "content": "وبست الجبال بسا"},
  {"surah_number": 56, "verse_number": 6, "content": "فكانت هباء منبثا"},
  {"surah_number": 56, "verse_number": 7, "content": "وكنتم ازوجا ثلثة"},
  {
    "surah_number": 56,
    "verse_number": 8,
    "content": "فاصحب الميمنة ما اصحب الميمنة",
  },
  {
    "surah_number": 56,
    "verse_number": 9,
    "content": "واصحب المشـمة ما اصحب المشـمة",
  },
  {"surah_number": 56, "verse_number": 10, "content": "والسـبقون السـبقون"},
  {"surah_number": 56, "verse_number": 11, "content": "اولـئك المقربون"},
  {"surah_number": 56, "verse_number": 12, "content": "في جنـت النعيم"},
  {"surah_number": 56, "verse_number": 13, "content": "ثلة من الاولين"},
  {"surah_number": 56, "verse_number": 14, "content": "وقليل من الاخرين"},
  {"surah_number": 56, "verse_number": 15, "content": "على سرر موضونة"},
  {"surah_number": 56, "verse_number": 16, "content": "متكـين عليها متقبلين"},
  {"surah_number": 56, "verse_number": 17, "content": "يطوف عليهم ولدن مخلدون"},
  {
    "surah_number": 56,
    "verse_number": 18,
    "content": "باكواب واباريق وكاس من معين",
  },
  {
    "surah_number": 56,
    "verse_number": 19,
    "content": "لا يصدعون عنها ولا ينزفون",
  },
  {"surah_number": 56, "verse_number": 20, "content": "وفكهة مما يتخيرون"},
  {"surah_number": 56, "verse_number": 21, "content": "ولحم طير مما يشتهون"},
  {"surah_number": 56, "verse_number": 22, "content": "وحور عين"},
  {"surah_number": 56, "verse_number": 23, "content": "كامثل اللؤلو المكنون"},
  {"surah_number": 56, "verse_number": 24, "content": "جزاء بما كانوا يعملون"},
  {
    "surah_number": 56,
    "verse_number": 25,
    "content": "لا يسمعون فيها لغوا ولا تاثيما",
  },
  {"surah_number": 56, "verse_number": 26, "content": "الا قيلا سلما سلما"},
  {
    "surah_number": 56,
    "verse_number": 27,
    "content": "واصحب اليمين ما اصحب اليمين",
  },
  {"surah_number": 56, "verse_number": 28, "content": "في سدر مخضود"},
  {"surah_number": 56, "verse_number": 29, "content": "وطلح منضود"},
  {"surah_number": 56, "verse_number": 30, "content": "وظل ممدود"},
  {"surah_number": 56, "verse_number": 31, "content": "وماء مسكوب"},
  {"surah_number": 56, "verse_number": 32, "content": "وفكهة كثيرة"},
  {"surah_number": 56, "verse_number": 33, "content": "لا مقطوعة ولا ممنوعة"},
  {"surah_number": 56, "verse_number": 34, "content": "وفرش مرفوعة"},
  {"surah_number": 56, "verse_number": 35, "content": "انا انشانهن انشاء"},
  {"surah_number": 56, "verse_number": 36, "content": "فجعلنهن ابكارا"},
  {"surah_number": 56, "verse_number": 37, "content": "عربا اترابا"},
  {"surah_number": 56, "verse_number": 38, "content": "لاصحب اليمين"},
  {"surah_number": 56, "verse_number": 39, "content": "ثلة من الاولين"},
  {"surah_number": 56, "verse_number": 40, "content": "وثلة من الاخرين"},
  {
    "surah_number": 56,
    "verse_number": 41,
    "content": "واصحب الشمال ما اصحب الشمال",
  },
  {"surah_number": 56, "verse_number": 42, "content": "في سموم وحميم"},
  {"surah_number": 56, "verse_number": 43, "content": "وظل من يحموم"},
  {"surah_number": 56, "verse_number": 44, "content": "لا بارد ولا كريم"},
  {
    "surah_number": 56,
    "verse_number": 45,
    "content": "انهم كانوا قبل ذلك مترفين",
  },
  {
    "surah_number": 56,
    "verse_number": 46,
    "content": "وكانوا يصرون على الحنث العظيم",
  },
  {
    "surah_number": 56,
    "verse_number": 47,
    "content": "وكانوا يقولون ائذا متنا وكنا ترابا وعظما اءنا لمبعوثون",
  },
  {"surah_number": 56, "verse_number": 48, "content": "اوءاباؤنا الاولون"},
  {"surah_number": 56, "verse_number": 49, "content": "قل ان الاولين والاخرين"},
  {
    "surah_number": 56,
    "verse_number": 50,
    "content": "لمجموعون الى ميقت يوم معلوم",
  },
  {
    "surah_number": 56,
    "verse_number": 51,
    "content": "ثم انكم ايها الضالون المكذبون",
  },
  {"surah_number": 56, "verse_number": 52, "content": "لاكلون من شجر من زقوم"},
  {"surah_number": 56, "verse_number": 53, "content": "فمالـون منها البطون"},
  {"surah_number": 56, "verse_number": 54, "content": "فشربون عليه من الحميم"},
  {"surah_number": 56, "verse_number": 55, "content": "فشربون شرب الهيم"},
  {"surah_number": 56, "verse_number": 56, "content": "هذا نزلهم يوم الدين"},
  {
    "surah_number": 56,
    "verse_number": 57,
    "content": "نحن خلقنكم فلولا تصدقون",
  },
  {"surah_number": 56, "verse_number": 58, "content": "افرءيتم ما تمنون"},
  {
    "surah_number": 56,
    "verse_number": 59,
    "content": "ءانتم تخلقونه ام نحن الخلقون",
  },
  {
    "surah_number": 56,
    "verse_number": 60,
    "content": "نحن قدرنا بينكم الموت وما نحن بمسبوقين",
  },
  {
    "surah_number": 56,
    "verse_number": 61,
    "content": "على ان نبدل امثلكم وننشئكم في ما لا تعلمون",
  },
  {
    "surah_number": 56,
    "verse_number": 62,
    "content": "ولقد علمتم النشاة الاولى فلولا تذكرون",
  },
  {"surah_number": 56, "verse_number": 63, "content": "افرءيتم ما تحرثون"},
  {
    "surah_number": 56,
    "verse_number": 64,
    "content": "ءانتم تزرعونه ام نحن الزـرعون",
  },
  {
    "surah_number": 56,
    "verse_number": 65,
    "content": "لو نشاء لجعلنه حطما فظلتم تفكهون",
  },
  {"surah_number": 56, "verse_number": 66, "content": "انا لمغرمون"},
  {"surah_number": 56, "verse_number": 67, "content": "بل نحن محرومون"},
  {
    "surah_number": 56,
    "verse_number": 68,
    "content": "افرءيتم الماء الذي تشربون",
  },
  {
    "surah_number": 56,
    "verse_number": 69,
    "content": "ءانتم انزلتموه من المزن ام نحن المنزلون",
  },
  {
    "surah_number": 56,
    "verse_number": 70,
    "content": "لو نشاء جعلنه اجاجا فلولا تشكرون",
  },
  {
    "surah_number": 56,
    "verse_number": 71,
    "content": "افرءيتم النار التي تورون",
  },
  {
    "surah_number": 56,
    "verse_number": 72,
    "content": "ءانتم انشاتم شجرتها ام نحن المنشـون",
  },
  {
    "surah_number": 56,
    "verse_number": 73,
    "content": "نحن جعلنها تذكرة ومتعا للمقوين",
  },
  {"surah_number": 56, "verse_number": 74, "content": "فسبح باسم ربك العظيم"},
  {"surah_number": 56, "verse_number": 75, "content": "فلا اقسم بموقع النجوم"},
  {
    "surah_number": 56,
    "verse_number": 76,
    "content": "وانه لقسم لو تعلمون عظيم",
  },
  {"surah_number": 56, "verse_number": 77, "content": "انه لقرءان كريم"},
  {"surah_number": 56, "verse_number": 78, "content": "في كتب مكنون"},
  {"surah_number": 56, "verse_number": 79, "content": "لا يمسه الا المطهرون"},
  {"surah_number": 56, "verse_number": 80, "content": "تنزيل من رب العلمين"},
  {
    "surah_number": 56,
    "verse_number": 81,
    "content": "افبهذا الحديث انتم مدهنون",
  },
  {
    "surah_number": 56,
    "verse_number": 82,
    "content": "وتجعلون رزقكم انكم تكذبون",
  },
  {"surah_number": 56, "verse_number": 83, "content": "فلولا اذا بلغت الحلقوم"},
  {"surah_number": 56, "verse_number": 84, "content": "وانتم حينئذ تنظرون"},
  {
    "surah_number": 56,
    "verse_number": 85,
    "content": "ونحن اقرب اليه منكم ولكن لا تبصرون",
  },
  {
    "surah_number": 56,
    "verse_number": 86,
    "content": "فلولا ان كنتم غير مدينين",
  },
  {"surah_number": 56, "verse_number": 87, "content": "ترجعونها ان كنتم صدقين"},
  {
    "surah_number": 56,
    "verse_number": 88,
    "content": "فاما ان كان من المقربين",
  },
  {"surah_number": 56, "verse_number": 89, "content": "فروح وريحان وجنت نعيم"},
  {
    "surah_number": 56,
    "verse_number": 90,
    "content": "واما ان كان من اصحب اليمين",
  },
  {"surah_number": 56, "verse_number": 91, "content": "فسلم لك من اصحب اليمين"},
  {
    "surah_number": 56,
    "verse_number": 92,
    "content": "واما ان كان من المكذبين الضالين",
  },
  {"surah_number": 56, "verse_number": 93, "content": "فنزل من حميم"},
  {"surah_number": 56, "verse_number": 94, "content": "وتصلية جحيم"},
  {"surah_number": 56, "verse_number": 95, "content": "ان هذا لهو حق اليقين"},
  {"surah_number": 56, "verse_number": 96, "content": "فسبح باسم ربك العظيم"},
  {
    "surah_number": 57,
    "verse_number": 1,
    "content": "سبح لله ما في السموت والارض وهو العزيز الحكيم",
  },
  {
    "surah_number": 57,
    "verse_number": 2,
    "content": "له ملك السموت والارض يحي ويميت وهو على كل شيء قدير",
  },
  {
    "surah_number": 57,
    "verse_number": 3,
    "content": "هو الاول والاخر والظـهر والباطن وهو بكل شيء عليم",
  },
  {
    "surah_number": 57,
    "verse_number": 4,
    "content":
        "هو الذي خلق السموت والارض في ستة ايام ثم استوى على العرش يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو معكم اين ما كنتم والله بما تعملون بصير",
  },
  {
    "surah_number": 57,
    "verse_number": 5,
    "content": "له ملك السموت والارض والى الله ترجع الامور",
  },
  {
    "surah_number": 57,
    "verse_number": 6,
    "content": "يولج اليل في النهار ويولج النهار في اليل وهو عليم بذات الصدور",
  },
  {
    "surah_number": 57,
    "verse_number": 7,
    "content":
        "ءامنوا بالله ورسوله وانفقوا مما جعلكم مستخلفين فيه فالذين ءامنوا منكم وانفقوا لهم اجر كبير",
  },
  {
    "surah_number": 57,
    "verse_number": 8,
    "content":
        "وما لكم لا تؤمنون بالله والرسول يدعوكم لتؤمنوا بربكم وقد اخذ ميثقكم ان كنتم مؤمنين",
  },
  {
    "surah_number": 57,
    "verse_number": 9,
    "content":
        "هو الذي ينزل على عبده ءايت بينت ليخرجكم من الظلمت الى النور وان الله بكم لرءوف رحيم",
  },
  {
    "surah_number": 57,
    "verse_number": 10,
    "content":
        "وما لكم الا تنفقوا في سبيل الله ولله ميرث السموت والارض لا يستوي منكم من انفق من قبل الفتح وقتل اولـئك اعظم درجة من الذين انفقوا من بعد وقتلوا وكلا وعد الله الحسنى والله بما تعملون خبير",
  },
  {
    "surah_number": 57,
    "verse_number": 11,
    "content": "من ذا الذي يقرض الله قرضا حسنا فيضعفه له وله اجر كريم",
  },
  {
    "surah_number": 57,
    "verse_number": 12,
    "content":
        "يوم ترى المؤمنين والمؤمنت يسعى نورهم بين ايديهم وبايمنهم بشرىكم اليوم جنـت تجري من تحتها الانهر خلدين فيها ذلك هو الفوز العظيم",
  },
  {
    "surah_number": 57,
    "verse_number": 13,
    "content":
        "يوم يقول المنفقون والمنفقت للذين ءامنوا انظرونا نقتبس من نوركم قيل ارجعوا وراءكم فالتمسوا نورا فضرب بينهم بسور له باب باطنه فيه الرحمة وظهره من قبله العذاب",
  },
  {
    "surah_number": 57,
    "verse_number": 14,
    "content":
        "ينادونهم الم نكن معكم قالوا بلى ولكنكم فتنتم انفسكم وتربصتم وارتبتم وغرتكم الاماني حتى جاء امر الله وغركم بالله الغرور",
  },
  {
    "surah_number": 57,
    "verse_number": 15,
    "content":
        "فاليوم لا يؤخذ منكم فدية ولا من الذين كفروا ماوىكم النار هي مولىكم وبئس المصير",
  },
  {
    "surah_number": 57,
    "verse_number": 16,
    "content":
        "الم يان للذين ءامنوا ان تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين اوتوا الكتب من قبل فطال عليهم الامد فقست قلوبهم وكثير منهم فسقون",
  },
  {
    "surah_number": 57,
    "verse_number": 17,
    "content":
        "اعلموا ان الله يحي الارض بعد موتها قد بينا لكم الايت لعلكم تعقلون",
  },
  {
    "surah_number": 57,
    "verse_number": 18,
    "content":
        "ان المصدقين والمصدقت واقرضوا الله قرضا حسنا يضعف لهم ولهم اجر كريم",
  },
  {
    "surah_number": 57,
    "verse_number": 19,
    "content":
        "والذين ءامنوا بالله ورسله اولـئك هم الصديقون والشهداء عند ربهم لهم اجرهم ونورهم والذين كفروا وكذبوا بـايتنا اولـئك اصحب الجحيم",
  },
  {
    "surah_number": 57,
    "verse_number": 20,
    "content":
        "اعلموا انما الحيوة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الامول والاولد كمثل غيث اعجب الكفار نباته ثم يهيج فترىه مصفرا ثم يكون حطما وفي الاخرة عذاب شديد ومغفرة من الله ورضون وما الحيوة الدنيا الا متع الغرور",
  },
  {
    "surah_number": 57,
    "verse_number": 21,
    "content":
        "سابقوا الى مغفرة من ربكم وجنة عرضها كعرض السماء والارض اعدت للذين ءامنوا بالله ورسله ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم",
  },
  {
    "surah_number": 57,
    "verse_number": 22,
    "content":
        "ما اصاب من مصيبة في الارض ولا في انفسكم الا في كتب من قبل ان نبراها ان ذلك على الله يسير",
  },
  {
    "surah_number": 57,
    "verse_number": 23,
    "content":
        "لكيلا تاسوا على ما فاتكم ولا تفرحوا بما ءاتىكم والله لا يحب كل مختال فخور",
  },
  {
    "surah_number": 57,
    "verse_number": 24,
    "content":
        "الذين يبخلون ويامرون الناس بالبخل ومن يتول فان الله هو الغني الحميد",
  },
  {
    "surah_number": 57,
    "verse_number": 25,
    "content":
        "لقد ارسلنا رسلنا بالبينت وانزلنا معهم الكتب والميزان ليقوم الناس بالقسط وانزلنا الحديد فيه باس شديد ومنفع للناس وليعلم الله من ينصره ورسله بالغيب ان الله قوي عزيز",
  },
  {
    "surah_number": 57,
    "verse_number": 26,
    "content":
        "ولقد ارسلنا نوحا وابرهيم وجعلنا في ذريتهما النبوة والكتب فمنهم مهتد وكثير منهم فسقون",
  },
  {
    "surah_number": 57,
    "verse_number": 27,
    "content":
        "ثم قفينا على ءاثرهم برسلنا وقفينا بعيسى ابن مريم وءاتينه الانجيل وجعلنا في قلوب الذين اتبعوه رافة ورحمة ورهبانية ابتدعوها ما كتبنها عليهم الا ابتغاء رضون الله فما رعوها حق رعايتها فـاتينا الذين ءامنوا منهم اجرهم وكثير منهم فسقون",
  },
  {
    "surah_number": 57,
    "verse_number": 28,
    "content":
        "يـايها الذين ءامنوا اتقوا الله وءامنوا برسوله يؤتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم والله غفور رحيم",
  },
  {
    "surah_number": 57,
    "verse_number": 29,
    "content":
        "لئلا يعلم اهل الكتب الا يقدرون على شيء من فضل الله وان الفضل بيد الله يؤتيه من يشاء والله ذو الفضل العظيم",
  },
  {
    "surah_number": 58,
    "verse_number": 1,
    "content":
        "قد سمع الله قول التي تجدلك في زوجها وتشتكي الى الله والله يسمع تحاوركما ان الله سميع بصير",
  },
  {
    "surah_number": 58,
    "verse_number": 2,
    "content":
        "الذين يظهرون منكم من نسائهم ما هن امهتهم ان امهتهم الا الــي ولدنهم وانهم ليقولون منكرا من القول وزورا وان الله لعفو غفور",
  },
  {
    "surah_number": 58,
    "verse_number": 3,
    "content":
        "والذين يظهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبة من قبل ان يتماسا ذلكم توعظون به والله بما تعملون خبير",
  },
  {
    "surah_number": 58,
    "verse_number": 4,
    "content":
        "فمن لم يجد فصيام شهرين متتابعين من قبل ان يتماسا فمن لم يستطع فاطعام ستين مسكينا ذلك لتؤمنوا بالله ورسوله وتلك حدود الله وللكفرين عذاب اليم",
  },
  {
    "surah_number": 58,
    "verse_number": 5,
    "content":
        "ان الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم وقد انزلنا ءايت بينت وللكفرين عذاب مهين",
  },
  {
    "surah_number": 58,
    "verse_number": 6,
    "content":
        "يوم يبعثهم الله جميعا فينبئهم بما عملوا احصىه الله ونسوه والله على كل شيء شهيد",
  },
  {
    "surah_number": 58,
    "verse_number": 7,
    "content":
        "الم تر ان الله يعلم ما في السموت وما في الارض ما يكون من نجوى ثلثة الا هو رابعهم ولا خمسة الا هو سادسهم ولا ادنى من ذلك ولا اكثر الا هو معهم اين ما كانوا ثم ينبئهم بما عملوا يوم القيمة ان الله بكل شيء عليم",
  },
  {
    "surah_number": 58,
    "verse_number": 8,
    "content":
        "الم تر الى الذين نهوا عن النجوى ثم يعودون لما نهوا عنه ويتنجون بالاثم والعدون ومعصيت الرسول واذا جاءوك حيوك بما لم يحيك به الله ويقولون في انفسهم لولا يعذبنا الله بما نقول حسبهم جهنم يصلونها فبئس المصير",
  },
  {
    "surah_number": 58,
    "verse_number": 9,
    "content":
        "يـايها الذين ءامنوا اذا تنجيتم فلا تتنجوا بالاثم والعدون ومعصيت الرسول وتنجوا بالبر والتقوى واتقوا الله الذي اليه تحشرون",
  },
  {
    "surah_number": 58,
    "verse_number": 10,
    "content":
        "انما النجوى من الشيطن ليحزن الذين ءامنوا وليس بضارهم شيـا الا باذن الله وعلى الله فليتوكل المؤمنون",
  },
  {
    "surah_number": 58,
    "verse_number": 11,
    "content":
        "يـايها الذين ءامنوا اذا قيل لكم تفسحوا في المجلس فافسحوا يفسح الله لكم واذا قيل انشزوا فانشزوا يرفع الله الذين ءامنوا منكم والذين اوتوا العلم درجت والله بما تعملون خبير",
  },
  {
    "surah_number": 58,
    "verse_number": 12,
    "content":
        "يـايها الذين ءامنوا اذا نجيتم الرسول فقدموا بين يدي نجوىكم صدقة ذلك خير لكم واطهر فان لم تجدوا فان الله غفور رحيم",
  },
  {
    "surah_number": 58,
    "verse_number": 13,
    "content":
        "ءاشفقتم ان تقدموا بين يدي نجوىكم صدقت فاذ لم تفعلوا وتاب الله عليكم فاقيموا الصلاة وءاتوا الزكوة واطيعوا الله ورسوله والله خبير بما تعملون",
  },
  {
    "surah_number": 58,
    "verse_number": 14,
    "content":
        "الم تر الى الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون على الكذب وهم يعلمون",
  },
  {
    "surah_number": 58,
    "verse_number": 15,
    "content": "اعد الله لهم عذابا شديدا انهم ساء ما كانوا يعملون",
  },
  {
    "surah_number": 58,
    "verse_number": 16,
    "content": "اتخذوا ايمنهم جنة فصدوا عن سبيل الله فلهم عذاب مهين",
  },
  {
    "surah_number": 58,
    "verse_number": 17,
    "content":
        "لن تغني عنهم امولهم ولا اولدهم من الله شيـا اولـئك اصحب النار هم فيها خلدون",
  },
  {
    "surah_number": 58,
    "verse_number": 18,
    "content":
        "يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم على شيء الا انهم هم الكذبون",
  },
  {
    "surah_number": 58,
    "verse_number": 19,
    "content":
        "استحوذ عليهم الشيطن فانسىهم ذكر الله اولـئك حزب الشيطن الا ان حزب الشيطن هم الخسرون",
  },
  {
    "surah_number": 58,
    "verse_number": 20,
    "content": "ان الذين يحادون الله ورسوله اولـئك في الاذلين",
  },
  {
    "surah_number": 58,
    "verse_number": 21,
    "content": "كتب الله لاغلبن انا ورسلي ان الله قوي عزيز",
  },
  {
    "surah_number": 58,
    "verse_number": 22,
    "content":
        "لا تجد قوما يؤمنون بالله واليوم الاخر يوادون من حاد الله ورسوله ولو كانوا ءاباءهم او ابناءهم او اخونهم او عشيرتهم اولـئك كتب في قلوبهم الايمن وايدهم بروح منه ويدخلهم جنـت تجري من تحتها الانهر خلدين فيها رضي الله عنهم ورضوا عنه اولـئك حزب الله الا ان حزب الله هم المفلحون",
  },
  {
    "surah_number": 59,
    "verse_number": 1,
    "content": "سبح لله ما في السموت وما في الارض وهو العزيز الحكيم",
  },
  {
    "surah_number": 59,
    "verse_number": 2,
    "content":
        "هو الذي اخرج الذين كفروا من اهل الكتب من ديرهم لاول الحشر ما ظننتم ان يخرجوا وظنوا انهم مانعتهم حصونهم من الله فاتىهم الله من حيث لم يحتسبوا وقذف في قلوبهم الرعب يخربون بيوتهم بايديهم وايدي المؤمنين فاعتبروا يـاولي الابصر",
  },
  {
    "surah_number": 59,
    "verse_number": 3,
    "content":
        "ولولا ان كتب الله عليهم الجلاء لعذبهم في الدنيا ولهم في الاخرة عذاب النار",
  },
  {
    "surah_number": 59,
    "verse_number": 4,
    "content": "ذلك بانهم شاقوا الله ورسوله ومن يشاق الله فان الله شديد العقاب",
  },
  {
    "surah_number": 59,
    "verse_number": 5,
    "content":
        "ما قطعتم من لينة او تركتموها قائمة على اصولها فباذن الله وليخزي الفسقين",
  },
  {
    "surah_number": 59,
    "verse_number": 6,
    "content":
        "وما افاء الله على رسوله منهم فما اوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله على من يشاء والله على كل شيء قدير",
  },
  {
    "surah_number": 59,
    "verse_number": 7,
    "content":
        "ما افاء الله على رسوله من اهل القرى فلله وللرسول ولذي القربى واليتمى والمسكين وابن السبيل كي لا يكون دولة بين الاغنياء منكم وما ءاتىكم الرسول فخذوه وما نهىكم عنه فانتهوا واتقوا الله ان الله شديد العقاب",
  },
  {
    "surah_number": 59,
    "verse_number": 8,
    "content":
        "للفقراء المهجرين الذين اخرجوا من ديرهم وامولهم يبتغون فضلا من الله ورضونا وينصرون الله ورسوله اولـئك هم الصـدقون",
  },
  {
    "surah_number": 59,
    "verse_number": 9,
    "content":
        "والذين تبوءو الدار والايمن من قبلهم يحبون من هاجر اليهم ولا يجدون في صدورهم حاجة مما اوتوا ويؤثرون على انفسهم ولو كان بهم خصاصة ومن يوق شح نفسه فاولـئك هم المفلحون",
  },
  {
    "surah_number": 59,
    "verse_number": 10,
    "content":
        "والذين جاءو من بعدهم يقولون ربنا اغفر لنا ولاخوننا الذين سبقونا بالايمن ولا تجعل في قلوبنا غلا للذين ءامنوا ربنا انك رءوف رحيم",
  },
  {
    "surah_number": 59,
    "verse_number": 11,
    "content":
        "الم تر الى الذين نافقوا يقولون لاخونهم الذين كفروا من اهل الكتب لئن اخرجتم لنخرجن معكم ولا نطيع فيكم احدا ابدا وان قوتلتم لننصرنكم والله يشهد انهم لكذبون",
  },
  {
    "surah_number": 59,
    "verse_number": 12,
    "content":
        "لئن اخرجوا لا يخرجون معهم ولئن قوتلوا لا ينصرونهم ولئن نصروهم ليولن الادبر ثم لا ينصرون",
  },
  {
    "surah_number": 59,
    "verse_number": 13,
    "content": "لانتم اشد رهبة في صدورهم من الله ذلك بانهم قوم لا يفقهون",
  },
  {
    "surah_number": 59,
    "verse_number": 14,
    "content":
        "لا يقتلونكم جميعا الا في قرى محصنة او من وراء جدر باسهم بينهم شديد تحسبهم جميعا وقلوبهم شتى ذلك بانهم قوم لا يعقلون",
  },
  {
    "surah_number": 59,
    "verse_number": 15,
    "content": "كمثل الذين من قبلهم قريبا ذاقوا وبال امرهم ولهم عذاب اليم",
  },
  {
    "surah_number": 59,
    "verse_number": 16,
    "content":
        "كمثل الشيطن اذ قال للانسن اكفر فلما كفر قال اني بريء منك اني اخاف الله رب العلمين",
  },
  {
    "surah_number": 59,
    "verse_number": 17,
    "content": "فكان عقبتهما انهما في النار خلدين فيها وذلك جزـؤا الظـلمين",
  },
  {
    "surah_number": 59,
    "verse_number": 18,
    "content":
        "يـايها الذين ءامنوا اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله ان الله خبير بما تعملون",
  },
  {
    "surah_number": 59,
    "verse_number": 19,
    "content": "ولا تكونوا كالذين نسوا الله فانسىهم انفسهم اولـئك هم الفسقون",
  },
  {
    "surah_number": 59,
    "verse_number": 20,
    "content": "لا يستوي اصحب النار واصحب الجنة اصحب الجنة هم الفائزون",
  },
  {
    "surah_number": 59,
    "verse_number": 21,
    "content":
        "لو انزلنا هذا القرءان على جبل لرايته خشعا متصدعا من خشية الله وتلك الامثل نضربها للناس لعلهم يتفكرون",
  },
  {
    "surah_number": 59,
    "verse_number": 22,
    "content": "هو الله الذي لا اله الا هو علم الغيب والشهدة هو الرحمن الرحيم",
  },
  {
    "surah_number": 59,
    "verse_number": 23,
    "content":
        "هو الله الذي لا اله الا هو الملك القدوس السلم المؤمن المهيمن العزيز الجبار المتكبر سبحن الله عما يشركون",
  },
  {
    "surah_number": 59,
    "verse_number": 24,
    "content":
        "هو الله الخلق البارئ المصور له الاسماء الحسنى يسبح له ما في السموت والارض وهو العزيز الحكيم",
  },
  {
    "surah_number": 60,
    "verse_number": 1,
    "content":
        "يـايها الذين ءامنوا لا تتخذوا عدوي وعدوكم اولياء تلقون اليهم بالمودة وقد كفروا بما جاءكم من الحق يخرجون الرسول واياكم ان تؤمنوا بالله ربكم ان كنتم خرجتم جهدا في سبيلي وابتغاء مرضاتي تسرون اليهم بالمودة وانا اعلم بما اخفيتم وما اعلنتم ومن يفعله منكم فقد ضل سواء السبيل",
  },
  {
    "surah_number": 60,
    "verse_number": 2,
    "content":
        "ان يثقفوكم يكونوا لكم اعداء ويبسطوا اليكم ايديهم والسنتهم بالسوء وودوا لو تكفرون",
  },
  {
    "surah_number": 60,
    "verse_number": 3,
    "content":
        "لن تنفعكم ارحامكم ولا اولدكم يوم القيمة يفصل بينكم والله بما تعملون بصير",
  },
  {
    "surah_number": 60,
    "verse_number": 4,
    "content":
        "قد كانت لكم اسوة حسنة في ابرهيم والذين معه اذ قالوا لقومهم انا برءـؤا منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العدوة والبغضاء ابدا حتى تؤمنوا بالله وحده الا قول ابرهيم لابيه لاستغفرن لك وما املك لك من الله من شيء ربنا عليك توكلنا واليك انبنا واليك المصير",
  },
  {
    "surah_number": 60,
    "verse_number": 5,
    "content":
        "ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا انك انت العزيز الحكيم",
  },
  {
    "surah_number": 60,
    "verse_number": 6,
    "content":
        "لقد كان لكم فيهم اسوة حسنة لمن كان يرجوا الله واليوم الاخر ومن يتول فان الله هو الغني الحميد",
  },
  {
    "surah_number": 60,
    "verse_number": 7,
    "content":
        "عسى الله ان يجعل بينكم وبين الذين عاديتم منهم مودة والله قدير والله غفور رحيم",
  },
  {
    "surah_number": 60,
    "verse_number": 8,
    "content":
        "لا ينهىكم الله عن الذين لم يقتلوكم في الدين ولم يخرجوكم من ديركم ان تبروهم وتقسطوا اليهم ان الله يحب المقسطين",
  },
  {
    "surah_number": 60,
    "verse_number": 9,
    "content":
        "انما ينهىكم الله عن الذين قتلوكم في الدين واخرجوكم من ديركم وظهروا على اخراجكم ان تولوهم ومن يتولهم فاولـئك هم الظـلمون",
  },
  {
    "surah_number": 60,
    "verse_number": 10,
    "content":
        "يـايها الذين ءامنوا اذا جاءكم المؤمنت مهجرت فامتحنوهن الله اعلم بايمنهن فان علمتموهن مؤمنت فلا ترجعوهن الى الكفار لا هن حل لهم ولا هم يحلون لهن وءاتوهم ما انفقوا ولا جناح عليكم ان تنكحوهن اذا ءاتيتموهن اجورهن ولا تمسكوا بعصم الكوافر وسـلوا ما انفقتم وليسـلوا ما انفقوا ذلكم حكم الله يحكم بينكم والله عليم حكيم",
  },
  {
    "surah_number": 60,
    "verse_number": 11,
    "content":
        "وان فاتكم شيء من ازوجكم الى الكفار فعاقبتم فـاتوا الذين ذهبت ازوجهم مثل ما انفقوا واتقوا الله الذي انتم به مؤمنون",
  },
  {
    "surah_number": 60,
    "verse_number": 12,
    "content":
        "يـايها النبي اذا جاءك المؤمنت يبايعنك على ان لا يشركن بالله شيـا ولا يسرقن ولا يزنين ولا يقتلن اولدهن ولا ياتين ببهتن يفترينه بين ايديهن وارجلهن ولا يعصينك في معروف فبايعهن واستغفر لهن الله ان الله غفور رحيم",
  },
  {
    "surah_number": 60,
    "verse_number": 13,
    "content":
        "يـايها الذين ءامنوا لا تتولوا قوما غضب الله عليهم قد يئسوا من الاخرة كما يئس الكفار من اصحب القبور",
  },
  {
    "surah_number": 61,
    "verse_number": 1,
    "content": "سبح لله ما في السموت وما في الارض وهو العزيز الحكيم",
  },
  {
    "surah_number": 61,
    "verse_number": 2,
    "content": "يـايها الذين ءامنوا لم تقولون ما لا تفعلون",
  },
  {
    "surah_number": 61,
    "verse_number": 3,
    "content": "كبر مقتا عند الله ان تقولوا ما لا تفعلون",
  },
  {
    "surah_number": 61,
    "verse_number": 4,
    "content": "ان الله يحب الذين يقتلون في سبيله صفا كانهم بنين مرصوص",
  },
  {
    "surah_number": 61,
    "verse_number": 5,
    "content":
        "واذ قال موسى لقومه يقوم لم تؤذونني وقد تعلمون اني رسول الله اليكم فلما زاغوا ازاغ الله قلوبهم والله لا يهدي القوم الفسقين",
  },
  {
    "surah_number": 61,
    "verse_number": 6,
    "content":
        "واذ قال عيسى ابن مريم يبني اسرـءيل اني رسول الله اليكم مصدقا لما بين يدي من التورىة ومبشرا برسول ياتي من بعدي اسمه احمد فلما جاءهم بالبينت قالوا هذا سحر مبين",
  },
  {
    "surah_number": 61,
    "verse_number": 7,
    "content":
        "ومن اظلم ممن افترى على الله الكذب وهو يدعى الى الاسلم والله لا يهدي القوم الظـلمين",
  },
  {
    "surah_number": 61,
    "verse_number": 8,
    "content": "يريدون ليطفـوا نور الله بافوههم والله متم نوره ولو كره الكفرون",
  },
  {
    "surah_number": 61,
    "verse_number": 9,
    "content":
        "هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون",
  },
  {
    "surah_number": 61,
    "verse_number": 10,
    "content": "يـايها الذين ءامنوا هل ادلكم على تجرة تنجيكم من عذاب اليم",
  },
  {
    "surah_number": 61,
    "verse_number": 11,
    "content":
        "تؤمنون بالله ورسوله وتجهدون في سبيل الله بامولكم وانفسكم ذلكم خير لكم ان كنتم تعلمون",
  },
  {
    "surah_number": 61,
    "verse_number": 12,
    "content":
        "يغفر لكم ذنوبكم ويدخلكم جنـت تجري من تحتها الانهر ومسكن طيبة في جنـت عدن ذلك الفوز العظيم",
  },
  {
    "surah_number": 61,
    "verse_number": 13,
    "content": "واخرى تحبونها نصر من الله وفتح قريب وبشر المؤمنين",
  },
  {
    "surah_number": 61,
    "verse_number": 14,
    "content":
        "يـايها الذين ءامنوا كونوا انصار الله كما قال عيسى ابن مريم للحواريـن من انصاري الى الله قال الحواريون نحن انصار الله فـامنت طائفة من بني اسرـءيل وكفرت طائفة فايدنا الذين ءامنوا على عدوهم فاصبحوا ظهرين",
  },
  {
    "surah_number": 62,
    "verse_number": 1,
    "content": "يسبح لله ما في السموت وما في الارض الملك القدوس العزيز الحكيم",
  },
  {
    "surah_number": 62,
    "verse_number": 2,
    "content":
        "هو الذي بعث في الاميـن رسولا منهم يتلوا عليهم ءايته ويزكيهم ويعلمهم الكتب والحكمة وان كانوا من قبل لفي ضلل مبين",
  },
  {
    "surah_number": 62,
    "verse_number": 3,
    "content": "وءاخرين منهم لما يلحقوا بهم وهو العزيز الحكيم",
  },
  {
    "surah_number": 62,
    "verse_number": 4,
    "content": "ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم",
  },
  {
    "surah_number": 62,
    "verse_number": 5,
    "content":
        "مثل الذين حملوا التورىة ثم لم يحملوها كمثل الحمار يحمل اسفارا بئس مثل القوم الذين كذبوا بـايت الله والله لا يهدي القوم الظـلمين",
  },
  {
    "surah_number": 62,
    "verse_number": 6,
    "content":
        "قل يـايها الذين هادوا ان زعمتم انكم اولياء لله من دون الناس فتمنوا الموت ان كنتم صدقين",
  },
  {
    "surah_number": 62,
    "verse_number": 7,
    "content": "ولا يتمنونه ابدا بما قدمت ايديهم والله عليم بالظـلمين",
  },
  {
    "surah_number": 62,
    "verse_number": 8,
    "content":
        "قل ان الموت الذي تفرون منه فانه ملقيكم ثم تردون الى علم الغيب والشهدة فينبئكم بما كنتم تعملون",
  },
  {
    "surah_number": 62,
    "verse_number": 9,
    "content":
        "يـايها الذين ءامنوا اذا نودي للصلوة من يوم الجمعة فاسعوا الى ذكر الله وذروا البيع ذلكم خير لكم ان كنتم تعلمون",
  },
  {
    "surah_number": 62,
    "verse_number": 10,
    "content":
        "فاذا قضيت الصلاة فانتشروا في الارض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون",
  },
  {
    "surah_number": 62,
    "verse_number": 11,
    "content":
        "واذا راوا تجرة او لهوا انفضوا اليها وتركوك قائما قل ما عند الله خير من اللهو ومن التجرة والله خير الرـزقين",
  },
  {
    "surah_number": 63,
    "verse_number": 1,
    "content":
        "اذا جاءك المنفقون قالوا نشهد انك لرسول الله والله يعلم انك لرسوله والله يشهد ان المنفقين لكذبون",
  },
  {
    "surah_number": 63,
    "verse_number": 2,
    "content": "اتخذوا ايمنهم جنة فصدوا عن سبيل الله انهم ساء ما كانوا يعملون",
  },
  {
    "surah_number": 63,
    "verse_number": 3,
    "content": "ذلك بانهم ءامنوا ثم كفروا فطبع على قلوبهم فهم لا يفقهون",
  },
  {
    "surah_number": 63,
    "verse_number": 4,
    "content":
        "واذا رايتهم تعجبك اجسامهم وان يقولوا تسمع لقولهم كانهم خشب مسندة يحسبون كل صيحة عليهم هم العدو فاحذرهم قتلهم الله انى يؤفكون",
  },
  {
    "surah_number": 63,
    "verse_number": 5,
    "content":
        "واذا قيل لهم تعالوا يستغفر لكم رسول الله لووا رءوسهم ورايتهم يصدون وهم مستكبرون",
  },
  {
    "surah_number": 63,
    "verse_number": 6,
    "content":
        "سواء عليهم استغفرت لهم ام لم تستغفر لهم لن يغفر الله لهم ان الله لا يهدي القوم الفسقين",
  },
  {
    "surah_number": 63,
    "verse_number": 7,
    "content":
        "هم الذين يقولون لا تنفقوا على من عند رسول الله حتى ينفضوا ولله خزائن السموت والارض ولكن المنفقين لا يفقهون",
  },
  {
    "surah_number": 63,
    "verse_number": 8,
    "content":
        "يقولون لئن رجعنا الى المدينة ليخرجن الاعز منها الاذل ولله العزة ولرسوله وللمؤمنين ولكن المنفقين لا يعلمون",
  },
  {
    "surah_number": 63,
    "verse_number": 9,
    "content":
        "يـايها الذين ءامنوا لا تلهكم امولكم ولا اولدكم عن ذكر الله ومن يفعل ذلك فاولـئك هم الخسرون",
  },
  {
    "surah_number": 63,
    "verse_number": 10,
    "content":
        "وانفقوا من ما رزقنكم من قبل ان ياتي احدكم الموت فيقول رب لولا اخرتني الى اجل قريب فاصدق واكن من الصـلحين",
  },
  {
    "surah_number": 63,
    "verse_number": 11,
    "content": "ولن يؤخر الله نفسا اذا جاء اجلها والله خبير بما تعملون",
  },
  {
    "surah_number": 64,
    "verse_number": 1,
    "content":
        "يسبح لله ما في السموت وما في الارض له الملك وله الحمد وهو على كل شيء قدير",
  },
  {
    "surah_number": 64,
    "verse_number": 2,
    "content": "هو الذي خلقكم فمنكم كافر ومنكم مؤمن والله بما تعملون بصير",
  },
  {
    "surah_number": 64,
    "verse_number": 3,
    "content": "خلق السموت والارض بالحق وصوركم فاحسن صوركم واليه المصير",
  },
  {
    "surah_number": 64,
    "verse_number": 4,
    "content":
        "يعلم ما في السموت والارض ويعلم ما تسرون وما تعلنون والله عليم بذات الصدور",
  },
  {
    "surah_number": 64,
    "verse_number": 5,
    "content":
        "الم ياتكم نبؤا الذين كفروا من قبل فذاقوا وبال امرهم ولهم عذاب اليم",
  },
  {
    "surah_number": 64,
    "verse_number": 6,
    "content":
        "ذلك بانه كانت تاتيهم رسلهم بالبينت فقالوا ابشر يهدوننا فكفروا وتولوا واستغنى الله والله غني حميد",
  },
  {
    "surah_number": 64,
    "verse_number": 7,
    "content":
        "زعم الذين كفروا ان لن يبعثوا قل بلى وربي لتبعثن ثم لتنبؤن بما عملتم وذلك على الله يسير",
  },
  {
    "surah_number": 64,
    "verse_number": 8,
    "content": "فـامنوا بالله ورسوله والنور الذي انزلنا والله بما تعملون خبير",
  },
  {
    "surah_number": 64,
    "verse_number": 9,
    "content":
        "يوم يجمعكم ليوم الجمع ذلك يوم التغابن ومن يؤمن بالله ويعمل صلحا يكفر عنه سيـاته ويدخله جنـت تجري من تحتها الانهر خلدين فيها ابدا ذلك الفوز العظيم",
  },
  {
    "surah_number": 64,
    "verse_number": 10,
    "content":
        "والذين كفروا وكذبوا بـايتنا اولـئك اصحب النار خلدين فيها وبئس المصير",
  },
  {
    "surah_number": 64,
    "verse_number": 11,
    "content":
        "ما اصاب من مصيبة الا باذن الله ومن يؤمن بالله يهد قلبه والله بكل شيء عليم",
  },
  {
    "surah_number": 64,
    "verse_number": 12,
    "content":
        "واطيعوا الله واطيعوا الرسول فان توليتم فانما على رسولنا البلغ المبين",
  },
  {
    "surah_number": 64,
    "verse_number": 13,
    "content": "الله لا اله الا هو وعلى الله فليتوكل المؤمنون",
  },
  {
    "surah_number": 64,
    "verse_number": 14,
    "content":
        "يـايها الذين ءامنوا ان من ازوجكم واولدكم عدوا لكم فاحذروهم وان تعفوا وتصفحوا وتغفروا فان الله غفور رحيم",
  },
  {
    "surah_number": 64,
    "verse_number": 15,
    "content": "انما امولكم واولدكم فتنة والله عنده اجر عظيم",
  },
  {
    "surah_number": 64,
    "verse_number": 16,
    "content":
        "فاتقوا الله ما استطعتم واسمعوا واطيعوا وانفقوا خيرا لانفسكم ومن يوق شح نفسه فاولـئك هم المفلحون",
  },
  {
    "surah_number": 64,
    "verse_number": 17,
    "content": "ان تقرضوا الله قرضا حسنا يضعفه لكم ويغفر لكم والله شكور حليم",
  },
  {
    "surah_number": 64,
    "verse_number": 18,
    "content": "علم الغيب والشهدة العزيز الحكيم",
  },
  {
    "surah_number": 65,
    "verse_number": 1,
    "content":
        "يـايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العدة واتقوا الله ربكم لا تخرجوهن من بيوتهن ولا يخرجن الا ان ياتين بفحشة مبينة وتلك حدود الله ومن يتعد حدود الله فقد ظلم نفسه لا تدري لعل الله يحدث بعد ذلك امرا",
  },
  {
    "surah_number": 65,
    "verse_number": 2,
    "content":
        "فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروف واشهدوا ذوي عدل منكم واقيموا الشهدة لله ذلكم يوعظ به من كان يؤمن بالله واليوم الاخر ومن يتق الله يجعل له مخرجا",
  },
  {
    "surah_number": 65,
    "verse_number": 3,
    "content":
        "ويرزقه من حيث لا يحتسب ومن يتوكل على الله فهو حسبه ان الله بلغ امره قد جعل الله لكل شيء قدرا",
  },
  {
    "surah_number": 65,
    "verse_number": 4,
    "content":
        "والــي يئسن من المحيض من نسائكم ان ارتبتم فعدتهن ثلثة اشهر والــي لم يحضن واولت الاحمال اجلهن ان يضعن حملهن ومن يتق الله يجعل له من امره يسرا",
  },
  {
    "surah_number": 65,
    "verse_number": 5,
    "content":
        "ذلك امر الله انزله اليكم ومن يتق الله يكفر عنه سيـاته ويعظم له اجرا",
  },
  {
    "surah_number": 65,
    "verse_number": 6,
    "content":
        "اسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا عليهن وان كن اولت حمل فانفقوا عليهن حتى يضعن حملهن فان ارضعن لكم فـاتوهن اجورهن واتمروا بينكم بمعروف وان تعاسرتم فسترضع له اخرى",
  },
  {
    "surah_number": 65,
    "verse_number": 7,
    "content":
        "لينفق ذو سعة من سعته ومن قدر عليه رزقه فلينفق مما ءاتىه الله لا يكلف الله نفسا الا ما ءاتىها سيجعل الله بعد عسر يسرا",
  },
  {
    "surah_number": 65,
    "verse_number": 8,
    "content":
        "وكاين من قرية عتت عن امر ربها ورسله فحاسبنها حسابا شديدا وعذبنها عذابا نكرا",
  },
  {
    "surah_number": 65,
    "verse_number": 9,
    "content": "فذاقت وبال امرها وكان عقبة امرها خسرا",
  },
  {
    "surah_number": 65,
    "verse_number": 10,
    "content":
        "اعد الله لهم عذابا شديدا فاتقوا الله يـاولي الالبب الذين ءامنوا قد انزل الله اليكم ذكرا",
  },
  {
    "surah_number": 65,
    "verse_number": 11,
    "content":
        "رسولا يتلوا عليكم ءايت الله مبينت ليخرج الذين ءامنوا وعملوا الصـلحت من الظلمت الى النور ومن يؤمن بالله ويعمل صلحا يدخله جنـت تجري من تحتها الانهر خلدين فيها ابدا قد احسن الله له رزقا",
  },
  {
    "surah_number": 65,
    "verse_number": 12,
    "content":
        "الله الذي خلق سبع سموت ومن الارض مثلهن يتنزل الامر بينهن لتعلموا ان الله على كل شيء قدير وان الله قد احاط بكل شيء علما",
  },
  {
    "surah_number": 66,
    "verse_number": 1,
    "content":
        "يـايها النبي لم تحرم ما احل الله لك تبتغي مرضات ازوجك والله غفور رحيم",
  },
  {
    "surah_number": 66,
    "verse_number": 2,
    "content": "قد فرض الله لكم تحلة ايمنكم والله مولىكم وهو العليم الحكيم",
  },
  {
    "surah_number": 66,
    "verse_number": 3,
    "content":
        "واذ اسر النبي الى بعض ازوجه حديثا فلما نبات به واظهره الله عليه عرف بعضه واعرض عن بعض فلما نباها به قالت من انباك هذا قال نباني العليم الخبير",
  },
  {
    "surah_number": 66,
    "verse_number": 4,
    "content":
        "ان تتوبا الى الله فقد صغت قلوبكما وان تظهرا عليه فان الله هو مولىه وجبريل وصلح المؤمنين والملـئكة بعد ذلك ظهير",
  },
  {
    "surah_number": 66,
    "verse_number": 5,
    "content":
        "عسى ربه ان طلقكن ان يبدله ازوجا خيرا منكن مسلمت مؤمنت قنتت تـئبت عبدت سـئحت ثيبت وابكارا",
  },
  {
    "surah_number": 66,
    "verse_number": 6,
    "content":
        "يـايها الذين ءامنوا قوا انفسكم واهليكم نارا وقودها الناس والحجارة عليها ملـئكة غلاظ شداد لا يعصون الله ما امرهم ويفعلون ما يؤمرون",
  },
  {
    "surah_number": 66,
    "verse_number": 7,
    "content": "يـايها الذين كفروا لا تعتذروا اليوم انما تجزون ما كنتم تعملون",
  },
  {
    "surah_number": 66,
    "verse_number": 8,
    "content":
        "يـايها الذين ءامنوا توبوا الى الله توبة نصوحا عسى ربكم ان يكفر عنكم سيـاتكم ويدخلكم جنـت تجري من تحتها الانهر يوم لا يخزي الله النبي والذين ءامنوا معه نورهم يسعى بين ايديهم وبايمنهم يقولون ربنا اتمم لنا نورنا واغفر لنا انك على كل شيء قدير",
  },
  {
    "surah_number": 66,
    "verse_number": 9,
    "content":
        "يـايها النبي جهد الكفار والمنفقين واغلظ عليهم وماوىهم جهنم وبئس المصير",
  },
  {
    "surah_number": 66,
    "verse_number": 10,
    "content":
        "ضرب الله مثلا للذين كفروا امرات نوح وامرات لوط كانتا تحت عبدين من عبادنا صلحين فخانتاهما فلم يغنيا عنهما من الله شيـا وقيل ادخلا النار مع الدـخلين",
  },
  {
    "surah_number": 66,
    "verse_number": 11,
    "content":
        "وضرب الله مثلا للذين ءامنوا امرات فرعون اذ قالت رب ابن لي عندك بيتا في الجنة ونجني من فرعون وعمله ونجني من القوم الظـلمين",
  },
  {
    "surah_number": 66,
    "verse_number": 12,
    "content":
        "ومريم ابنت عمرن التي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمت ربها وكتبه وكانت من القنتين",
  },
  {
    "surah_number": 67,
    "verse_number": 1,
    "content": "تبرك الذي بيده الملك وهو على كل شيء قدير",
  },
  {
    "surah_number": 67,
    "verse_number": 2,
    "content":
        "الذي خلق الموت والحيوة ليبلوكم ايكم احسن عملا وهو العزيز الغفور",
  },
  {
    "surah_number": 67,
    "verse_number": 3,
    "content":
        "الذي خلق سبع سموت طباقا ما ترى في خلق الرحمن من تفوت فارجع البصر هل ترى من فطور",
  },
  {
    "surah_number": 67,
    "verse_number": 4,
    "content": "ثم ارجع البصر كرتين ينقلب اليك البصر خاسئا وهو حسير",
  },
  {
    "surah_number": 67,
    "verse_number": 5,
    "content":
        "ولقد زينا السماء الدنيا بمصبيح وجعلنها رجوما للشيطين واعتدنا لهم عذاب السعير",
  },
  {
    "surah_number": 67,
    "verse_number": 6,
    "content": "وللذين كفروا بربهم عذاب جهنم وبئس المصير",
  },
  {
    "surah_number": 67,
    "verse_number": 7,
    "content": "اذا القوا فيها سمعوا لها شهيقا وهي تفور",
  },
  {
    "surah_number": 67,
    "verse_number": 8,
    "content":
        "تكاد تميز من الغيظ كلما القي فيها فوج سالهم خزنتها الم ياتكم نذير",
  },
  {
    "surah_number": 67,
    "verse_number": 9,
    "content":
        "قالوا بلى قد جاءنا نذير فكذبنا وقلنا ما نزل الله من شيء ان انتم الا في ضلل كبير",
  },
  {
    "surah_number": 67,
    "verse_number": 10,
    "content": "وقالوا لو كنا نسمع او نعقل ما كنا في اصحب السعير",
  },
  {
    "surah_number": 67,
    "verse_number": 11,
    "content": "فاعترفوا بذنبهم فسحقا لاصحب السعير",
  },
  {
    "surah_number": 67,
    "verse_number": 12,
    "content": "ان الذين يخشون ربهم بالغيب لهم مغفرة واجر كبير",
  },
  {
    "surah_number": 67,
    "verse_number": 13,
    "content": "واسروا قولكم او اجهروا به انه عليم بذات الصدور",
  },
  {
    "surah_number": 67,
    "verse_number": 14,
    "content": "الا يعلم من خلق وهو اللطيف الخبير",
  },
  {
    "surah_number": 67,
    "verse_number": 15,
    "content":
        "هو الذي جعل لكم الارض ذلولا فامشوا في مناكبها وكلوا من رزقه واليه النشور",
  },
  {
    "surah_number": 67,
    "verse_number": 16,
    "content": "ءامنتم من في السماء ان يخسف بكم الارض فاذا هي تمور",
  },
  {
    "surah_number": 67,
    "verse_number": 17,
    "content": "ام امنتم من في السماء ان يرسل عليكم حاصبا فستعلمون كيف نذير",
  },
  {
    "surah_number": 67,
    "verse_number": 18,
    "content": "ولقد كذب الذين من قبلهم فكيف كان نكير",
  },
  {
    "surah_number": 67,
    "verse_number": 19,
    "content":
        "اولم يروا الى الطير فوقهم صـفـت ويقبضن ما يمسكهن الا الرحمن انه بكل شيء بصير",
  },
  {
    "surah_number": 67,
    "verse_number": 20,
    "content":
        "امن هذا الذي هو جند لكم ينصركم من دون الرحمن ان الكفرون الا في غرور",
  },
  {
    "surah_number": 67,
    "verse_number": 21,
    "content": "امن هذا الذي يرزقكم ان امسك رزقه بل لجوا في عتو ونفور",
  },
  {
    "surah_number": 67,
    "verse_number": 22,
    "content": "افمن يمشي مكبا على وجهه اهدى امن يمشي سويا على صراط مستقيم",
  },
  {
    "surah_number": 67,
    "verse_number": 23,
    "content":
        "قل هو الذي انشاكم وجعل لكم السمع والابصر والافـدة قليلا ما تشكرون",
  },
  {
    "surah_number": 67,
    "verse_number": 24,
    "content": "قل هو الذي ذراكم في الارض واليه تحشرون",
  },
  {
    "surah_number": 67,
    "verse_number": 25,
    "content": "ويقولون متى هذا الوعد ان كنتم صدقين",
  },
  {
    "surah_number": 67,
    "verse_number": 26,
    "content": "قل انما العلم عند الله وانما انا نذير مبين",
  },
  {
    "surah_number": 67,
    "verse_number": 27,
    "content":
        "فلما راوه زلفة سيـت وجوه الذين كفروا وقيل هذا الذي كنتم به تدعون",
  },
  {
    "surah_number": 67,
    "verse_number": 28,
    "content":
        "قل ارءيتم ان اهلكني الله ومن معي او رحمنا فمن يجير الكفرين من عذاب اليم",
  },
  {
    "surah_number": 67,
    "verse_number": 29,
    "content": "قل هو الرحمن ءامنا به وعليه توكلنا فستعلمون من هو في ضلل مبين",
  },
  {
    "surah_number": 67,
    "verse_number": 30,
    "content": "قل ارءيتم ان اصبح ماؤكم غورا فمن ياتيكم بماء معين",
  },
  {"surah_number": 68, "verse_number": 1, "content": "ن والقلم وما يسطرون"},
  {"surah_number": 68, "verse_number": 2, "content": "ما انت بنعمة ربك بمجنون"},
  {"surah_number": 68, "verse_number": 3, "content": "وان لك لاجرا غير ممنون"},
  {"surah_number": 68, "verse_number": 4, "content": "وانك لعلى خلق عظيم"},
  {"surah_number": 68, "verse_number": 5, "content": "فستبصر ويبصرون"},
  {"surah_number": 68, "verse_number": 6, "content": "باييكم المفتون"},
  {
    "surah_number": 68,
    "verse_number": 7,
    "content": "ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين",
  },
  {"surah_number": 68, "verse_number": 8, "content": "فلا تطع المكذبين"},
  {"surah_number": 68, "verse_number": 9, "content": "ودوا لو تدهن فيدهنون"},
  {"surah_number": 68, "verse_number": 10, "content": "ولا تطع كل حلاف مهين"},
  {"surah_number": 68, "verse_number": 11, "content": "هماز مشاء بنميم"},
  {"surah_number": 68, "verse_number": 12, "content": "مناع للخير معتد اثيم"},
  {"surah_number": 68, "verse_number": 13, "content": "عتل بعد ذلك زنيم"},
  {"surah_number": 68, "verse_number": 14, "content": "ان كان ذا مال وبنين"},
  {
    "surah_number": 68,
    "verse_number": 15,
    "content": "اذا تتلى عليه ءايتنا قال اسطير الاولين",
  },
  {"surah_number": 68, "verse_number": 16, "content": "سنسمه على الخرطوم"},
  {
    "surah_number": 68,
    "verse_number": 17,
    "content": "انا بلونهم كما بلونا اصحب الجنة اذ اقسموا ليصرمنها مصبحين",
  },
  {"surah_number": 68, "verse_number": 18, "content": "ولا يستثنون"},
  {
    "surah_number": 68,
    "verse_number": 19,
    "content": "فطاف عليها طائف من ربك وهم نائمون",
  },
  {"surah_number": 68, "verse_number": 20, "content": "فاصبحت كالصريم"},
  {"surah_number": 68, "verse_number": 21, "content": "فتنادوا مصبحين"},
  {
    "surah_number": 68,
    "verse_number": 22,
    "content": "ان اغدوا على حرثكم ان كنتم صرمين",
  },
  {"surah_number": 68, "verse_number": 23, "content": "فانطلقوا وهم يتخفتون"},
  {
    "surah_number": 68,
    "verse_number": 24,
    "content": "ان لا يدخلنها اليوم عليكم مسكين",
  },
  {"surah_number": 68, "verse_number": 25, "content": "وغدوا على حرد قدرين"},
  {
    "surah_number": 68,
    "verse_number": 26,
    "content": "فلما راوها قالوا انا لضالون",
  },
  {"surah_number": 68, "verse_number": 27, "content": "بل نحن محرومون"},
  {
    "surah_number": 68,
    "verse_number": 28,
    "content": "قال اوسطهم الم اقل لكم لولا تسبحون",
  },
  {
    "surah_number": 68,
    "verse_number": 29,
    "content": "قالوا سبحن ربنا انا كنا ظلمين",
  },
  {
    "surah_number": 68,
    "verse_number": 30,
    "content": "فاقبل بعضهم على بعض يتلومون",
  },
  {
    "surah_number": 68,
    "verse_number": 31,
    "content": "قالوا يويلنا انا كنا طغين",
  },
  {
    "surah_number": 68,
    "verse_number": 32,
    "content": "عسى ربنا ان يبدلنا خيرا منها انا الى ربنا رغبون",
  },
  {
    "surah_number": 68,
    "verse_number": 33,
    "content": "كذلك العذاب ولعذاب الاخرة اكبر لو كانوا يعلمون",
  },
  {
    "surah_number": 68,
    "verse_number": 34,
    "content": "ان للمتقين عند ربهم جنـت النعيم",
  },
  {
    "surah_number": 68,
    "verse_number": 35,
    "content": "افنجعل المسلمين كالمجرمين",
  },
  {"surah_number": 68, "verse_number": 36, "content": "ما لكم كيف تحكمون"},
  {"surah_number": 68, "verse_number": 37, "content": "ام لكم كتب فيه تدرسون"},
  {"surah_number": 68, "verse_number": 38, "content": "ان لكم فيه لما تخيرون"},
  {
    "surah_number": 68,
    "verse_number": 39,
    "content": "ام لكم ايمن علينا بلغة الى يوم القيمة ان لكم لما تحكمون",
  },
  {"surah_number": 68, "verse_number": 40, "content": "سلهم ايهم بذلك زعيم"},
  {
    "surah_number": 68,
    "verse_number": 41,
    "content": "ام لهم شركاء فلياتوا بشركائهم ان كانوا صدقين",
  },
  {
    "surah_number": 68,
    "verse_number": 42,
    "content": "يوم يكشف عن ساق ويدعون الى السجود فلا يستطيعون",
  },
  {
    "surah_number": 68,
    "verse_number": 43,
    "content": "خشعة ابصرهم ترهقهم ذلة وقد كانوا يدعون الى السجود وهم سلمون",
  },
  {
    "surah_number": 68,
    "verse_number": 44,
    "content": "فذرني ومن يكذب بهذا الحديث سنستدرجهم من حيث لا يعلمون",
  },
  {"surah_number": 68, "verse_number": 45, "content": "واملي لهم ان كيدي متين"},
  {
    "surah_number": 68,
    "verse_number": 46,
    "content": "ام تسـلهم اجرا فهم من مغرم مثقلون",
  },
  {
    "surah_number": 68,
    "verse_number": 47,
    "content": "ام عندهم الغيب فهم يكتبون",
  },
  {
    "surah_number": 68,
    "verse_number": 48,
    "content": "فاصبر لحكم ربك ولا تكن كصاحب الحوت اذ نادى وهو مكظوم",
  },
  {
    "surah_number": 68,
    "verse_number": 49,
    "content": "لولا ان تدركه نعمة من ربه لنبذ بالعراء وهو مذموم",
  },
  {
    "surah_number": 68,
    "verse_number": 50,
    "content": "فاجتبه ربه فجعله من الصـلحين",
  },
  {
    "surah_number": 68,
    "verse_number": 51,
    "content":
        "وان يكاد الذين كفروا ليزلقونك بابصرهم لما سمعوا الذكر ويقولون انه لمجنون",
  },
  {"surah_number": 68, "verse_number": 52, "content": "وما هو الا ذكر للعلمين"},
  {"surah_number": 69, "verse_number": 1, "content": "الحاقة"},
  {"surah_number": 69, "verse_number": 2, "content": "ما الحاقة"},
  {"surah_number": 69, "verse_number": 3, "content": "وما ادرىك ما الحاقة"},
  {"surah_number": 69, "verse_number": 4, "content": "كذبت ثمود وعاد بالقارعة"},
  {
    "surah_number": 69,
    "verse_number": 5,
    "content": "فاما ثمود فاهلكوا بالطاغية",
  },
  {
    "surah_number": 69,
    "verse_number": 6,
    "content": "واما عاد فاهلكوا بريح صرصر عاتية",
  },
  {
    "surah_number": 69,
    "verse_number": 7,
    "content":
        "سخرها عليهم سبع ليال وثمنية ايام حسوما فترى القوم فيها صرعى كانهم اعجاز نخل خاوية",
  },
  {"surah_number": 69, "verse_number": 8, "content": "فهل ترى لهم من باقية"},
  {
    "surah_number": 69,
    "verse_number": 9,
    "content": "وجاء فرعون ومن قبله والمؤتفكت بالخاطئة",
  },
  {
    "surah_number": 69,
    "verse_number": 10,
    "content": "فعصوا رسول ربهم فاخذهم اخذة رابية",
  },
  {
    "surah_number": 69,
    "verse_number": 11,
    "content": "انا لما طغا الماء حملنكم في الجارية",
  },
  {
    "surah_number": 69,
    "verse_number": 12,
    "content": "لنجعلها لكم تذكرة وتعيها اذن وعية",
  },
  {
    "surah_number": 69,
    "verse_number": 13,
    "content": "فاذا نفخ في الصور نفخة وحدة",
  },
  {
    "surah_number": 69,
    "verse_number": 14,
    "content": "وحملت الارض والجبال فدكتا دكة وحدة",
  },
  {"surah_number": 69, "verse_number": 15, "content": "فيومئذ وقعت الواقعة"},
  {
    "surah_number": 69,
    "verse_number": 16,
    "content": "وانشقت السماء فهي يومئذ واهية",
  },
  {
    "surah_number": 69,
    "verse_number": 17,
    "content": "والملك على ارجائها ويحمل عرش ربك فوقهم يومئذ ثمنية",
  },
  {
    "surah_number": 69,
    "verse_number": 18,
    "content": "يومئذ تعرضون لا تخفى منكم خافية",
  },
  {
    "surah_number": 69,
    "verse_number": 19,
    "content": "فاما من اوتي كتبه بيمينه فيقول هاؤم اقرءوا كتبيه",
  },
  {
    "surah_number": 69,
    "verse_number": 20,
    "content": "اني ظننت اني ملق حسابيه",
  },
  {"surah_number": 69, "verse_number": 21, "content": "فهو في عيشة راضية"},
  {"surah_number": 69, "verse_number": 22, "content": "في جنة عالية"},
  {"surah_number": 69, "verse_number": 23, "content": "قطوفها دانية"},
  {
    "surah_number": 69,
    "verse_number": 24,
    "content": "كلوا واشربوا هنيـا بما اسلفتم في الايام الخالية",
  },
  {
    "surah_number": 69,
    "verse_number": 25,
    "content": "واما من اوتي كتبه بشماله فيقول يليتني لم اوت كتبيه",
  },
  {"surah_number": 69, "verse_number": 26, "content": "ولم ادر ما حسابيه"},
  {"surah_number": 69, "verse_number": 27, "content": "يليتها كانت القاضية"},
  {"surah_number": 69, "verse_number": 28, "content": "ما اغنى عني ماليه"},
  {"surah_number": 69, "verse_number": 29, "content": "هلك عني سلطنيه"},
  {"surah_number": 69, "verse_number": 30, "content": "خذوه فغلوه"},
  {"surah_number": 69, "verse_number": 31, "content": "ثم الجحيم صلوه"},
  {
    "surah_number": 69,
    "verse_number": 32,
    "content": "ثم في سلسلة ذرعها سبعون ذراعا فاسلكوه",
  },
  {
    "surah_number": 69,
    "verse_number": 33,
    "content": "انه كان لا يؤمن بالله العظيم",
  },
  {
    "surah_number": 69,
    "verse_number": 34,
    "content": "ولا يحض على طعام المسكين",
  },
  {
    "surah_number": 69,
    "verse_number": 35,
    "content": "فليس له اليوم ههنا حميم",
  },
  {"surah_number": 69, "verse_number": 36, "content": "ولا طعام الا من غسلين"},
  {"surah_number": 69, "verse_number": 37, "content": "لا ياكله الا الخطـون"},
  {"surah_number": 69, "verse_number": 38, "content": "فلا اقسم بما تبصرون"},
  {"surah_number": 69, "verse_number": 39, "content": "وما لا تبصرون"},
  {"surah_number": 69, "verse_number": 40, "content": "انه لقول رسول كريم"},
  {
    "surah_number": 69,
    "verse_number": 41,
    "content": "وما هو بقول شاعر قليلا ما تؤمنون",
  },
  {
    "surah_number": 69,
    "verse_number": 42,
    "content": "ولا بقول كاهن قليلا ما تذكرون",
  },
  {"surah_number": 69, "verse_number": 43, "content": "تنزيل من رب العلمين"},
  {
    "surah_number": 69,
    "verse_number": 44,
    "content": "ولو تقول علينا بعض الاقاويل",
  },
  {"surah_number": 69, "verse_number": 45, "content": "لاخذنا منه باليمين"},
  {"surah_number": 69, "verse_number": 46, "content": "ثم لقطعنا منه الوتين"},
  {
    "surah_number": 69,
    "verse_number": 47,
    "content": "فما منكم من احد عنه حجزين",
  },
  {"surah_number": 69, "verse_number": 48, "content": "وانه لتذكرة للمتقين"},
  {
    "surah_number": 69,
    "verse_number": 49,
    "content": "وانا لنعلم ان منكم مكذبين",
  },
  {"surah_number": 69, "verse_number": 50, "content": "وانه لحسرة على الكفرين"},
  {"surah_number": 69, "verse_number": 51, "content": "وانه لحق اليقين"},
  {"surah_number": 69, "verse_number": 52, "content": "فسبح باسم ربك العظيم"},
  {"surah_number": 70, "verse_number": 1, "content": "سال سائل بعذاب واقع"},
  {"surah_number": 70, "verse_number": 2, "content": "للكفرين ليس له دافع"},
  {"surah_number": 70, "verse_number": 3, "content": "من الله ذي المعارج"},
  {
    "surah_number": 70,
    "verse_number": 4,
    "content": "تعرج الملـئكة والروح اليه في يوم كان مقداره خمسين الف سنة",
  },
  {"surah_number": 70, "verse_number": 5, "content": "فاصبر صبرا جميلا"},
  {"surah_number": 70, "verse_number": 6, "content": "انهم يرونه بعيدا"},
  {"surah_number": 70, "verse_number": 7, "content": "ونرىه قريبا"},
  {"surah_number": 70, "verse_number": 8, "content": "يوم تكون السماء كالمهل"},
  {"surah_number": 70, "verse_number": 9, "content": "وتكون الجبال كالعهن"},
  {"surah_number": 70, "verse_number": 10, "content": "ولا يسـل حميم حميما"},
  {
    "surah_number": 70,
    "verse_number": 11,
    "content": "يبصرونهم يود المجرم لو يفتدي من عذاب يومئذ ببنيه",
  },
  {"surah_number": 70, "verse_number": 12, "content": "وصحبته واخيه"},
  {"surah_number": 70, "verse_number": 13, "content": "وفصيلته التي تـويه"},
  {
    "surah_number": 70,
    "verse_number": 14,
    "content": "ومن في الارض جميعا ثم ينجيه",
  },
  {"surah_number": 70, "verse_number": 15, "content": "كلا انها لظى"},
  {"surah_number": 70, "verse_number": 16, "content": "نزاعة للشوى"},
  {"surah_number": 70, "verse_number": 17, "content": "تدعوا من ادبر وتولى"},
  {"surah_number": 70, "verse_number": 18, "content": "وجمع فاوعى"},
  {"surah_number": 70, "verse_number": 19, "content": "ان الانسن خلق هلوعا"},
  {"surah_number": 70, "verse_number": 20, "content": "اذا مسه الشر جزوعا"},
  {"surah_number": 70, "verse_number": 21, "content": "واذا مسه الخير منوعا"},
  {"surah_number": 70, "verse_number": 22, "content": "الا المصلين"},
  {
    "surah_number": 70,
    "verse_number": 23,
    "content": "الذين هم على صلاتهم دائمون",
  },
  {
    "surah_number": 70,
    "verse_number": 24,
    "content": "والذين في امولهم حق معلوم",
  },
  {"surah_number": 70, "verse_number": 25, "content": "للسائل والمحروم"},
  {
    "surah_number": 70,
    "verse_number": 26,
    "content": "والذين يصدقون بيوم الدين",
  },
  {
    "surah_number": 70,
    "verse_number": 27,
    "content": "والذين هم من عذاب ربهم مشفقون",
  },
  {"surah_number": 70, "verse_number": 28, "content": "ان عذاب ربهم غير مامون"},
  {
    "surah_number": 70,
    "verse_number": 29,
    "content": "والذين هم لفروجهم حفظون",
  },
  {
    "surah_number": 70,
    "verse_number": 30,
    "content": "الا على ازوجهم او ما ملكت ايمنهم فانهم غير ملومين",
  },
  {
    "surah_number": 70,
    "verse_number": 31,
    "content": "فمن ابتغى وراء ذلك فاولـئك هم العادون",
  },
  {
    "surah_number": 70,
    "verse_number": 32,
    "content": "والذين هم لامنتهم وعهدهم رعون",
  },
  {
    "surah_number": 70,
    "verse_number": 33,
    "content": "والذين هم بشهدتهم قائمون",
  },
  {
    "surah_number": 70,
    "verse_number": 34,
    "content": "والذين هم على صلاتهم يحافظون",
  },
  {"surah_number": 70, "verse_number": 35, "content": "اولـئك في جنـت مكرمون"},
  {
    "surah_number": 70,
    "verse_number": 36,
    "content": "فمال الذين كفروا قبلك مهطعين",
  },
  {
    "surah_number": 70,
    "verse_number": 37,
    "content": "عن اليمين وعن الشمال عزين",
  },
  {
    "surah_number": 70,
    "verse_number": 38,
    "content": "ايطمع كل امري منهم ان يدخل جنة نعيم",
  },
  {
    "surah_number": 70,
    "verse_number": 39,
    "content": "كلا انا خلقنهم مما يعلمون",
  },
  {
    "surah_number": 70,
    "verse_number": 40,
    "content": "فلا اقسم برب المشرق والمغرب انا لقدرون",
  },
  {
    "surah_number": 70,
    "verse_number": 41,
    "content": "على ان نبدل خيرا منهم وما نحن بمسبوقين",
  },
  {
    "surah_number": 70,
    "verse_number": 42,
    "content": "فذرهم يخوضوا ويلعبوا حتى يلقوا يومهم الذي يوعدون",
  },
  {
    "surah_number": 70,
    "verse_number": 43,
    "content": "يوم يخرجون من الاجداث سراعا كانهم الى نصب يوفضون",
  },
  {
    "surah_number": 70,
    "verse_number": 44,
    "content": "خشعة ابصرهم ترهقهم ذلة ذلك اليوم الذي كانوا يوعدون",
  },
  {
    "surah_number": 71,
    "verse_number": 1,
    "content":
        "انا ارسلنا نوحا الى قومه ان انذر قومك من قبل ان ياتيهم عذاب اليم",
  },
  {
    "surah_number": 71,
    "verse_number": 2,
    "content": "قال يقوم اني لكم نذير مبين",
  },
  {
    "surah_number": 71,
    "verse_number": 3,
    "content": "ان اعبدوا الله واتقوه واطيعون",
  },
  {
    "surah_number": 71,
    "verse_number": 4,
    "content":
        "يغفر لكم من ذنوبكم ويؤخركم الى اجل مسمى ان اجل الله اذا جاء لا يؤخر لو كنتم تعلمون",
  },
  {
    "surah_number": 71,
    "verse_number": 5,
    "content": "قال رب اني دعوت قومي ليلا ونهارا",
  },
  {
    "surah_number": 71,
    "verse_number": 6,
    "content": "فلم يزدهم دعاءي الا فرارا",
  },
  {
    "surah_number": 71,
    "verse_number": 7,
    "content":
        "واني كلما دعوتهم لتغفر لهم جعلوا اصبعهم في ءاذانهم واستغشوا ثيابهم واصروا واستكبروا استكبارا",
  },
  {"surah_number": 71, "verse_number": 8, "content": "ثم اني دعوتهم جهارا"},
  {
    "surah_number": 71,
    "verse_number": 9,
    "content": "ثم اني اعلنت لهم واسررت لهم اسرارا",
  },
  {
    "surah_number": 71,
    "verse_number": 10,
    "content": "فقلت استغفروا ربكم انه كان غفارا",
  },
  {
    "surah_number": 71,
    "verse_number": 11,
    "content": "يرسل السماء عليكم مدرارا",
  },
  {
    "surah_number": 71,
    "verse_number": 12,
    "content": "ويمددكم بامول وبنين ويجعل لكم جنـت ويجعل لكم انهرا",
  },
  {
    "surah_number": 71,
    "verse_number": 13,
    "content": "ما لكم لا ترجون لله وقارا",
  },
  {"surah_number": 71, "verse_number": 14, "content": "وقد خلقكم اطوارا"},
  {
    "surah_number": 71,
    "verse_number": 15,
    "content": "الم تروا كيف خلق الله سبع سموت طباقا",
  },
  {
    "surah_number": 71,
    "verse_number": 16,
    "content": "وجعل القمر فيهن نورا وجعل الشمس سراجا",
  },
  {
    "surah_number": 71,
    "verse_number": 17,
    "content": "والله انبتكم من الارض نباتا",
  },
  {
    "surah_number": 71,
    "verse_number": 18,
    "content": "ثم يعيدكم فيها ويخرجكم اخراجا",
  },
  {
    "surah_number": 71,
    "verse_number": 19,
    "content": "والله جعل لكم الارض بساطا",
  },
  {
    "surah_number": 71,
    "verse_number": 20,
    "content": "لتسلكوا منها سبلا فجاجا",
  },
  {
    "surah_number": 71,
    "verse_number": 21,
    "content": "قال نوح رب انهم عصوني واتبعوا من لم يزده ماله وولده الا خسارا",
  },
  {"surah_number": 71, "verse_number": 22, "content": "ومكروا مكرا كبارا"},
  {
    "surah_number": 71,
    "verse_number": 23,
    "content":
        "وقالوا لا تذرن ءالهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا",
  },
  {
    "surah_number": 71,
    "verse_number": 24,
    "content": "وقد اضلوا كثيرا ولا تزد الظـلمين الا ضللا",
  },
  {
    "surah_number": 71,
    "verse_number": 25,
    "content":
        "مما خطيـتهم اغرقوا فادخلوا نارا فلم يجدوا لهم من دون الله انصارا",
  },
  {
    "surah_number": 71,
    "verse_number": 26,
    "content": "وقال نوح رب لا تذر على الارض من الكفرين ديارا",
  },
  {
    "surah_number": 71,
    "verse_number": 27,
    "content": "انك ان تذرهم يضلوا عبادك ولا يلدوا الا فاجرا كفارا",
  },
  {
    "surah_number": 71,
    "verse_number": 28,
    "content":
        "رب اغفر لي ولولدي ولمن دخل بيتي مؤمنا وللمؤمنين والمؤمنت ولا تزد الظـلمين الا تبارا",
  },
  {
    "surah_number": 72,
    "verse_number": 1,
    "content": "قل اوحي الي انه استمع نفر من الجن فقالوا انا سمعنا قرءانا عجبا",
  },
  {
    "surah_number": 72,
    "verse_number": 2,
    "content": "يهدي الى الرشد فـامنا به ولن نشرك بربنا احدا",
  },
  {
    "surah_number": 72,
    "verse_number": 3,
    "content": "وانه تعلى جد ربنا ما اتخذ صحبة ولا ولدا",
  },
  {
    "surah_number": 72,
    "verse_number": 4,
    "content": "وانه كان يقول سفيهنا على الله شططا",
  },
  {
    "surah_number": 72,
    "verse_number": 5,
    "content": "وانا ظننا ان لن تقول الانس والجن على الله كذبا",
  },
  {
    "surah_number": 72,
    "verse_number": 6,
    "content": "وانه كان رجال من الانس يعوذون برجال من الجن فزادوهم رهقا",
  },
  {
    "surah_number": 72,
    "verse_number": 7,
    "content": "وانهم ظنوا كما ظننتم ان لن يبعث الله احدا",
  },
  {
    "surah_number": 72,
    "verse_number": 8,
    "content": "وانا لمسنا السماء فوجدنها ملئت حرسا شديدا وشهبا",
  },
  {
    "surah_number": 72,
    "verse_number": 9,
    "content": "وانا كنا نقعد منها مقعد للسمع فمن يستمع الان يجد له شهابا رصدا",
  },
  {
    "surah_number": 72,
    "verse_number": 10,
    "content": "وانا لا ندري اشر اريد بمن في الارض ام اراد بهم ربهم رشدا",
  },
  {
    "surah_number": 72,
    "verse_number": 11,
    "content": "وانا منا الصـلحون ومنا دون ذلك كنا طرائق قددا",
  },
  {
    "surah_number": 72,
    "verse_number": 12,
    "content": "وانا ظننا ان لن نعجز الله في الارض ولن نعجزه هربا",
  },
  {
    "surah_number": 72,
    "verse_number": 13,
    "content":
        "وانا لما سمعنا الهدى ءامنا به فمن يؤمن بربه فلا يخاف بخسا ولا رهقا",
  },
  {
    "surah_number": 72,
    "verse_number": 14,
    "content": "وانا منا المسلمون ومنا القسطون فمن اسلم فاولـئك تحروا رشدا",
  },
  {
    "surah_number": 72,
    "verse_number": 15,
    "content": "واما القسطون فكانوا لجهنم حطبا",
  },
  {
    "surah_number": 72,
    "verse_number": 16,
    "content": "والو استقموا على الطريقة لاسقينهم ماء غدقا",
  },
  {
    "surah_number": 72,
    "verse_number": 17,
    "content": "لنفتنهم فيه ومن يعرض عن ذكر ربه يسلكه عذابا صعدا",
  },
  {
    "surah_number": 72,
    "verse_number": 18,
    "content": "وان المسجد لله فلا تدعوا مع الله احدا",
  },
  {
    "surah_number": 72,
    "verse_number": 19,
    "content": "وانه لما قام عبد الله يدعوه كادوا يكونون عليه لبدا",
  },
  {
    "surah_number": 72,
    "verse_number": 20,
    "content": "قل انما ادعوا ربي ولا اشرك به احدا",
  },
  {
    "surah_number": 72,
    "verse_number": 21,
    "content": "قل اني لا املك لكم ضرا ولا رشدا",
  },
  {
    "surah_number": 72,
    "verse_number": 22,
    "content": "قل اني لن يجيرني من الله احد ولن اجد من دونه ملتحدا",
  },
  {
    "surah_number": 72,
    "verse_number": 23,
    "content":
        "الا بلغا من الله ورسلته ومن يعص الله ورسوله فان له نار جهنم خلدين فيها ابدا",
  },
  {
    "surah_number": 72,
    "verse_number": 24,
    "content": "حتى اذا راوا ما يوعدون فسيعلمون من اضعف ناصرا واقل عددا",
  },
  {
    "surah_number": 72,
    "verse_number": 25,
    "content": "قل ان ادري اقريب ما توعدون ام يجعل له ربي امدا",
  },
  {
    "surah_number": 72,
    "verse_number": 26,
    "content": "علم الغيب فلا يظهر على غيبه احدا",
  },
  {
    "surah_number": 72,
    "verse_number": 27,
    "content": "الا من ارتضى من رسول فانه يسلك من بين يديه ومن خلفه رصدا",
  },
  {
    "surah_number": 72,
    "verse_number": 28,
    "content": "ليعلم ان قد ابلغوا رسلت ربهم واحاط بما لديهم واحصى كل شيء عددا",
  },
  {"surah_number": 73, "verse_number": 1, "content": "يـايها المزمل"},
  {"surah_number": 73, "verse_number": 2, "content": "قم اليل الا قليلا"},
  {"surah_number": 73, "verse_number": 3, "content": "نصفه او انقص منه قليلا"},
  {
    "surah_number": 73,
    "verse_number": 4,
    "content": "او زد عليه ورتل القرءان ترتيلا",
  },
  {
    "surah_number": 73,
    "verse_number": 5,
    "content": "انا سنلقي عليك قولا ثقيلا",
  },
  {
    "surah_number": 73,
    "verse_number": 6,
    "content": "ان ناشئة اليل هي اشد وطـا واقوم قيلا",
  },
  {
    "surah_number": 73,
    "verse_number": 7,
    "content": "ان لك في النهار سبحا طويلا",
  },
  {
    "surah_number": 73,
    "verse_number": 8,
    "content": "واذكر اسم ربك وتبتل اليه تبتيلا",
  },
  {
    "surah_number": 73,
    "verse_number": 9,
    "content": "رب المشرق والمغرب لا اله الا هو فاتخذه وكيلا",
  },
  {
    "surah_number": 73,
    "verse_number": 10,
    "content": "واصبر على ما يقولون واهجرهم هجرا جميلا",
  },
  {
    "surah_number": 73,
    "verse_number": 11,
    "content": "وذرني والمكذبين اولي النعمة ومهلهم قليلا",
  },
  {"surah_number": 73, "verse_number": 12, "content": "ان لدينا انكالا وجحيما"},
  {
    "surah_number": 73,
    "verse_number": 13,
    "content": "وطعاما ذا غصة وعذابا اليما",
  },
  {
    "surah_number": 73,
    "verse_number": 14,
    "content": "يوم ترجف الارض والجبال وكانت الجبال كثيبا مهيلا",
  },
  {
    "surah_number": 73,
    "verse_number": 15,
    "content": "انا ارسلنا اليكم رسولا شهدا عليكم كما ارسلنا الى فرعون رسولا",
  },
  {
    "surah_number": 73,
    "verse_number": 16,
    "content": "فعصى فرعون الرسول فاخذنه اخذا وبيلا",
  },
  {
    "surah_number": 73,
    "verse_number": 17,
    "content": "فكيف تتقون ان كفرتم يوما يجعل الولدن شيبا",
  },
  {
    "surah_number": 73,
    "verse_number": 18,
    "content": "السماء منفطر به كان وعده مفعولا",
  },
  {
    "surah_number": 73,
    "verse_number": 19,
    "content": "ان هذه تذكرة فمن شاء اتخذ الى ربه سبيلا",
  },
  {
    "surah_number": 73,
    "verse_number": 20,
    "content":
        "ان ربك يعلم انك تقوم ادنى من ثلثي اليل ونصفه وثلثه وطائفة من الذين معك والله يقدر اليل والنهار علم ان لن تحصوه فتاب عليكم فاقرءوا ما تيسر من القرءان علم ان سيكون منكم مرضى وءاخرون يضربون في الارض يبتغون من فضل الله وءاخرون يقتلون في سبيل الله فاقرءوا ما تيسر منه واقيموا الصلاة وءاتوا الزكوة واقرضوا الله قرضا حسنا وما تقدموا لانفسكم من خير تجدوه عند الله هو خيرا واعظم اجرا واستغفروا الله ان الله غفور رحيم",
  },
  {"surah_number": 74, "verse_number": 1, "content": "يـايها المدثر"},
  {"surah_number": 74, "verse_number": 2, "content": "قم فانذر"},
  {"surah_number": 74, "verse_number": 3, "content": "وربك فكبر"},
  {"surah_number": 74, "verse_number": 4, "content": "وثيابك فطهر"},
  {"surah_number": 74, "verse_number": 5, "content": "والرجز فاهجر"},
  {"surah_number": 74, "verse_number": 6, "content": "ولا تمنن تستكثر"},
  {"surah_number": 74, "verse_number": 7, "content": "ولربك فاصبر"},
  {"surah_number": 74, "verse_number": 8, "content": "فاذا نقر في الناقور"},
  {"surah_number": 74, "verse_number": 9, "content": "فذلك يومئذ يوم عسير"},
  {"surah_number": 74, "verse_number": 10, "content": "على الكفرين غير يسير"},
  {"surah_number": 74, "verse_number": 11, "content": "ذرني ومن خلقت وحيدا"},
  {"surah_number": 74, "verse_number": 12, "content": "وجعلت له مالا ممدودا"},
  {"surah_number": 74, "verse_number": 13, "content": "وبنين شهودا"},
  {"surah_number": 74, "verse_number": 14, "content": "ومهدت له تمهيدا"},
  {"surah_number": 74, "verse_number": 15, "content": "ثم يطمع ان ازيد"},
  {
    "surah_number": 74,
    "verse_number": 16,
    "content": "كلا انه كان لايتنا عنيدا",
  },
  {"surah_number": 74, "verse_number": 17, "content": "سارهقه صعودا"},
  {"surah_number": 74, "verse_number": 18, "content": "انه فكر وقدر"},
  {"surah_number": 74, "verse_number": 19, "content": "فقتل كيف قدر"},
  {"surah_number": 74, "verse_number": 20, "content": "ثم قتل كيف قدر"},
  {"surah_number": 74, "verse_number": 21, "content": "ثم نظر"},
  {"surah_number": 74, "verse_number": 22, "content": "ثم عبس وبسر"},
  {"surah_number": 74, "verse_number": 23, "content": "ثم ادبر واستكبر"},
  {
    "surah_number": 74,
    "verse_number": 24,
    "content": "فقال ان هذا الا سحر يؤثر",
  },
  {"surah_number": 74, "verse_number": 25, "content": "ان هذا الا قول البشر"},
  {"surah_number": 74, "verse_number": 26, "content": "ساصليه سقر"},
  {"surah_number": 74, "verse_number": 27, "content": "وما ادرىك ما سقر"},
  {"surah_number": 74, "verse_number": 28, "content": "لا تبقي ولا تذر"},
  {"surah_number": 74, "verse_number": 29, "content": "لواحة للبشر"},
  {"surah_number": 74, "verse_number": 30, "content": "عليها تسعة عشر"},
  {
    "surah_number": 74,
    "verse_number": 31,
    "content":
        "وما جعلنا اصحب النار الا ملـئكة وما جعلنا عدتهم الا فتنة للذين كفروا ليستيقن الذين اوتوا الكتب ويزداد الذين ءامنوا ايمنا ولا يرتاب الذين اوتوا الكتب والمؤمنون وليقول الذين في قلوبهم مرض والكفرون ماذا اراد الله بهذا مثلا كذلك يضل الله من يشاء ويهدي من يشاء وما يعلم جنود ربك الا هو وما هي الا ذكرى للبشر",
  },
  {"surah_number": 74, "verse_number": 32, "content": "كلا والقمر"},
  {"surah_number": 74, "verse_number": 33, "content": "واليل اذ ادبر"},
  {"surah_number": 74, "verse_number": 34, "content": "والصبح اذا اسفر"},
  {"surah_number": 74, "verse_number": 35, "content": "انها لاحدى الكبر"},
  {"surah_number": 74, "verse_number": 36, "content": "نذيرا للبشر"},
  {
    "surah_number": 74,
    "verse_number": 37,
    "content": "لمن شاء منكم ان يتقدم او يتاخر",
  },
  {"surah_number": 74, "verse_number": 38, "content": "كل نفس بما كسبت رهينة"},
  {"surah_number": 74, "verse_number": 39, "content": "الا اصحب اليمين"},
  {"surah_number": 74, "verse_number": 40, "content": "في جنـت يتساءلون"},
  {"surah_number": 74, "verse_number": 41, "content": "عن المجرمين"},
  {"surah_number": 74, "verse_number": 42, "content": "ما سلككم في سقر"},
  {"surah_number": 74, "verse_number": 43, "content": "قالوا لم نك من المصلين"},
  {"surah_number": 74, "verse_number": 44, "content": "ولم نك نطعم المسكين"},
  {"surah_number": 74, "verse_number": 45, "content": "وكنا نخوض مع الخائضين"},
  {"surah_number": 74, "verse_number": 46, "content": "وكنا نكذب بيوم الدين"},
  {"surah_number": 74, "verse_number": 47, "content": "حتى اتىنا اليقين"},
  {
    "surah_number": 74,
    "verse_number": 48,
    "content": "فما تنفعهم شفعة الشـفعين",
  },
  {
    "surah_number": 74,
    "verse_number": 49,
    "content": "فما لهم عن التذكرة معرضين",
  },
  {"surah_number": 74, "verse_number": 50, "content": "كانهم حمر مستنفرة"},
  {"surah_number": 74, "verse_number": 51, "content": "فرت من قسورة"},
  {
    "surah_number": 74,
    "verse_number": 52,
    "content": "بل يريد كل امري منهم ان يؤتى صحفا منشرة",
  },
  {
    "surah_number": 74,
    "verse_number": 53,
    "content": "كلا بل لا يخافون الاخرة",
  },
  {"surah_number": 74, "verse_number": 54, "content": "كلا انه تذكرة"},
  {"surah_number": 74, "verse_number": 55, "content": "فمن شاء ذكره"},
  {
    "surah_number": 74,
    "verse_number": 56,
    "content": "وما يذكرون الا ان يشاء الله هو اهل التقوى واهل المغفرة",
  },
  {"surah_number": 75, "verse_number": 1, "content": "لا اقسم بيوم القيمة"},
  {"surah_number": 75, "verse_number": 2, "content": "ولا اقسم بالنفس اللوامة"},
  {
    "surah_number": 75,
    "verse_number": 3,
    "content": "ايحسب الانسن الن نجمع عظامه",
  },
  {
    "surah_number": 75,
    "verse_number": 4,
    "content": "بلى قدرين على ان نسوي بنانه",
  },
  {
    "surah_number": 75,
    "verse_number": 5,
    "content": "بل يريد الانسن ليفجر امامه",
  },
  {"surah_number": 75, "verse_number": 6, "content": "يسـل ايان يوم القيمة"},
  {"surah_number": 75, "verse_number": 7, "content": "فاذا برق البصر"},
  {"surah_number": 75, "verse_number": 8, "content": "وخسف القمر"},
  {"surah_number": 75, "verse_number": 9, "content": "وجمع الشمس والقمر"},
  {
    "surah_number": 75,
    "verse_number": 10,
    "content": "يقول الانسن يومئذ اين المفر",
  },
  {"surah_number": 75, "verse_number": 11, "content": "كلا لا وزر"},
  {"surah_number": 75, "verse_number": 12, "content": "الى ربك يومئذ المستقر"},
  {
    "surah_number": 75,
    "verse_number": 13,
    "content": "ينبؤا الانسن يومئذ بما قدم واخر",
  },
  {
    "surah_number": 75,
    "verse_number": 14,
    "content": "بل الانسن على نفسه بصيرة",
  },
  {"surah_number": 75, "verse_number": 15, "content": "ولو القى معاذيره"},
  {
    "surah_number": 75,
    "verse_number": 16,
    "content": "لا تحرك به لسانك لتعجل به",
  },
  {"surah_number": 75, "verse_number": 17, "content": "ان علينا جمعه وقرءانه"},
  {
    "surah_number": 75,
    "verse_number": 18,
    "content": "فاذا قرانه فاتبع قرءانه",
  },
  {"surah_number": 75, "verse_number": 19, "content": "ثم ان علينا بيانه"},
  {"surah_number": 75, "verse_number": 20, "content": "كلا بل تحبون العاجلة"},
  {"surah_number": 75, "verse_number": 21, "content": "وتذرون الاخرة"},
  {"surah_number": 75, "verse_number": 22, "content": "وجوه يومئذ ناضرة"},
  {"surah_number": 75, "verse_number": 23, "content": "الى ربها ناظرة"},
  {"surah_number": 75, "verse_number": 24, "content": "ووجوه يومئذ باسرة"},
  {"surah_number": 75, "verse_number": 25, "content": "تظن ان يفعل بها فاقرة"},
  {"surah_number": 75, "verse_number": 26, "content": "كلا اذا بلغت التراقي"},
  {"surah_number": 75, "verse_number": 27, "content": "وقيل من راق"},
  {"surah_number": 75, "verse_number": 28, "content": "وظن انه الفراق"},
  {"surah_number": 75, "verse_number": 29, "content": "والتفت الساق بالساق"},
  {"surah_number": 75, "verse_number": 30, "content": "الى ربك يومئذ المساق"},
  {"surah_number": 75, "verse_number": 31, "content": "فلا صدق ولا صلى"},
  {"surah_number": 75, "verse_number": 32, "content": "ولكن كذب وتولى"},
  {"surah_number": 75, "verse_number": 33, "content": "ثم ذهب الى اهله يتمطى"},
  {"surah_number": 75, "verse_number": 34, "content": "اولى لك فاولى"},
  {"surah_number": 75, "verse_number": 35, "content": "ثم اولى لك فاولى"},
  {
    "surah_number": 75,
    "verse_number": 36,
    "content": "ايحسب الانسن ان يترك سدى",
  },
  {
    "surah_number": 75,
    "verse_number": 37,
    "content": "الم يك نطفة من مني يمنى",
  },
  {"surah_number": 75, "verse_number": 38, "content": "ثم كان علقة فخلق فسوى"},
  {
    "surah_number": 75,
    "verse_number": 39,
    "content": "فجعل منه الزوجين الذكر والانثى",
  },
  {
    "surah_number": 75,
    "verse_number": 40,
    "content": "اليس ذلك بقدر على ان يحـي الموتى",
  },
  {
    "surah_number": 76,
    "verse_number": 1,
    "content": "هل اتى على الانسن حين من الدهر لم يكن شيـا مذكورا",
  },
  {
    "surah_number": 76,
    "verse_number": 2,
    "content": "انا خلقنا الانسن من نطفة امشاج نبتليه فجعلنه سميعا بصيرا",
  },
  {
    "surah_number": 76,
    "verse_number": 3,
    "content": "انا هدينه السبيل اما شاكرا واما كفورا",
  },
  {
    "surah_number": 76,
    "verse_number": 4,
    "content": "انا اعتدنا للكفرين سلسلا واغللا وسعيرا",
  },
  {
    "surah_number": 76,
    "verse_number": 5,
    "content": "ان الابرار يشربون من كاس كان مزاجها كافورا",
  },
  {
    "surah_number": 76,
    "verse_number": 6,
    "content": "عينا يشرب بها عباد الله يفجرونها تفجيرا",
  },
  {
    "surah_number": 76,
    "verse_number": 7,
    "content": "يوفون بالنذر ويخافون يوما كان شره مستطيرا",
  },
  {
    "surah_number": 76,
    "verse_number": 8,
    "content": "ويطعمون الطعام على حبه مسكينا ويتيما واسيرا",
  },
  {
    "surah_number": 76,
    "verse_number": 9,
    "content": "انما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكورا",
  },
  {
    "surah_number": 76,
    "verse_number": 10,
    "content": "انا نخاف من ربنا يوما عبوسا قمطريرا",
  },
  {
    "surah_number": 76,
    "verse_number": 11,
    "content": "فوقىهم الله شر ذلك اليوم ولقىهم نضرة وسرورا",
  },
  {
    "surah_number": 76,
    "verse_number": 12,
    "content": "وجزىهم بما صبروا جنة وحريرا",
  },
  {
    "surah_number": 76,
    "verse_number": 13,
    "content": "متكـين فيها على الارائك لا يرون فيها شمسا ولا زمهريرا",
  },
  {
    "surah_number": 76,
    "verse_number": 14,
    "content": "ودانية عليهم ظللها وذللت قطوفها تذليلا",
  },
  {
    "surah_number": 76,
    "verse_number": 15,
    "content": "ويطاف عليهم بـانية من فضة واكواب كانت قواريرا",
  },
  {
    "surah_number": 76,
    "verse_number": 16,
    "content": "قواريرا من فضة قدروها تقديرا",
  },
  {
    "surah_number": 76,
    "verse_number": 17,
    "content": "ويسقون فيها كاسا كان مزاجها زنجبيلا",
  },
  {"surah_number": 76, "verse_number": 18, "content": "عينا فيها تسمى سلسبيلا"},
  {
    "surah_number": 76,
    "verse_number": 19,
    "content": "ويطوف عليهم ولدن مخلدون اذا رايتهم حسبتهم لؤلؤا منثورا",
  },
  {
    "surah_number": 76,
    "verse_number": 20,
    "content": "واذا رايت ثم رايت نعيما وملكا كبيرا",
  },
  {
    "surah_number": 76,
    "verse_number": 21,
    "content":
        "عليهم ثياب سندس خضر واستبرق وحلوا اساور من فضة وسقىهم ربهم شرابا طهورا",
  },
  {
    "surah_number": 76,
    "verse_number": 22,
    "content": "ان هذا كان لكم جزاء وكان سعيكم مشكورا",
  },
  {
    "surah_number": 76,
    "verse_number": 23,
    "content": "انا نحن نزلنا عليك القرءان تنزيلا",
  },
  {
    "surah_number": 76,
    "verse_number": 24,
    "content": "فاصبر لحكم ربك ولا تطع منهم ءاثما او كفورا",
  },
  {
    "surah_number": 76,
    "verse_number": 25,
    "content": "واذكر اسم ربك بكرة واصيلا",
  },
  {
    "surah_number": 76,
    "verse_number": 26,
    "content": "ومن اليل فاسجد له وسبحه ليلا طويلا",
  },
  {
    "surah_number": 76,
    "verse_number": 27,
    "content": "ان هـؤلاء يحبون العاجلة ويذرون وراءهم يوما ثقيلا",
  },
  {
    "surah_number": 76,
    "verse_number": 28,
    "content": "نحن خلقنهم وشددنا اسرهم واذا شئنا بدلنا امثلهم تبديلا",
  },
  {
    "surah_number": 76,
    "verse_number": 29,
    "content": "ان هذه تذكرة فمن شاء اتخذ الى ربه سبيلا",
  },
  {
    "surah_number": 76,
    "verse_number": 30,
    "content": "وما تشاءون الا ان يشاء الله ان الله كان عليما حكيما",
  },
  {
    "surah_number": 76,
    "verse_number": 31,
    "content": "يدخل من يشاء في رحمته والظـلمين اعد لهم عذابا اليما",
  },
  {"surah_number": 77, "verse_number": 1, "content": "والمرسلت عرفا"},
  {"surah_number": 77, "verse_number": 2, "content": "فالعصفت عصفا"},
  {"surah_number": 77, "verse_number": 3, "content": "والنـشرت نشرا"},
  {"surah_number": 77, "verse_number": 4, "content": "فالفرقت فرقا"},
  {"surah_number": 77, "verse_number": 5, "content": "فالملقيت ذكرا"},
  {"surah_number": 77, "verse_number": 6, "content": "عذرا او نذرا"},
  {"surah_number": 77, "verse_number": 7, "content": "انما توعدون لوقع"},
  {"surah_number": 77, "verse_number": 8, "content": "فاذا النجوم طمست"},
  {"surah_number": 77, "verse_number": 9, "content": "واذا السماء فرجت"},
  {"surah_number": 77, "verse_number": 10, "content": "واذا الجبال نسفت"},
  {"surah_number": 77, "verse_number": 11, "content": "واذا الرسل اقتت"},
  {"surah_number": 77, "verse_number": 12, "content": "لاي يوم اجلت"},
  {"surah_number": 77, "verse_number": 13, "content": "ليوم الفصل"},
  {"surah_number": 77, "verse_number": 14, "content": "وما ادرىك ما يوم الفصل"},
  {"surah_number": 77, "verse_number": 15, "content": "ويل يومئذ للمكذبين"},
  {"surah_number": 77, "verse_number": 16, "content": "الم نهلك الاولين"},
  {"surah_number": 77, "verse_number": 17, "content": "ثم نتبعهم الاخرين"},
  {"surah_number": 77, "verse_number": 18, "content": "كذلك نفعل بالمجرمين"},
  {"surah_number": 77, "verse_number": 19, "content": "ويل يومئذ للمكذبين"},
  {"surah_number": 77, "verse_number": 20, "content": "الم نخلقكم من ماء مهين"},
  {"surah_number": 77, "verse_number": 21, "content": "فجعلنه في قرار مكين"},
  {"surah_number": 77, "verse_number": 22, "content": "الى قدر معلوم"},
  {"surah_number": 77, "verse_number": 23, "content": "فقدرنا فنعم القدرون"},
  {"surah_number": 77, "verse_number": 24, "content": "ويل يومئذ للمكذبين"},
  {"surah_number": 77, "verse_number": 25, "content": "الم نجعل الارض كفاتا"},
  {"surah_number": 77, "verse_number": 26, "content": "احياء واموتا"},
  {
    "surah_number": 77,
    "verse_number": 27,
    "content": "وجعلنا فيها روسي شمخت واسقينكم ماء فراتا",
  },
  {"surah_number": 77, "verse_number": 28, "content": "ويل يومئذ للمكذبين"},
  {
    "surah_number": 77,
    "verse_number": 29,
    "content": "انطلقوا الى ما كنتم به تكذبون",
  },
  {
    "surah_number": 77,
    "verse_number": 30,
    "content": "انطلقوا الى ظل ذي ثلث شعب",
  },
  {
    "surah_number": 77,
    "verse_number": 31,
    "content": "لا ظليل ولا يغني من اللهب",
  },
  {"surah_number": 77, "verse_number": 32, "content": "انها ترمي بشرر كالقصر"},
  {"surah_number": 77, "verse_number": 33, "content": "كانه جملت صفر"},
  {"surah_number": 77, "verse_number": 34, "content": "ويل يومئذ للمكذبين"},
  {"surah_number": 77, "verse_number": 35, "content": "هذا يوم لا ينطقون"},
  {"surah_number": 77, "verse_number": 36, "content": "ولا يؤذن لهم فيعتذرون"},
  {"surah_number": 77, "verse_number": 37, "content": "ويل يومئذ للمكذبين"},
  {
    "surah_number": 77,
    "verse_number": 38,
    "content": "هذا يوم الفصل جمعنكم والاولين",
  },
  {"surah_number": 77, "verse_number": 39, "content": "فان كان لكم كيد فكيدون"},
  {"surah_number": 77, "verse_number": 40, "content": "ويل يومئذ للمكذبين"},
  {
    "surah_number": 77,
    "verse_number": 41,
    "content": "ان المتقين في ظلل وعيون",
  },
  {"surah_number": 77, "verse_number": 42, "content": "وفوكه مما يشتهون"},
  {
    "surah_number": 77,
    "verse_number": 43,
    "content": "كلوا واشربوا هنيـا بما كنتم تعملون",
  },
  {"surah_number": 77, "verse_number": 44, "content": "انا كذلك نجزي المحسنين"},
  {"surah_number": 77, "verse_number": 45, "content": "ويل يومئذ للمكذبين"},
  {
    "surah_number": 77,
    "verse_number": 46,
    "content": "كلوا وتمتعوا قليلا انكم مجرمون",
  },
  {"surah_number": 77, "verse_number": 47, "content": "ويل يومئذ للمكذبين"},
  {
    "surah_number": 77,
    "verse_number": 48,
    "content": "واذا قيل لهم اركعوا لا يركعون",
  },
  {"surah_number": 77, "verse_number": 49, "content": "ويل يومئذ للمكذبين"},
  {"surah_number": 77, "verse_number": 50, "content": "فباي حديث بعده يؤمنون"},
  {"surah_number": 78, "verse_number": 1, "content": "عم يتساءلو"},
  {"surah_number": 78, "verse_number": 2, "content": "عن النبا العظيم"},
  {"surah_number": 78, "verse_number": 3, "content": "الذي هم فيه مختلفون"},
  {"surah_number": 78, "verse_number": 4, "content": "كلا سيعلمون"},
  {"surah_number": 78, "verse_number": 5, "content": "ثم كلا سيعلمون"},
  {"surah_number": 78, "verse_number": 6, "content": "الم نجعل الارض مهدا"},
  {"surah_number": 78, "verse_number": 7, "content": "والجبال اوتادا"},
  {"surah_number": 78, "verse_number": 8, "content": "وخلقنكم ازوجا"},
  {"surah_number": 78, "verse_number": 9, "content": "وجعلنا نومكم سباتا"},
  {"surah_number": 78, "verse_number": 10, "content": "وجعلنا اليل لباسا"},
  {"surah_number": 78, "verse_number": 11, "content": "وجعلنا النهار معاشا"},
  {
    "surah_number": 78,
    "verse_number": 12,
    "content": "وبنينا فوقكم سبعا شدادا",
  },
  {"surah_number": 78, "verse_number": 13, "content": "وجعلنا سراجا وهاجا"},
  {
    "surah_number": 78,
    "verse_number": 14,
    "content": "وانزلنا من المعصرت ماء ثجاجا",
  },
  {"surah_number": 78, "verse_number": 15, "content": "لنخرج به حبا ونباتا"},
  {"surah_number": 78, "verse_number": 16, "content": "وجنـت الفافا"},
  {"surah_number": 78, "verse_number": 17, "content": "ان يوم الفصل كان ميقتا"},
  {
    "surah_number": 78,
    "verse_number": 18,
    "content": "يوم ينفخ في الصور فتاتون افواجا",
  },
  {
    "surah_number": 78,
    "verse_number": 19,
    "content": "وفتحت السماء فكانت ابوبا",
  },
  {
    "surah_number": 78,
    "verse_number": 20,
    "content": "وسيرت الجبال فكانت سرابا",
  },
  {"surah_number": 78, "verse_number": 21, "content": "ان جهنم كانت مرصادا"},
  {"surah_number": 78, "verse_number": 22, "content": "للطـغين مـابا"},
  {"surah_number": 78, "verse_number": 23, "content": "لـبثين فيها احقابا"},
  {
    "surah_number": 78,
    "verse_number": 24,
    "content": "لا يذوقون فيها بردا ولا شرابا",
  },
  {"surah_number": 78, "verse_number": 25, "content": "الا حميما وغساقا"},
  {"surah_number": 78, "verse_number": 26, "content": "جزاء وفاقا"},
  {
    "surah_number": 78,
    "verse_number": 27,
    "content": "انهم كانوا لا يرجون حسابا",
  },
  {"surah_number": 78, "verse_number": 28, "content": "وكذبوا بـايتنا كذابا"},
  {"surah_number": 78, "verse_number": 29, "content": "وكل شيء احصينه كتبا"},
  {
    "surah_number": 78,
    "verse_number": 30,
    "content": "فذوقوا فلن نزيدكم الا عذابا",
  },
  {"surah_number": 78, "verse_number": 31, "content": "ان للمتقين مفازا"},
  {"surah_number": 78, "verse_number": 32, "content": "حدائق واعنبا"},
  {"surah_number": 78, "verse_number": 33, "content": "وكواعب اترابا"},
  {"surah_number": 78, "verse_number": 34, "content": "وكاسا دهاقا"},
  {
    "surah_number": 78,
    "verse_number": 35,
    "content": "لا يسمعون فيها لغوا ولا كذـبا",
  },
  {"surah_number": 78, "verse_number": 36, "content": "جزاء من ربك عطاء حسابا"},
  {
    "surah_number": 78,
    "verse_number": 37,
    "content": "رب السموت والارض وما بينهما الرحمن لا يملكون منه خطابا",
  },
  {
    "surah_number": 78,
    "verse_number": 38,
    "content":
        "يوم يقوم الروح والملـئكة صفا لا يتكلمون الا من اذن له الرحمن وقال صوابا",
  },
  {
    "surah_number": 78,
    "verse_number": 39,
    "content": "ذلك اليوم الحق فمن شاء اتخذ الى ربه مـابا",
  },
  {
    "surah_number": 78,
    "verse_number": 40,
    "content":
        "انا انذرنكم عذابا قريبا يوم ينظر المرء ما قدمت يداه ويقول الكافر يليتني كنت تربا",
  },
  {"surah_number": 79, "verse_number": 1, "content": "والنـزعت غرقا"},
  {"surah_number": 79, "verse_number": 2, "content": "والنـشطت نشطا"},
  {"surah_number": 79, "verse_number": 3, "content": "والسـبحت سبحا"},
  {"surah_number": 79, "verse_number": 4, "content": "فالسـبقت سبقا"},
  {"surah_number": 79, "verse_number": 5, "content": "فالمدبرت امرا"},
  {"surah_number": 79, "verse_number": 6, "content": "يوم ترجف الراجفة"},
  {"surah_number": 79, "verse_number": 7, "content": "تتبعها الرادفة"},
  {"surah_number": 79, "verse_number": 8, "content": "قلوب يومئذ واجفة"},
  {"surah_number": 79, "verse_number": 9, "content": "ابصرها خشعة"},
  {
    "surah_number": 79,
    "verse_number": 10,
    "content": "يقولون اءنا لمردودون في الحافرة",
  },
  {"surah_number": 79, "verse_number": 11, "content": "اءذا كنا عظما نخرة"},
  {
    "surah_number": 79,
    "verse_number": 12,
    "content": "قالوا تلك اذا كرة خاسرة",
  },
  {"surah_number": 79, "verse_number": 13, "content": "فانما هي زجرة وحدة"},
  {"surah_number": 79, "verse_number": 14, "content": "فاذا هم بالساهرة"},
  {"surah_number": 79, "verse_number": 15, "content": "هل اتىك حديث موسى"},
  {
    "surah_number": 79,
    "verse_number": 16,
    "content": "اذ نادىه ربه بالواد المقدس طوى",
  },
  {"surah_number": 79, "verse_number": 17, "content": "اذهب الى فرعون انه طغى"},
  {"surah_number": 79, "verse_number": 18, "content": "فقل هل لك الى ان تزكى"},
  {"surah_number": 79, "verse_number": 19, "content": "واهديك الى ربك فتخشى"},
  {"surah_number": 79, "verse_number": 20, "content": "فارىه الاية الكبرى"},
  {"surah_number": 79, "verse_number": 21, "content": "فكذب وعصى"},
  {"surah_number": 79, "verse_number": 22, "content": "ثم ادبر يسعى"},
  {"surah_number": 79, "verse_number": 23, "content": "فحشر فنادى"},
  {"surah_number": 79, "verse_number": 24, "content": "فقال انا ربكم الاعلى"},
  {
    "surah_number": 79,
    "verse_number": 25,
    "content": "فاخذه الله نكال الاخرة والاولى",
  },
  {
    "surah_number": 79,
    "verse_number": 26,
    "content": "ان في ذلك لعبرة لمن يخشى",
  },
  {
    "surah_number": 79,
    "verse_number": 27,
    "content": "ءانتم اشد خلقا ام السماء بنىها",
  },
  {"surah_number": 79, "verse_number": 28, "content": "رفع سمكها فسوىها"},
  {
    "surah_number": 79,
    "verse_number": 29,
    "content": "واغطش ليلها واخرج ضحىها",
  },
  {"surah_number": 79, "verse_number": 30, "content": "والارض بعد ذلك دحىها"},
  {
    "surah_number": 79,
    "verse_number": 31,
    "content": "اخرج منها ماءها ومرعىها",
  },
  {"surah_number": 79, "verse_number": 32, "content": "والجبال ارسىها"},
  {"surah_number": 79, "verse_number": 33, "content": "متعا لكم ولانعمكم"},
  {
    "surah_number": 79,
    "verse_number": 34,
    "content": "فاذا جاءت الطامة الكبرى",
  },
  {
    "surah_number": 79,
    "verse_number": 35,
    "content": "يوم يتذكر الانسن ما سعى",
  },
  {"surah_number": 79, "verse_number": 36, "content": "وبرزت الجحيم لمن يرى"},
  {"surah_number": 79, "verse_number": 37, "content": "فاما من طغى"},
  {"surah_number": 79, "verse_number": 38, "content": "وءاثر الحيوة الدنيا"},
  {"surah_number": 79, "verse_number": 39, "content": "فان الجحيم هي الماوى"},
  {
    "surah_number": 79,
    "verse_number": 40,
    "content": "واما من خاف مقام ربه ونهى النفس عن الهوى",
  },
  {"surah_number": 79, "verse_number": 41, "content": "فان الجنة هي الماوى"},
  {
    "surah_number": 79,
    "verse_number": 42,
    "content": "يسـلونك عن الساعة ايان مرسىها",
  },
  {"surah_number": 79, "verse_number": 43, "content": "فيم انت من ذكرىها"},
  {"surah_number": 79, "verse_number": 44, "content": "الى ربك منتهىها"},
  {
    "surah_number": 79,
    "verse_number": 45,
    "content": "انما انت منذر من يخشىها",
  },
  {
    "surah_number": 79,
    "verse_number": 46,
    "content": "كانهم يوم يرونها لم يلبثوا الا عشية او ضحىها",
  },
  {"surah_number": 80, "verse_number": 1, "content": "عبس وتولى"},
  {"surah_number": 80, "verse_number": 2, "content": "ان جاءه الاعمى"},
  {"surah_number": 80, "verse_number": 3, "content": "وما يدريك لعله يزكى"},
  {"surah_number": 80, "verse_number": 4, "content": "او يذكر فتنفعه الذكرى"},
  {"surah_number": 80, "verse_number": 5, "content": "اما من استغنى"},
  {"surah_number": 80, "verse_number": 6, "content": "فانت له تصدى"},
  {"surah_number": 80, "verse_number": 7, "content": "وما عليك الا يزكى"},
  {"surah_number": 80, "verse_number": 8, "content": "واما من جاءك يسعى"},
  {"surah_number": 80, "verse_number": 9, "content": "وهو يخشى"},
  {"surah_number": 80, "verse_number": 10, "content": "فانت عنه تلهى"},
  {"surah_number": 80, "verse_number": 11, "content": "كلا انها تذكرة"},
  {"surah_number": 80, "verse_number": 12, "content": "فمن شاء ذكره"},
  {"surah_number": 80, "verse_number": 13, "content": "في صحف مكرمة"},
  {"surah_number": 80, "verse_number": 14, "content": "مرفوعة مطهرة"},
  {"surah_number": 80, "verse_number": 15, "content": "بايدي سفرة"},
  {"surah_number": 80, "verse_number": 16, "content": "كرام بررة"},
  {"surah_number": 80, "verse_number": 17, "content": "قتل الانسن ما اكفره"},
  {"surah_number": 80, "verse_number": 18, "content": "من اي شيء خلقه"},
  {"surah_number": 80, "verse_number": 19, "content": "من نطفة خلقه فقدره"},
  {"surah_number": 80, "verse_number": 20, "content": "ثم السبيل يسره"},
  {"surah_number": 80, "verse_number": 21, "content": "ثم اماته فاقبره"},
  {"surah_number": 80, "verse_number": 22, "content": "ثم اذا شاء انشره"},
  {"surah_number": 80, "verse_number": 23, "content": "كلا لما يقض ما امره"},
  {
    "surah_number": 80,
    "verse_number": 24,
    "content": "فلينظر الانسن الى طعامه",
  },
  {"surah_number": 80, "verse_number": 25, "content": "انا صببنا الماء صبا"},
  {"surah_number": 80, "verse_number": 26, "content": "ثم شققنا الارض شقا"},
  {"surah_number": 80, "verse_number": 27, "content": "فانبتنا فيها حبا"},
  {"surah_number": 80, "verse_number": 28, "content": "وعنبا وقضبا"},
  {"surah_number": 80, "verse_number": 29, "content": "وزيتونا ونخلا"},
  {"surah_number": 80, "verse_number": 30, "content": "وحدائق غلبا"},
  {"surah_number": 80, "verse_number": 31, "content": "وفكهة وابا"},
  {"surah_number": 80, "verse_number": 32, "content": "متعا لكم ولانعمكم"},
  {"surah_number": 80, "verse_number": 33, "content": "فاذا جاءت الصاخة"},
  {"surah_number": 80, "verse_number": 34, "content": "يوم يفر المرء من اخيه"},
  {"surah_number": 80, "verse_number": 35, "content": "وامه وابيه"},
  {"surah_number": 80, "verse_number": 36, "content": "وصحبته وبنيه"},
  {
    "surah_number": 80,
    "verse_number": 37,
    "content": "لكل امري منهم يومئذ شان يغنيه",
  },
  {"surah_number": 80, "verse_number": 38, "content": "وجوه يومئذ مسفرة"},
  {"surah_number": 80, "verse_number": 39, "content": "ضاحكة مستبشرة"},
  {"surah_number": 80, "verse_number": 40, "content": "ووجوه يومئذ عليها غبرة"},
  {"surah_number": 80, "verse_number": 41, "content": "ترهقها قترة"},
  {
    "surah_number": 80,
    "verse_number": 42,
    "content": "اولـئك هم الكفرة الفجرة",
  },
  {"surah_number": 81, "verse_number": 1, "content": "اذا الشمس كورت"},
  {"surah_number": 81, "verse_number": 2, "content": "واذا النجوم انكدرت"},
  {"surah_number": 81, "verse_number": 3, "content": "واذا الجبال سيرت"},
  {"surah_number": 81, "verse_number": 4, "content": "واذا العشار عطلت"},
  {"surah_number": 81, "verse_number": 5, "content": "واذا الوحوش حشرت"},
  {"surah_number": 81, "verse_number": 6, "content": "واذا البحار سجرت"},
  {"surah_number": 81, "verse_number": 7, "content": "واذا النفوس زوجت"},
  {"surah_number": 81, "verse_number": 8, "content": "واذا الموءدة سئلت"},
  {"surah_number": 81, "verse_number": 9, "content": "باي ذنب قتلت"},
  {"surah_number": 81, "verse_number": 10, "content": "واذا الصحف نشرت"},
  {"surah_number": 81, "verse_number": 11, "content": "واذا السماء كشطت"},
  {"surah_number": 81, "verse_number": 12, "content": "واذا الجحيم سعرت"},
  {"surah_number": 81, "verse_number": 13, "content": "واذا الجنة ازلفت"},
  {"surah_number": 81, "verse_number": 14, "content": "علمت نفس ما احضرت"},
  {"surah_number": 81, "verse_number": 15, "content": "فلا اقسم بالخنس"},
  {"surah_number": 81, "verse_number": 16, "content": "الجوار الكنس"},
  {"surah_number": 81, "verse_number": 17, "content": "واليل اذا عسعس"},
  {"surah_number": 81, "verse_number": 18, "content": "والصبح اذا تنفس"},
  {"surah_number": 81, "verse_number": 19, "content": "انه لقول رسول كريم"},
  {
    "surah_number": 81,
    "verse_number": 20,
    "content": "ذي قوة عند ذي العرش مكين",
  },
  {"surah_number": 81, "verse_number": 21, "content": "مطاع ثم امين"},
  {"surah_number": 81, "verse_number": 22, "content": "وما صاحبكم بمجنون"},
  {
    "surah_number": 81,
    "verse_number": 23,
    "content": "ولقد رءاه بالافق المبين",
  },
  {"surah_number": 81, "verse_number": 24, "content": "وما هو على الغيب بضنين"},
  {"surah_number": 81, "verse_number": 25, "content": "وما هو بقول شيطن رجيم"},
  {"surah_number": 81, "verse_number": 26, "content": "فاين تذهبون"},
  {"surah_number": 81, "verse_number": 27, "content": "ان هو الا ذكر للعلمين"},
  {"surah_number": 81, "verse_number": 28, "content": "لمن شاء منكم ان يستقيم"},
  {
    "surah_number": 81,
    "verse_number": 29,
    "content": "وما تشاءون الا ان يشاء الله رب العلمين",
  },
  {"surah_number": 82, "verse_number": 1, "content": "اذا السماء انفطرت"},
  {"surah_number": 82, "verse_number": 2, "content": "واذا الكواكب انتثرت"},
  {"surah_number": 82, "verse_number": 3, "content": "واذا البحار فجرت"},
  {"surah_number": 82, "verse_number": 4, "content": "واذا القبور بعثرت"},
  {"surah_number": 82, "verse_number": 5, "content": "علمت نفس ما قدمت واخرت"},
  {
    "surah_number": 82,
    "verse_number": 6,
    "content": "يـايها الانسن ما غرك بربك الكريم",
  },
  {"surah_number": 82, "verse_number": 7, "content": "الذي خلقك فسوىك فعدلك"},
  {"surah_number": 82, "verse_number": 8, "content": "في اي صورة ما شاء ركبك"},
  {"surah_number": 82, "verse_number": 9, "content": "كلا بل تكذبون بالدين"},
  {"surah_number": 82, "verse_number": 10, "content": "وان عليكم لحفظين"},
  {"surah_number": 82, "verse_number": 11, "content": "كراما كتبين"},
  {"surah_number": 82, "verse_number": 12, "content": "يعلمون ما تفعلون"},
  {"surah_number": 82, "verse_number": 13, "content": "ان الابرار لفي نعيم"},
  {"surah_number": 82, "verse_number": 14, "content": "وان الفجار لفي جحيم"},
  {"surah_number": 82, "verse_number": 15, "content": "يصلونها يوم الدين"},
  {"surah_number": 82, "verse_number": 16, "content": "وما هم عنها بغائبين"},
  {"surah_number": 82, "verse_number": 17, "content": "وما ادرىك ما يوم الدين"},
  {
    "surah_number": 82,
    "verse_number": 18,
    "content": "ثم ما ادرىك ما يوم الدين",
  },
  {
    "surah_number": 82,
    "verse_number": 19,
    "content": "يوم لا تملك نفس لنفس شيـا والامر يومئذ لله",
  },
  {"surah_number": 83, "verse_number": 1, "content": "ويل للمطففين"},
  {
    "surah_number": 83,
    "verse_number": 2,
    "content": "الذين اذا اكتالوا على الناس يستوفون",
  },
  {
    "surah_number": 83,
    "verse_number": 3,
    "content": "واذا كالوهم او وزنوهم يخسرون",
  },
  {
    "surah_number": 83,
    "verse_number": 4,
    "content": "الا يظن اولـئك انهم مبعوثون",
  },
  {"surah_number": 83, "verse_number": 5, "content": "ليوم عظيم"},
  {
    "surah_number": 83,
    "verse_number": 6,
    "content": "يوم يقوم الناس لرب العلمين",
  },
  {
    "surah_number": 83,
    "verse_number": 7,
    "content": "كلا ان كتب الفجار لفي سجين",
  },
  {"surah_number": 83, "verse_number": 8, "content": "وما ادرىك ما سجين"},
  {"surah_number": 83, "verse_number": 9, "content": "كتب مرقوم"},
  {"surah_number": 83, "verse_number": 10, "content": "ويل يومئذ للمكذبين"},
  {
    "surah_number": 83,
    "verse_number": 11,
    "content": "الذين يكذبون بيوم الدين",
  },
  {
    "surah_number": 83,
    "verse_number": 12,
    "content": "وما يكذب به الا كل معتد اثيم",
  },
  {
    "surah_number": 83,
    "verse_number": 13,
    "content": "اذا تتلى عليه ءايتنا قال اسطير الاولين",
  },
  {
    "surah_number": 83,
    "verse_number": 14,
    "content": "كلا بل ران على قلوبهم ما كانوا يكسبون",
  },
  {
    "surah_number": 83,
    "verse_number": 15,
    "content": "كلا انهم عن ربهم يومئذ لمحجوبون",
  },
  {"surah_number": 83, "verse_number": 16, "content": "ثم انهم لصالوا الجحيم"},
  {
    "surah_number": 83,
    "verse_number": 17,
    "content": "ثم يقال هذا الذي كنتم به تكذبون",
  },
  {
    "surah_number": 83,
    "verse_number": 18,
    "content": "كلا ان كتب الابرار لفي عليين",
  },
  {"surah_number": 83, "verse_number": 19, "content": "وما ادرىك ما عليون"},
  {"surah_number": 83, "verse_number": 20, "content": "كتب مرقوم"},
  {"surah_number": 83, "verse_number": 21, "content": "يشهده المقربون"},
  {"surah_number": 83, "verse_number": 22, "content": "ان الابرار لفي نعيم"},
  {"surah_number": 83, "verse_number": 23, "content": "على الارائك ينظرون"},
  {
    "surah_number": 83,
    "verse_number": 24,
    "content": "تعرف في وجوههم نضرة النعيم",
  },
  {"surah_number": 83, "verse_number": 25, "content": "يسقون من رحيق مختوم"},
  {
    "surah_number": 83,
    "verse_number": 26,
    "content": "ختمه مسك وفي ذلك فليتنافس المتنفسون",
  },
  {"surah_number": 83, "verse_number": 27, "content": "ومزاجه من تسنيم"},
  {"surah_number": 83, "verse_number": 28, "content": "عينا يشرب بها المقربون"},
  {
    "surah_number": 83,
    "verse_number": 29,
    "content": "ان الذين اجرموا كانوا من الذين ءامنوا يضحكون",
  },
  {"surah_number": 83, "verse_number": 30, "content": "واذا مروا بهم يتغامزون"},
  {
    "surah_number": 83,
    "verse_number": 31,
    "content": "واذا انقلبوا الى اهلهم انقلبوا فكهين",
  },
  {
    "surah_number": 83,
    "verse_number": 32,
    "content": "واذا راوهم قالوا ان هـؤلاء لضالون",
  },
  {"surah_number": 83, "verse_number": 33, "content": "وما ارسلوا عليهم حفظين"},
  {
    "surah_number": 83,
    "verse_number": 34,
    "content": "فاليوم الذين ءامنوا من الكفار يضحكون",
  },
  {"surah_number": 83, "verse_number": 35, "content": "على الارائك ينظرون"},
  {
    "surah_number": 83,
    "verse_number": 36,
    "content": "هل ثوب الكفار ما كانوا يفعلون",
  },
  {"surah_number": 84, "verse_number": 1, "content": "اذا السماء انشقت"},
  {"surah_number": 84, "verse_number": 2, "content": "واذنت لربها وحقت"},
  {"surah_number": 84, "verse_number": 3, "content": "واذا الارض مدت"},
  {"surah_number": 84, "verse_number": 4, "content": "والقت ما فيها وتخلت"},
  {"surah_number": 84, "verse_number": 5, "content": "واذنت لربها وحقت"},
  {
    "surah_number": 84,
    "verse_number": 6,
    "content": "يـايها الانسن انك كادح الى ربك كدحا فملقيه",
  },
  {
    "surah_number": 84,
    "verse_number": 7,
    "content": "فاما من اوتي كتبه بيمينه",
  },
  {"surah_number": 84, "verse_number": 8, "content": "فسوف يحاسب حسابا يسيرا"},
  {"surah_number": 84, "verse_number": 9, "content": "وينقلب الى اهله مسرورا"},
  {
    "surah_number": 84,
    "verse_number": 10,
    "content": "واما من اوتي كتبه وراء ظهره",
  },
  {"surah_number": 84, "verse_number": 11, "content": "فسوف يدعوا ثبورا"},
  {"surah_number": 84, "verse_number": 12, "content": "ويصلى سعيرا"},
  {"surah_number": 84, "verse_number": 13, "content": "انه كان في اهله مسرورا"},
  {"surah_number": 84, "verse_number": 14, "content": "انه ظن ان لن يحور"},
  {
    "surah_number": 84,
    "verse_number": 15,
    "content": "بلى ان ربه كان به بصيرا",
  },
  {"surah_number": 84, "verse_number": 16, "content": "فلا اقسم بالشفق"},
  {"surah_number": 84, "verse_number": 17, "content": "واليل وما وسق"},
  {"surah_number": 84, "verse_number": 18, "content": "والقمر اذا اتسق"},
  {"surah_number": 84, "verse_number": 19, "content": "لتركبن طبقا عن طبق"},
  {"surah_number": 84, "verse_number": 20, "content": "فما لهم لا يؤمنون"},
  {
    "surah_number": 84,
    "verse_number": 21,
    "content": "واذا قرئ عليهم القرءان لا يسجدون",
  },
  {"surah_number": 84, "verse_number": 22, "content": "بل الذين كفروا يكذبون"},
  {"surah_number": 84, "verse_number": 23, "content": "والله اعلم بما يوعون"},
  {"surah_number": 84, "verse_number": 24, "content": "فبشرهم بعذاب اليم"},
  {
    "surah_number": 84,
    "verse_number": 25,
    "content": "الا الذين ءامنوا وعملوا الصـلحت لهم اجر غير ممنون",
  },
  {"surah_number": 85, "verse_number": 1, "content": "والسماء ذات البروج"},
  {"surah_number": 85, "verse_number": 2, "content": "واليوم الموعود"},
  {"surah_number": 85, "verse_number": 3, "content": "وشاهد ومشهود"},
  {"surah_number": 85, "verse_number": 4, "content": "قتل اصحب الاخدود"},
  {"surah_number": 85, "verse_number": 5, "content": "النار ذات الوقود"},
  {"surah_number": 85, "verse_number": 6, "content": "اذ هم عليها قعود"},
  {
    "surah_number": 85,
    "verse_number": 7,
    "content": "وهم على ما يفعلون بالمؤمنين شهود",
  },
  {
    "surah_number": 85,
    "verse_number": 8,
    "content": "وما نقموا منهم الا ان يؤمنوا بالله العزيز الحميد",
  },
  {
    "surah_number": 85,
    "verse_number": 9,
    "content": "الذي له ملك السموت والارض والله على كل شيء شهيد",
  },
  {
    "surah_number": 85,
    "verse_number": 10,
    "content":
        "ان الذين فتنوا المؤمنين والمؤمنت ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب الحريق",
  },
  {
    "surah_number": 85,
    "verse_number": 11,
    "content":
        "ان الذين ءامنوا وعملوا الصـلحت لهم جنـت تجري من تحتها الانهر ذلك الفوز الكبير",
  },
  {"surah_number": 85, "verse_number": 12, "content": "ان بطش ربك لشديد"},
  {"surah_number": 85, "verse_number": 13, "content": "انه هو يبدئ ويعيد"},
  {"surah_number": 85, "verse_number": 14, "content": "وهو الغفور الودود"},
  {"surah_number": 85, "verse_number": 15, "content": "ذو العرش المجيد"},
  {"surah_number": 85, "verse_number": 16, "content": "فعال لما يريد"},
  {"surah_number": 85, "verse_number": 17, "content": "هل اتىك حديث الجنود"},
  {"surah_number": 85, "verse_number": 18, "content": "فرعون وثمود"},
  {
    "surah_number": 85,
    "verse_number": 19,
    "content": "بل الذين كفروا في تكذيب",
  },
  {"surah_number": 85, "verse_number": 20, "content": "والله من ورائهم محيط"},
  {"surah_number": 85, "verse_number": 21, "content": "بل هو قرءان مجيد"},
  {"surah_number": 85, "verse_number": 22, "content": "في لوح محفوظ"},
  {"surah_number": 86, "verse_number": 1, "content": "والسماء والطارق"},
  {"surah_number": 86, "verse_number": 2, "content": "وما ادرىك ما الطارق"},
  {"surah_number": 86, "verse_number": 3, "content": "النجم الثاقب"},
  {
    "surah_number": 86,
    "verse_number": 4,
    "content": "ان كل نفس لما عليها حافظ",
  },
  {"surah_number": 86, "verse_number": 5, "content": "فلينظر الانسن مم خلق"},
  {"surah_number": 86, "verse_number": 6, "content": "خلق من ماء دافق"},
  {
    "surah_number": 86,
    "verse_number": 7,
    "content": "يخرج من بين الصلب والترائب",
  },
  {"surah_number": 86, "verse_number": 8, "content": "انه على رجعه لقادر"},
  {"surah_number": 86, "verse_number": 9, "content": "يوم تبلى السرائر"},
  {"surah_number": 86, "verse_number": 10, "content": "فما له من قوة ولا ناصر"},
  {"surah_number": 86, "verse_number": 11, "content": "والسماء ذات الرجع"},
  {"surah_number": 86, "verse_number": 12, "content": "والارض ذات الصدع"},
  {"surah_number": 86, "verse_number": 13, "content": "انه لقول فصل"},
  {"surah_number": 86, "verse_number": 14, "content": "وما هو بالهزل"},
  {"surah_number": 86, "verse_number": 15, "content": "انهم يكيدون كيدا"},
  {"surah_number": 86, "verse_number": 16, "content": "واكيد كيدا"},
  {
    "surah_number": 86,
    "verse_number": 17,
    "content": "فمهل الكفرين امهلهم رويدا",
  },
  {"surah_number": 87, "verse_number": 1, "content": "سبح اسم ربك الاعلى"},
  {"surah_number": 87, "verse_number": 2, "content": "الذي خلق فسوى"},
  {"surah_number": 87, "verse_number": 3, "content": "والذي قدر فهدى"},
  {"surah_number": 87, "verse_number": 4, "content": "والذي اخرج المرعى"},
  {"surah_number": 87, "verse_number": 5, "content": "فجعله غثاء احوى"},
  {"surah_number": 87, "verse_number": 6, "content": "سنقرئك فلا تنسى"},
  {
    "surah_number": 87,
    "verse_number": 7,
    "content": "الا ما شاء الله انه يعلم الجهر وما يخفى",
  },
  {"surah_number": 87, "verse_number": 8, "content": "ونيسرك لليسرى"},
  {"surah_number": 87, "verse_number": 9, "content": "فذكر ان نفعت الذكرى"},
  {"surah_number": 87, "verse_number": 10, "content": "سيذكر من يخشى"},
  {"surah_number": 87, "verse_number": 11, "content": "ويتجنبها الاشقى"},
  {"surah_number": 87, "verse_number": 12, "content": "الذي يصلى النار الكبرى"},
  {
    "surah_number": 87,
    "verse_number": 13,
    "content": "ثم لا يموت فيها ولا يحيى",
  },
  {"surah_number": 87, "verse_number": 14, "content": "قد افلح من تزكى"},
  {"surah_number": 87, "verse_number": 15, "content": "وذكر اسم ربه فصلى"},
  {
    "surah_number": 87,
    "verse_number": 16,
    "content": "بل تؤثرون الحيوة الدنيا",
  },
  {"surah_number": 87, "verse_number": 17, "content": "والاخرة خير وابقى"},
  {
    "surah_number": 87,
    "verse_number": 18,
    "content": "ان هذا لفي الصحف الاولى",
  },
  {"surah_number": 87, "verse_number": 19, "content": "صحف ابرهيم وموسى"},
  {"surah_number": 88, "verse_number": 1, "content": "هل اتىك حديث الغشية"},
  {"surah_number": 88, "verse_number": 2, "content": "وجوه يومئذ خشعة"},
  {"surah_number": 88, "verse_number": 3, "content": "عاملة ناصبة"},
  {"surah_number": 88, "verse_number": 4, "content": "تصلى نارا حامية"},
  {"surah_number": 88, "verse_number": 5, "content": "تسقى من عين ءانية"},
  {
    "surah_number": 88,
    "verse_number": 6,
    "content": "ليس لهم طعام الا من ضريع",
  },
  {"surah_number": 88, "verse_number": 7, "content": "لا يسمن ولا يغني من جوع"},
  {"surah_number": 88, "verse_number": 8, "content": "وجوه يومئذ ناعمة"},
  {"surah_number": 88, "verse_number": 9, "content": "لسعيها راضية"},
  {"surah_number": 88, "verse_number": 10, "content": "في جنة عالية"},
  {"surah_number": 88, "verse_number": 11, "content": "لا تسمع فيها لغية"},
  {"surah_number": 88, "verse_number": 12, "content": "فيها عين جارية"},
  {"surah_number": 88, "verse_number": 13, "content": "فيها سرر مرفوعة"},
  {"surah_number": 88, "verse_number": 14, "content": "واكواب موضوعة"},
  {"surah_number": 88, "verse_number": 15, "content": "ونمارق مصفوفة"},
  {"surah_number": 88, "verse_number": 16, "content": "وزرابي مبثوثة"},
  {
    "surah_number": 88,
    "verse_number": 17,
    "content": "افلا ينظرون الى الابل كيف خلقت",
  },
  {"surah_number": 88, "verse_number": 18, "content": "والى السماء كيف رفعت"},
  {"surah_number": 88, "verse_number": 19, "content": "والى الجبال كيف نصبت"},
  {"surah_number": 88, "verse_number": 20, "content": "والى الارض كيف سطحت"},
  {"surah_number": 88, "verse_number": 21, "content": "فذكر انما انت مذكر"},
  {"surah_number": 88, "verse_number": 22, "content": "لست عليهم بمصيطر"},
  {"surah_number": 88, "verse_number": 23, "content": "الا من تولى وكفر"},
  {
    "surah_number": 88,
    "verse_number": 24,
    "content": "فيعذبه الله العذاب الاكبر",
  },
  {"surah_number": 88, "verse_number": 25, "content": "ان الينا ايابهم"},
  {"surah_number": 88, "verse_number": 26, "content": "ثم ان علينا حسابهم"},
  {"surah_number": 89, "verse_number": 1, "content": "والفجر"},
  {"surah_number": 89, "verse_number": 2, "content": "وليال عشر"},
  {"surah_number": 89, "verse_number": 3, "content": "والشفع والوتر"},
  {"surah_number": 89, "verse_number": 4, "content": "واليل اذا يسر"},
  {"surah_number": 89, "verse_number": 5, "content": "هل في ذلك قسم لذي حجر"},
  {"surah_number": 89, "verse_number": 6, "content": "الم تر كيف فعل ربك بعاد"},
  {"surah_number": 89, "verse_number": 7, "content": "ارم ذات العماد"},
  {
    "surah_number": 89,
    "verse_number": 8,
    "content": "التي لم يخلق مثلها في البلد",
  },
  {
    "surah_number": 89,
    "verse_number": 9,
    "content": "وثمود الذين جابوا الصخر بالواد",
  },
  {"surah_number": 89, "verse_number": 10, "content": "وفرعون ذي الاوتاد"},
  {"surah_number": 89, "verse_number": 11, "content": "الذين طغوا في البلد"},
  {"surah_number": 89, "verse_number": 12, "content": "فاكثروا فيها الفساد"},
  {"surah_number": 89, "verse_number": 13, "content": "فصب عليهم ربك سوط عذاب"},
  {"surah_number": 89, "verse_number": 14, "content": "ان ربك لبالمرصاد"},
  {
    "surah_number": 89,
    "verse_number": 15,
    "content": "فاما الانسن اذا ما ابتلىه ربه فاكرمه ونعمه فيقول ربي اكرمن",
  },
  {
    "surah_number": 89,
    "verse_number": 16,
    "content": "واما اذا ما ابتلىه فقدر عليه رزقه فيقول ربي اهنن",
  },
  {
    "surah_number": 89,
    "verse_number": 17,
    "content": "كلا بل لا تكرمون اليتيم",
  },
  {
    "surah_number": 89,
    "verse_number": 18,
    "content": "ولا تحـضون على طعام المسكين",
  },
  {
    "surah_number": 89,
    "verse_number": 19,
    "content": "وتاكلون التراث اكلا لما",
  },
  {"surah_number": 89, "verse_number": 20, "content": "وتحبون المال حبا جما"},
  {
    "surah_number": 89,
    "verse_number": 21,
    "content": "كلا اذا دكت الارض دكا دكا",
  },
  {
    "surah_number": 89,
    "verse_number": 22,
    "content": "وجاء ربك والملك صفا صفا",
  },
  {
    "surah_number": 89,
    "verse_number": 23,
    "content": "وجايء يومئذ بجهنم يومئذ يتذكر الانسن وانى له الذكرى",
  },
  {
    "surah_number": 89,
    "verse_number": 24,
    "content": "يقول يليتني قدمت لحياتي",
  },
  {
    "surah_number": 89,
    "verse_number": 25,
    "content": "فيومئذ لا يعذب عذابه احد",
  },
  {"surah_number": 89, "verse_number": 26, "content": "ولا يوثق وثاقه احد"},
  {"surah_number": 89, "verse_number": 27, "content": "يـايتها النفس المطمئنة"},
  {
    "surah_number": 89,
    "verse_number": 28,
    "content": "ارجعي الى ربك راضية مرضية",
  },
  {"surah_number": 89, "verse_number": 29, "content": "فادخلي في عبدي"},
  {"surah_number": 89, "verse_number": 30, "content": "وادخلي جنتي"},
  {"surah_number": 90, "verse_number": 1, "content": "لا اقسم بهذا البلد"},
  {"surah_number": 90, "verse_number": 2, "content": "وانت حل بهذا البلد"},
  {"surah_number": 90, "verse_number": 3, "content": "ووالد وما ولد"},
  {"surah_number": 90, "verse_number": 4, "content": "لقد خلقنا الانسن في كبد"},
  {
    "surah_number": 90,
    "verse_number": 5,
    "content": "ايحسب ان لن يقدر عليه احد",
  },
  {"surah_number": 90, "verse_number": 6, "content": "يقول اهلكت مالا لبدا"},
  {"surah_number": 90, "verse_number": 7, "content": "ايحسب ان لم يره احد"},
  {"surah_number": 90, "verse_number": 8, "content": "الم نجعل له عينين"},
  {"surah_number": 90, "verse_number": 9, "content": "ولسانا وشفتين"},
  {"surah_number": 90, "verse_number": 10, "content": "وهدينه النجدين"},
  {"surah_number": 90, "verse_number": 11, "content": "فلا اقتحم العقبة"},
  {"surah_number": 90, "verse_number": 12, "content": "وما ادرىك ما العقبة"},
  {"surah_number": 90, "verse_number": 13, "content": "فك رقبة"},
  {
    "surah_number": 90,
    "verse_number": 14,
    "content": "او اطعم في يوم ذي مسغبة",
  },
  {"surah_number": 90, "verse_number": 15, "content": "يتيما ذا مقربة"},
  {"surah_number": 90, "verse_number": 16, "content": "او مسكينا ذا متربة"},
  {
    "surah_number": 90,
    "verse_number": 17,
    "content": "ثم كان من الذين ءامنوا وتواصوا بالصبر وتواصوا بالمرحمة",
  },
  {"surah_number": 90, "verse_number": 18, "content": "اولـئك اصحب الميمنة"},
  {
    "surah_number": 90,
    "verse_number": 19,
    "content": "والذين كفروا بـايتنا هم اصحب المشـمة",
  },
  {"surah_number": 90, "verse_number": 20, "content": "عليهم نار مؤصدة"},
  {"surah_number": 91, "verse_number": 1, "content": "والشمس وضحىها"},
  {"surah_number": 91, "verse_number": 2, "content": "والقمر اذا تلىها"},
  {"surah_number": 91, "verse_number": 3, "content": "والنهار اذا جلىها"},
  {"surah_number": 91, "verse_number": 4, "content": "واليل اذا يغشىها"},
  {"surah_number": 91, "verse_number": 5, "content": "والسماء وما بنىها"},
  {"surah_number": 91, "verse_number": 6, "content": "والارض وما طحىها"},
  {"surah_number": 91, "verse_number": 7, "content": "ونفس وما سوىها"},
  {"surah_number": 91, "verse_number": 8, "content": "فالهمها فجورها وتقوىها"},
  {"surah_number": 91, "verse_number": 9, "content": "قد افلح من زكىها"},
  {"surah_number": 91, "verse_number": 10, "content": "وقد خاب من دسىها"},
  {"surah_number": 91, "verse_number": 11, "content": "كذبت ثمود بطغوىها"},
  {"surah_number": 91, "verse_number": 12, "content": "اذ انبعث اشقىها"},
  {
    "surah_number": 91,
    "verse_number": 13,
    "content": "فقال لهم رسول الله ناقة الله وسقيها",
  },
  {
    "surah_number": 91,
    "verse_number": 14,
    "content": "فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسوىها",
  },
  {"surah_number": 91, "verse_number": 15, "content": "ولا يخاف عقبها"},
  {"surah_number": 92, "verse_number": 1, "content": "واليل اذا يغشى"},
  {"surah_number": 92, "verse_number": 2, "content": "والنهار اذا تجلى"},
  {"surah_number": 92, "verse_number": 3, "content": "وما خلق الذكر والانثى"},
  {"surah_number": 92, "verse_number": 4, "content": "ان سعيكم لشتى"},
  {"surah_number": 92, "verse_number": 5, "content": "فاما من اعطى واتقى"},
  {"surah_number": 92, "verse_number": 6, "content": "وصدق بالحسنى"},
  {"surah_number": 92, "verse_number": 7, "content": "فسنيسره لليسرى"},
  {"surah_number": 92, "verse_number": 8, "content": "واما من بخل واستغنى"},
  {"surah_number": 92, "verse_number": 9, "content": "وكذب بالحسنى"},
  {"surah_number": 92, "verse_number": 10, "content": "فسنيسره للعسرى"},
  {
    "surah_number": 92,
    "verse_number": 11,
    "content": "وما يغني عنه ماله اذا تردى",
  },
  {"surah_number": 92, "verse_number": 12, "content": "ان علينا للهدى"},
  {"surah_number": 92, "verse_number": 13, "content": "وان لنا للاخرة والاولى"},
  {"surah_number": 92, "verse_number": 14, "content": "فانذرتكم نارا تلظى"},
  {"surah_number": 92, "verse_number": 15, "content": "لا يصلىها الا الاشقى"},
  {"surah_number": 92, "verse_number": 16, "content": "الذي كذب وتولى"},
  {"surah_number": 92, "verse_number": 17, "content": "وسيجنبها الاتقى"},
  {"surah_number": 92, "verse_number": 18, "content": "الذي يؤتي ماله يتزكى"},
  {
    "surah_number": 92,
    "verse_number": 19,
    "content": "وما لاحد عنده من نعمة تجزى",
  },
  {
    "surah_number": 92,
    "verse_number": 20,
    "content": "الا ابتغاء وجه ربه الاعلى",
  },
  {"surah_number": 92, "verse_number": 21, "content": "ولسوف يرضى"},
  {"surah_number": 93, "verse_number": 1, "content": "والضحى"},
  {"surah_number": 93, "verse_number": 2, "content": "واليل اذا سجى"},
  {"surah_number": 93, "verse_number": 3, "content": "ما ودعك ربك وما قلى"},
  {
    "surah_number": 93,
    "verse_number": 4,
    "content": "وللاخرة خير لك من الاولى",
  },
  {"surah_number": 93, "verse_number": 5, "content": "ولسوف يعطيك ربك فترضى"},
  {"surah_number": 93, "verse_number": 6, "content": "الم يجدك يتيما فـاوى"},
  {"surah_number": 93, "verse_number": 7, "content": "ووجدك ضالا فهدى"},
  {"surah_number": 93, "verse_number": 8, "content": "ووجدك عائلا فاغنى"},
  {"surah_number": 93, "verse_number": 9, "content": "فاما اليتيم فلا تقهر"},
  {"surah_number": 93, "verse_number": 10, "content": "واما السائل فلا تنهر"},
  {"surah_number": 93, "verse_number": 11, "content": "واما بنعمة ربك فحدث"},
  {"surah_number": 94, "verse_number": 1, "content": "الم نشرح لك صدرك"},
  {"surah_number": 94, "verse_number": 2, "content": "ووضعنا عنك وزرك"},
  {"surah_number": 94, "verse_number": 3, "content": "الذي انقض ظهرك"},
  {"surah_number": 94, "verse_number": 4, "content": "ورفعنا لك ذكرك"},
  {"surah_number": 94, "verse_number": 5, "content": "فان مع العسر يسرا"},
  {"surah_number": 94, "verse_number": 6, "content": "ان مع العسر يسرا"},
  {"surah_number": 94, "verse_number": 7, "content": "فاذا فرغت فانصب"},
  {"surah_number": 94, "verse_number": 8, "content": "والى ربك فارغب"},
  {"surah_number": 95, "verse_number": 1, "content": "والتين والزيتون"},
  {"surah_number": 95, "verse_number": 2, "content": "وطور سينين"},
  {"surah_number": 95, "verse_number": 3, "content": "وهذا البلد الامين"},
  {
    "surah_number": 95,
    "verse_number": 4,
    "content": "لقد خلقنا الانسن في احسن تقويم",
  },
  {"surah_number": 95, "verse_number": 5, "content": "ثم رددنه اسفل سفلين"},
  {
    "surah_number": 95,
    "verse_number": 6,
    "content": "الا الذين ءامنوا وعملوا الصـلحت فلهم اجر غير ممنون",
  },
  {"surah_number": 95, "verse_number": 7, "content": "فما يكذبك بعد بالدين"},
  {"surah_number": 95, "verse_number": 8, "content": "اليس الله باحكم الحكمين"},
  {"surah_number": 96, "verse_number": 1, "content": "اقرا باسم ربك الذي خلق"},
  {"surah_number": 96, "verse_number": 2, "content": "خلق الانسن من علق"},
  {"surah_number": 96, "verse_number": 3, "content": "اقرا وربك الاكرم"},
  {"surah_number": 96, "verse_number": 4, "content": "الذي علم بالقلم"},
  {"surah_number": 96, "verse_number": 5, "content": "علم الانسن ما لم يعلم"},
  {"surah_number": 96, "verse_number": 6, "content": "كلا ان الانسن ليطغى"},
  {"surah_number": 96, "verse_number": 7, "content": "ان رءاه استغنى"},
  {"surah_number": 96, "verse_number": 8, "content": "ان الى ربك الرجعى"},
  {"surah_number": 96, "verse_number": 9, "content": "ارءيت الذي ينهى"},
  {"surah_number": 96, "verse_number": 10, "content": "عبدا اذا صلى"},
  {"surah_number": 96, "verse_number": 11, "content": "ارءيت ان كان على الهدى"},
  {"surah_number": 96, "verse_number": 12, "content": "او امر بالتقوى"},
  {"surah_number": 96, "verse_number": 13, "content": "ارءيت ان كذب وتولى"},
  {"surah_number": 96, "verse_number": 14, "content": "الم يعلم بان الله يرى"},
  {
    "surah_number": 96,
    "verse_number": 15,
    "content": "كلا لئن لم ينته لنسفعا بالناصية",
  },
  {"surah_number": 96, "verse_number": 16, "content": "ناصية كذبة خاطئة"},
  {"surah_number": 96, "verse_number": 17, "content": "فليدع ناديه"},
  {"surah_number": 96, "verse_number": 18, "content": "سندع الزبانية"},
  {
    "surah_number": 96,
    "verse_number": 19,
    "content": "كلا لا تطعه واسجد واقترب",
  },
  {
    "surah_number": 97,
    "verse_number": 1,
    "content": "انا انزلنه في ليلة القدر",
  },
  {"surah_number": 97, "verse_number": 2, "content": "وما ادرىك ما ليلة القدر"},
  {
    "surah_number": 97,
    "verse_number": 3,
    "content": "ليلة القدر خير من الف شهر",
  },
  {
    "surah_number": 97,
    "verse_number": 4,
    "content": "تنزل الملـئكة والروح فيها باذن ربهم من كل امر",
  },
  {"surah_number": 97, "verse_number": 5, "content": "سلم هي حتى مطلع الفجر"},
  {
    "surah_number": 98,
    "verse_number": 1,
    "content":
        "لم يكن الذين كفروا من اهل الكتب والمشركين منفكين حتى تاتيهم البينة",
  },
  {
    "surah_number": 98,
    "verse_number": 2,
    "content": "رسول من الله يتلوا صحفا مطهرة",
  },
  {"surah_number": 98, "verse_number": 3, "content": "فيها كتب قيمة"},
  {
    "surah_number": 98,
    "verse_number": 4,
    "content": "وما تفرق الذين اوتوا الكتب الا من بعد ما جاءتهم البينة",
  },
  {
    "surah_number": 98,
    "verse_number": 5,
    "content":
        "وما امروا الا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاة ويؤتوا الزكوة وذلك دين القيمة",
  },
  {
    "surah_number": 98,
    "verse_number": 6,
    "content":
        "ان الذين كفروا من اهل الكتب والمشركين في نار جهنم خلدين فيها اولـئك هم شر البرية",
  },
  {
    "surah_number": 98,
    "verse_number": 7,
    "content": "ان الذين ءامنوا وعملوا الصـلحت اولـئك هم خير البرية",
  },
  {
    "surah_number": 98,
    "verse_number": 8,
    "content":
        "جزاؤهم عند ربهم جنـت عدن تجري من تحتها الانهر خلدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك لمن خشي ربه",
  },
  {"surah_number": 99, "verse_number": 1, "content": "اذا زلزلت الارض زلزالها"},
  {"surah_number": 99, "verse_number": 2, "content": "واخرجت الارض اثقالها"},
  {"surah_number": 99, "verse_number": 3, "content": "وقال الانسن ما لها"},
  {"surah_number": 99, "verse_number": 4, "content": "يومئذ تحدث اخبارها"},
  {"surah_number": 99, "verse_number": 5, "content": "بان ربك اوحى لها"},
  {
    "surah_number": 99,
    "verse_number": 6,
    "content": "يومئذ يصدر الناس اشتاتا ليروا اعملهم",
  },
  {
    "surah_number": 99,
    "verse_number": 7,
    "content": "فمن يعمل مثقال ذرة خيرا يره",
  },
  {
    "surah_number": 99,
    "verse_number": 8,
    "content": "ومن يعمل مثقال ذرة شرا يره",
  },
  {"surah_number": 100, "verse_number": 1, "content": "والعديت ضبحا"},
  {"surah_number": 100, "verse_number": 2, "content": "فالموريت قدحا"},
  {"surah_number": 100, "verse_number": 3, "content": "فالمغيرت صبحا"},
  {"surah_number": 100, "verse_number": 4, "content": "فاثرن به نقعا"},
  {"surah_number": 100, "verse_number": 5, "content": "فوسطن به جمعا"},
  {"surah_number": 100, "verse_number": 6, "content": "ان الانسن لربه لكنود"},
  {"surah_number": 100, "verse_number": 7, "content": "وانه على ذلك لشهيد"},
  {"surah_number": 100, "verse_number": 8, "content": "وانه لحب الخير لشديد"},
  {
    "surah_number": 100,
    "verse_number": 9,
    "content": "افلا يعلم اذا بعثر ما في القبور",
  },
  {"surah_number": 100, "verse_number": 10, "content": "وحصل ما في الصدور"},
  {
    "surah_number": 100,
    "verse_number": 11,
    "content": "ان ربهم بهم يومئذ لخبير",
  },
  {"surah_number": 101, "verse_number": 1, "content": "القارعة"},
  {"surah_number": 101, "verse_number": 2, "content": "ما القارعة"},
  {"surah_number": 101, "verse_number": 3, "content": "وما ادرىك ما القارعة"},
  {
    "surah_number": 101,
    "verse_number": 4,
    "content": "يوم يكون الناس كالفراش المبثوث",
  },
  {
    "surah_number": 101,
    "verse_number": 5,
    "content": "وتكون الجبال كالعهن المنفوش",
  },
  {"surah_number": 101, "verse_number": 6, "content": "فاما من ثقلت موزينه"},
  {"surah_number": 101, "verse_number": 7, "content": "فهو في عيشة راضية"},
  {"surah_number": 101, "verse_number": 8, "content": "واما من خفت موزينه"},
  {"surah_number": 101, "verse_number": 9, "content": "فامه هاوية"},
  {"surah_number": 101, "verse_number": 10, "content": "وما ادرىك ما هيه"},
  {"surah_number": 101, "verse_number": 11, "content": "نار حامية"},
  {"surah_number": 102, "verse_number": 1, "content": "الهىكم التكاثر"},
  {"surah_number": 102, "verse_number": 2, "content": "حتى زرتم المقابر"},
  {"surah_number": 102, "verse_number": 3, "content": "كلا سوف تعلمون"},
  {"surah_number": 102, "verse_number": 4, "content": "ثم كلا سوف تعلمون"},
  {
    "surah_number": 102,
    "verse_number": 5,
    "content": "كلا لو تعلمون علم اليقين",
  },
  {"surah_number": 102, "verse_number": 6, "content": "لترون الجحيم"},
  {"surah_number": 102, "verse_number": 7, "content": "ثم لترونها عين اليقين"},
  {
    "surah_number": 102,
    "verse_number": 8,
    "content": "ثم لتسـلن يومئذ عن النعيم",
  },
  {"surah_number": 103, "verse_number": 1, "content": "والعصر"},
  {"surah_number": 103, "verse_number": 2, "content": "ان الانسن لفي خسر"},
  {
    "surah_number": 103,
    "verse_number": 3,
    "content": "الا الذين ءامنوا وعملوا الصـلحت وتواصوا بالحق وتواصوا بالصبر",
  },
  {"surah_number": 104, "verse_number": 1, "content": "ويل لكل همزة لمزة"},
  {"surah_number": 104, "verse_number": 2, "content": "الذي جمع مالا وعدده"},
  {"surah_number": 104, "verse_number": 3, "content": "يحسب ان ماله اخلده"},
  {"surah_number": 104, "verse_number": 4, "content": "كلا لينبذن في الحطمة"},
  {"surah_number": 104, "verse_number": 5, "content": "وما ادرىك ما الحطمة"},
  {"surah_number": 104, "verse_number": 6, "content": "نار الله الموقدة"},
  {"surah_number": 104, "verse_number": 7, "content": "التي تطلع على الافـدة"},
  {"surah_number": 104, "verse_number": 8, "content": "انها عليهم مؤصدة"},
  {"surah_number": 104, "verse_number": 9, "content": "في عمد ممددة"},
  {
    "surah_number": 105,
    "verse_number": 1,
    "content": "الم تر كيف فعل ربك باصحب الفيل",
  },
  {
    "surah_number": 105,
    "verse_number": 2,
    "content": "الم يجعل كيدهم في تضليل",
  },
  {
    "surah_number": 105,
    "verse_number": 3,
    "content": "وارسل عليهم طيرا ابابيل",
  },
  {"surah_number": 105, "verse_number": 4, "content": "ترميهم بحجارة من سجيل"},
  {"surah_number": 105, "verse_number": 5, "content": "فجعلهم كعصف ماكول"},
  {"surah_number": 106, "verse_number": 1, "content": "لايلف قريش"},
  {
    "surah_number": 106,
    "verse_number": 2,
    "content": "الفهم رحلة الشتاء والصيف",
  },
  {"surah_number": 106, "verse_number": 3, "content": "فليعبدوا رب هذا البيت"},
  {
    "surah_number": 106,
    "verse_number": 4,
    "content": "الذي اطعمهم من جوع وءامنهم من خوف",
  },
  {"surah_number": 107, "verse_number": 1, "content": "ارءيت الذي يكذب بالدين"},
  {"surah_number": 107, "verse_number": 2, "content": "فذلك الذي يدع اليتيم"},
  {
    "surah_number": 107,
    "verse_number": 3,
    "content": "ولا يحض على طعام المسكين",
  },
  {"surah_number": 107, "verse_number": 4, "content": "فويل للمصلين"},
  {
    "surah_number": 107,
    "verse_number": 5,
    "content": "الذين هم عن صلاتهم ساهون",
  },
  {"surah_number": 107, "verse_number": 6, "content": "الذين هم يراءون"},
  {"surah_number": 107, "verse_number": 7, "content": "ويمنعون الماعون"},
  {"surah_number": 108, "verse_number": 1, "content": "انا اعطينك الكوثر"},
  {"surah_number": 108, "verse_number": 2, "content": "فصل لربك وانحر"},
  {"surah_number": 108, "verse_number": 3, "content": "ان شانئك هو الابتر"},
  {"surah_number": 109, "verse_number": 1, "content": "قل يـايها الكفرون"},
  {"surah_number": 109, "verse_number": 2, "content": "لا اعبد ما تعبدون"},
  {"surah_number": 109, "verse_number": 3, "content": "ولا انتم عبدون ما اعبد"},
  {"surah_number": 109, "verse_number": 4, "content": "ولا انا عابد ما عبدتم"},
  {"surah_number": 109, "verse_number": 5, "content": "ولا انتم عبدون ما اعبد"},
  {"surah_number": 109, "verse_number": 6, "content": "لكم دينكم ولي دين"},
  {
    "surah_number": 110,
    "verse_number": 1,
    "content": "اذا جاء نصر الله والفتح",
  },
  {
    "surah_number": 110,
    "verse_number": 2,
    "content": "ورايت الناس يدخلون في دين الله افواجا",
  },
  {
    "surah_number": 110,
    "verse_number": 3,
    "content": "فسبح بحمد ربك واستغفره انه كان توابا",
  },
  {"surah_number": 111, "verse_number": 1, "content": "تبت يدا ابي لهب وتب"},
  {
    "surah_number": 111,
    "verse_number": 2,
